QT_ISI(16,{"2215":["(Khidhir berkata, \"Bukankah sudah kukatakan kepadamu, bahwa sesungguhnya kamu tidak akan dapat sabar bersamaku)\" hal ini sebagai teguran yang kedua bagimu di samping teguran yang pertama tadi, dalam hal ini alasanmu tidak dapat diterima.",[["۞ قَالَ","Dia berkata"],["أَلَمْ","tidak"],["أَقُل","aku cakap"],["لَّكَ","kepada kamu"],["إِنَّكَ","bahawa kamu"],["لَن","tidak pernah"],["تَسْتَطِيعَ","akan dapat"],["مَعِىَ","dengan aku"],["صَبْرًۭا","(mempunyai) kesabaran"]]],"2216":["Oleh sebab itu maka (berkatalah Musa, \"Jika aku bertanya kepadamu tentang sesuatu sesudah ini) sesudah kali ini (maka janganlah kamu menemani aku lagi) artinya janganlah kamu mengikuti aku lagi (sesungguhnya kamu telah cukup memberikan kepadaku) dapat dibaca Ladunii atau Ladunnii, artinya dari pihakku (udzur\") alasan agar aku berpisah denganmu.",[["قَالَ","Dia berkata"],["إِن","Jika"],["سَأَلْتُكَ","aku tanya kamu"],["عَن","tentang"],["شَىْءٍۭ","sesuatu"],["بَعْدَهَا","selepas itu"],["فَلَا","maka (buat) jangan"],["تُصَـٰحِبْنِى ۖ","kekalkan aku sebagai peneman"],["قَدْ","Sesungguhnya"],["بَلَغْتَ","kamu telah sampai"],["مِن","daripada aku"],["لَّدُنِّى","daripada aku"],["عُذْرًۭا","satu alasan"]]],"2217":["(Maka keduanya berjalan; hingga tatkala keduanya sampai kepada penduduk suatu negeri) yaitu kota Inthakiyah (mereka meminta dijamu kepada penduduk negeri itu) keduanya meminta kepada mereka supaya memberi makan kepadanya sebagaimana layaknya tamu (tetapi penduduk negeri itu tidak mau menjamu mereka, kemudian keduanya mendapatkan dalam negeri itu dinding rumah) yang tingginya mencapai seratus hasta (yang hampir roboh) mengingat kemiringannya yang sangat (maka Khidhir menegakkan dinding itu) dengan tangannya sendiri (Musa berkata) kepadanya, (\"Jika kamu mau, niscaya kamu mengambil) menurut suatu qiraat dibaca Laittakhadzta (upah untuk itu)\" yakni persenan karena mereka tidak mau menjamu kita, sedangkan kita sangat membutuhkan makanan.",[["فَٱنطَلَقَا","Jadi mereka berangkat"],["حَتَّىٰٓ","sehingga"],["إِذَآ","apabila"],["أَتَيَآ","mereka datang"],["أَهْلَ","(kepada) orang ramai"],["قَرْيَةٍ","(dari) sebuah bandar"],["ٱسْتَطْعَمَآ","mereka meminta makanan"],["أَهْلَهَا","(dari) rakyatnya"],["فَأَبَوْا۟","tetapi mereka menolak"],["أَن","kepada"],["يُضَيِّفُوهُمَا","menawarkan mereka layanan"],["فَوَجَدَا","Kemudian mereka mendapati"],["فِيهَا","di dalamnya"],["جِدَارًۭا","sebuah dinding"],["يُرِيدُ","(yang) mahu (ed)"],["أَن","kepada"],["يَنقَضَّ","runtuh"],["فَأَقَامَهُۥ ۖ","jadi dia luruskan"],["قَالَ","Dia berkata"],["لَوْ","Jika"],["شِئْتَ","kamu mahu"],["لَتَّخَذْتَ","sesungguhnya kamu (boleh) mengambil"],["عَلَيْهِ","baginya"],["أَجْرًۭا","bayaran"]]],"2218":["(Khidhir berkata) kepada Nabi Musa, (\"Inilah perpisahan) waktu perpisahan (antara aku dengan kamu). Lafal Baina dimudhafkan kepada hal yang tidak Muta'addi atau berbilang, pengulangan lafal Baina di sini diperbolehkan karena di antara keduanya terdapat huruf 'Athaf Wawu. (Aku akan memberitahukan kepadamu) sebelum perpisahanku denganmu (tujuan perbuatan-perbuatan yang kamu tidak sabar terhadapnya).",[["قَالَ","Dia berkata"],["هَـٰذَا","Ini"],["فِرَاقُ","(sedang) berpisah"],["بَيْنِى","antara aku"],["وَبَيْنِكَ ۚ","dan antara kamu"],["سَأُنَبِّئُكَ","Aku akan maklumkan kepada kamu"],["بِتَأْوِيلِ","daripada (the) tafsiran"],["مَا","apa"],["لَمْ","tidak"],["تَسْتَطِع","kamu mampu"],["عَّلَيْهِ","di atasnya"],["صَبْرًا","(mempunyai) kesabaran"]]],"2219":["(Adapun perahu itu adalah kepunyaan orang-orang miskin) yang jumlahnya ada sepuluh orang (yang bekerja di laut) dengan menyewakannya, mereka menjadikannya sebagai mata pencaharian (dan aku bertujuan merusakkan perahu itu, karena di hadapan mereka) jika mereka kembali, atau di hadapan mereka sekarang ini (ada seorang raja) kafir (yang mengambil tiap-tiap perahu) yang masih baik (secara ghashab) yakni dengan cara merampasnya. Lafal Ghashban dinashabkan karena menjadi Mashdar yang kedudukannya menjelaskan tentang cara pengambilan itu.",[["أَمَّا","Adapun"],["ٱلسَّفِينَةُ","kapal itu"],["فَكَانَتْ","ia adalah"],["لِمَسَـٰكِينَ","daripada orang-orang miskin"],["يَعْمَلُونَ","bekerja"],["فِى","dalam"],["ٱلْبَحْرِ","laut"],["فَأَرَدتُّ","Jadi aku berniat"],["أَنْ","bahawa"],["أَعِيبَهَا","Aku menyebabkan kecacatan (dalam) itu"],["وَكَانَ","(seperti yang ada) adalah"],["وَرَآءَهُم","selepas mereka"],["مَّلِكٌۭ","seorang raja"],["يَأْخُذُ","yang merampas"],["كُلَّ","setiap"],["سَفِينَةٍ","kapal"],["غَصْبًۭا","(dengan) kekerasan"]]],"2220":["(Adapun anak muda itu, kedua orang tuanya adalah orang-orang Mukmin, dan kami khawatir bahwa dia akan mendorong kedua orang tuanya itu kepada kesesatan dan kekafiran), karena sesungguhnya sebagaimana yang telah disebutkan di dalam hadis sahih Muslim, bahwa anak muda itu telah dicap oleh Allah menjadi orang kafir. Dan seandainya ia hidup niscaya dia akan mendorong kedua orang tuanya kepada kekafiran, disebabkan kecintaan keduanya kepadanya, hingga keduanya pasti akan mengikuti jejak anaknya.",[["وَأَمَّا","Dan untuk"],["ٱلْغُلَـٰمُ","budak lelaki itu"],["فَكَانَ","ibu bapanya adalah"],["أَبَوَاهُ","ibu bapanya adalah"],["مُؤْمِنَيْنِ","orang yang beriman"],["فَخَشِينَآ","dan kami takut"],["أَن","bahawa"],["يُرْهِقَهُمَا","dia akan membebankan mereka"],["طُغْيَـٰنًۭا","(oleh) pelanggaran"],["وَكُفْرًۭا","dan kekufuran"]]],"2221":["(Dan kami menghendaki, supaya menggantikan bagi kedua orang tuanya) dapat dibaca Yubaddilahuma atau Yubdilahuma (Rabbnya dengan anak lain yang lebih baik kesuciannya daripada anaknya itu) artinya lebih baik dan lebih bertakwa (dan lebih) daripada anaknya itu (dalam kasih sayangnya) dapat dibaca Ruhman atau Ruhuman, artinya berbakti kepada kedua orang tuanya. Ternyata sesudah itu Allah menggantikan bagi keduanya seorang anak perempuan yang kemudian dikawini oleh seorang nabi, dan dari hasil perkawinannya itu lahirlah seorang nabi. Pada akhirnya Allah memberikan petunjuk kepada suatu umat melalui nabi itu.",[["فَأَرَدْنَآ","Jadi kami berniat"],["أَن","bahawa"],["يُبْدِلَهُمَا","akan berubah untuk mereka"],["رَبُّهُمَا","Tuhan mereka"],["خَيْرًۭا","yang lebih baik"],["مِّنْهُ","daripada dia"],["زَكَوٰةًۭ","(dalam) kesucian"],["وَأَقْرَبَ","dan lebih dekat"],["رُحْمًۭا","(dalam) kasih sayang"]]],"2222":["(Adapun dinding rumah itu adalah kepunyaan dua orang anak muda yang yatim di kota ini, dan di bawahnya ada harta benda simpanan) yakni harta yang terpendam berupa emas dan perak (bagi mereka berdua, sedangkan ayahnya adalah seorang yang saleh) maka dengan kesalehannya itu ia dapat memelihara kedua anaknya dan harta benda bagi keduanya (maka Rabbmu menghendaki agar mereka berdua sampai kepada kedewasaannya) sampai kepada usia dewasa (dan mengeluarkan simpanannya itu, sebagai rahmat dari Rabbmu). Lafal Rahmatan menjadi Maf'ul Lah, sedangkan 'Amilnya adalah lafal Araada (dan bukanlah aku melakukannya itu) yaitu semua hal yang telah disebutkan tadi, yakni melubangi perahu, membunuh anak muda dan mendirikan tembok yang hampir roboh (menurut kemauanku sendiri) berdasarkan keinginanku sendiri, tetapi hal itu kulakukan berdasarkan perintah dan ilham dari Allah. (Demikian itu adalah tujuan perbuatan-perbuatan yang kamu tidak dapat sabar terhadapnya)\" lafal Tasthi' menurut pendapat lain dibaca Isthaa'a dan Istathas'a artinya mampu. Di dalam ayat ini dan ayat-ayat sebelumnya terdapat berbagai macam ungkapan, yaitu terkadang memakai istilah Aradtu (aku menghendaki); terkadang memakai istilah Aradnaa (kami menghendaki), dan terkadang memakai istilah Araada Rabbuka (Rabbmu menghendaki). Hal ini dinamakan Jam'un Bainal Lughataini atau penganekaragaman ungkapan.",[["وَأَمَّا","Dan untuk"],["ٱلْجِدَارُ","dinding"],["فَكَانَ","ia adalah"],["لِغُلَـٰمَيْنِ","untuk dua orang anak yatim piatu"],["يَتِيمَيْنِ","untuk dua orang anak yatim piatu"],["فِى","dalam"],["ٱلْمَدِينَةِ","bandar itu"],["وَكَانَ","dan adalah"],["تَحْتَهُۥ","di bawahnya"],["كَنزٌۭ","harta karun"],["لَّهُمَا","bagi mereka"],["وَكَانَ","dan adalah"],["أَبُوهُمَا","bapa mereka"],["صَـٰلِحًۭا","soleh"],["فَأَرَادَ","Begitu diniatkan"],["رَبُّكَ","Tuhanmu"],["أَن","bahawa"],["يَبْلُغَآ","mereka sampai"],["أَشُدَّهُمَا","kematangan mereka"],["وَيَسْتَخْرِجَا","dan melahirkan"],["كَنزَهُمَا","harta mereka"],["رَحْمَةًۭ","(sebagai) rahmat"],["مِّن","daripada"],["رَّبِّكَ ۚ","Tuhanmu"],["وَمَا","Dan tidak"],["فَعَلْتُهُۥ","Aku melakukannya"],["عَنْ","pada"],["أَمْرِى ۚ","kehendak aku (sendiri)."],["ذَٰلِكَ","Itu"],["تَأْوِيلُ","(ialah) tafsiran"],["مَا","apa"],["لَمْ","tidak"],["تَسْطِع","kamu mampu"],["عَّلَيْهِ","di atasnya"],["صَبْرًۭا","(mempunyai) kesabaran"]]],"2223":["(Dan mereka akan bertanya kepadamu) yakni orang-orang yahudi (tentang Zulkarnain) yang namanya adalah Iskandar; dia bukan seorang Nabi (Katakanlah, \"Aku akan bacakan) aku akan kisahkan (kepada kalian mengenainya) tentang perihalnya (sebagai kisah)\".",[["وَيَسْـَٔلُونَكَ","Dan mereka bertanya kepada kamu"],["عَن","tentang"],["ذِى","Dzul-qarnain"],["ٱلْقَرْنَيْنِ ۖ","Dzul-qarnain"],["قُلْ","Katakanlah"],["سَأَتْلُوا۟","aku akan mengaji"],["عَلَيْكُم","kepada kamu"],["مِّنْهُ","tentang dia"],["ذِكْرًا","sebuah zikir"]]],"2224":["(Sesungguhnya Kami telah memberi kekuasaan kepadanya di muka bumi) dengan memudahkan perjalanan baginya di muka bumi ini (dan Kami telah memberikan kepadanya di dalam menghadapi segala sesuatu) yang ia perlukan (jalan untuk mencapainya) jalan yang dapat mengantarkannya kepada yang dikehendakinya.",[["إِنَّا","Sesungguhnya Kami"],["مَكَّنَّا","[Kami] meneguhkan"],["لَهُۥ","[untuk] dia"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَءَاتَيْنَـٰهُ","dan Kami berikan kepadanya"],["مِن","daripada"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["سَبَبًۭا","satu cara"]]],"2225":["(Maka dia pun menempuh suatu jalan) yakni dia menempuh jalan ke arah Barat.",[["فَأَتْبَعَ","Jadi dia mengikut"],["سَبَبًا","kursus"]]],"2226":["(Hingga apabila dia telah sampai ke tempat terbenamnya matahari) tempat matahari terbenam (dia melihat matahari terbenam di dalam laut yang berlumpur hitam) pengertian terbenamnya matahari di dalam laut hanyalah berdasarkan pandangan mata saja, karena sesungguhnya matahari jauh lebih besar daripada dunia atau bumi (dan dia mendapati di situ) di laut itu (segolongan umat) yang kafir (Kami berkata, \"Hai Zulkarnain!) dengan melalui ilham (Kamu boleh menyiksa) kaum itu dengan cara membunuh mereka (atau boleh berbuat kebaikan terhadap mereka)\" dengan hanya menawan mereka.",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["بَلَغَ","dia sampai"],["مَغْرِبَ","(tempat) setting"],["ٱلشَّمْسِ","(dari) matahari"],["وَجَدَهَا","dia menjumpainya"],["تَغْرُبُ","tetapan"],["فِى","dalam"],["عَيْنٍ","sebuah mata air"],["حَمِئَةٍۢ","(dari) lumpur gelap"],["وَوَجَدَ","dan dia mendapati"],["عِندَهَا","berhampirannya"],["قَوْمًۭا ۗ","sesebuah komuniti"],["قُلْنَا","Kami berkata"],["يَـٰذَا","Wahai Dzulqarnain"],["ٱلْقَرْنَيْنِ","Wahai Dzulqarnain"],["إِمَّآ","sama ada"],["أَن","[bahawa]"],["تُعَذِّبَ","kamu menghukum"],["وَإِمَّآ","atau"],["أَن","[bahawa]"],["تَتَّخِذَ","kamu ambil"],["فِيهِمْ","[dalam] mereka"],["حُسْنًۭا","(dengan) kebaikan"]]],"2227":["(Berkata Zulkarnain, \"Adapun orang yang aniaya) yang melakukan kemusyrikan (maka kami kelak akan mengazabnya) yaitu kami akan membunuhnya (kemudian dia dikembalikan kepada Rabbnya, lalu Rabb mengazabnya dengan azab yang tiada taranya). Lafal Nukran artinya yang sangat keras, yakni azab yang sangat keras di neraka.",[["قَالَ","Dia berkata"],["أَمَّا","Adapun"],["مَن","(satu) siapa"],["ظَلَمَ","kesalahan"],["فَسَوْفَ","kemudian tidak lama lagi"],["نُعَذِّبُهُۥ","kami akan menghukumnya"],["ثُمَّ","Kemudian"],["يُرَدُّ","dia akan dikembalikan"],["إِلَىٰ","kepada"],["رَبِّهِۦ","Tuhannya"],["فَيُعَذِّبُهُۥ","dan Dia akan menghukumnya"],["عَذَابًۭا","(dengan) hukuman"],["نُّكْرًۭا","dahsyat"]]],"2228":["(Adapun orang-orang yang beriman dan beramal saleh, maka baginya pahala yang terbaik) yakni surga; diidhafatkannya lafal Jazaa-an kepada lafal Al Husna mengandung makna penjelasan. Dan menurut qiraat yang lain lafal Jazaa-an dibaca Jazaa-u'; sehubungan dengan bacaan ini Imam Al-Farra' mengatakan bahwa dinashabkannya lafal Jazaa-an karena dianggap sebagai kalimat penafsir, maksudnya bila ditinjau dari segi nisbatnya (dan akan Kami titahkan kepadanya perintah yang mudah dari perintah-perintah Kami)\" maksudnya Kami akan memberikan perintah kepadanya dengan perintah yang mudah untuk ia laksanakan.",[["وَأَمَّا","Tetapi untuk"],["مَنْ","(satu) siapa"],["ءَامَنَ","beriman"],["وَعَمِلَ","dan melakukan"],["صَـٰلِحًۭا","benar (perbuatan)"],["فَلَهُۥ","kemudian untuk dia"],["جَزَآءً","(adalah) ganjaran"],["ٱلْحُسْنَىٰ ۖ","kebaikan"],["وَسَنَقُولُ","Dan kami akan bercakap"],["لَهُۥ","kepadanya"],["مِنْ","daripada"],["أَمْرِنَا","perintah kami"],["يُسْرًۭا","(dengan) mudah"]]],"2229":["(Kemudian ia menempuh jalan yang lain) yaitu menuju ke arah Timur.",[["ثُمَّ","Kemudian"],["أَتْبَعَ","dia ikut"],["سَبَبًا","(a) kursus"]]],"2230":["(Hingga apabila dia telah sampai ke tempat terbitnya matahari) tempat matahari terbit (dia mendapati matahari itu menyinari segolongan umat) mereka adalah bangsa Zunuj atau orang-orang Indian (yang Kami tidak menjadikan bagi mereka dari sinarnya) yaitu dari sinar matahari (sesuatu yang melindunginya) baik berupa pakaian atau pun atap-atap. Karena sesungguhnya tanah tempat mereka tinggal tidak dapat menopang bangunan, dan mereka hanya mempunyai tempat perlindungan berupa liang-liang, di tempat tersebut mereka masuk bila matahari terbit, dan bila matahari telah tinggi baru mereka keluar dari liang-liang itu.",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["بَلَغَ","dia sampai"],["مَطْلِعَ","(tempat) meningkat"],["ٱلشَّمْسِ","(dari) matahari"],["وَجَدَهَا","dan dia menjumpainya"],["تَطْلُعُ","meningkat"],["عَلَىٰ","pada"],["قَوْمٍۢ","sesebuah komuniti"],["لَّمْ","tidak"],["نَجْعَل","Kami buat"],["لَّهُم","bagi mereka"],["مِّن","menentangnya"],["دُونِهَا","menentangnya"],["سِتْرًۭا","mana-mana tempat perlindungan"]]],"2231":["(Demikianlah) perkara itu sebagaimana yang telah Kami ceritakan. (Dan sesungguhnya Kami meliputi terhadap semua apa yang ada padanya) yaitu yang ada pada Zulkarnain berupa alat-alat persenjataan, balatentara dan lain sebagainya (dengan ilmu Kami) yakni Kami mengetahui semuanya.",[["كَذَٰلِكَ","Demikianlah"],["وَقَدْ","Dan sesungguhnya"],["أَحَطْنَا","Kami merangkumi"],["بِمَا","tentang apa"],["لَدَيْهِ","(ada) bersamanya"],["خُبْرًۭا","(daripada) maklumat"]]],"2232":["(Kemudian dia menempuh suatu jalan yang lain lagi).",[["ثُمَّ","Kemudian"],["أَتْبَعَ","dia ikut"],["سَبَبًا","kursus"]]],"2233":["(Hingga apabila dia telah sampai di antara dua buah bendungan) dibaca Saddaini atau Suddaini, dan sesudah kedua bendungan tersebut terdapat dua buah gunung, yaitu di salah satu wilayah negeri Turki. Bendungan raja Iskandar akan dibangun di antara kedua buah bukit itu, sebagaimana yang akan dijelaskan nanti (dia mendapati di hadapan kedua bendungan itu) yakni pada sebelah depan keduanya (suatu kaum yang hampir tidak mengerti pembicaraan) mereka tidak dapat memahami pembicaraan melainkan secara lambat sekali. Menurut qiraat yang lain lafal Yafqahuuna dibaca Yufqihuuna.",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["بَلَغَ","dia sampai"],["بَيْنَ","antara"],["ٱلسَّدَّيْنِ","dua gunung itu"],["وَجَدَ","dia jumpa"],["مِن","selain mereka"],["دُونِهِمَا","selain mereka"],["قَوْمًۭا","sesebuah komuniti"],["لَّا","tidak"],["يَكَادُونَ","siapa yang hampir"],["يَفْقَهُونَ","faham"],["قَوْلًۭا","(nya) ucapannya"]]],"2234":["(Mereka berkata, \"Hai Zulkarnain! Sesungguhnya Yakjuj dan Makjuj itu) dikenal dengan nama Yakjuj dan Makjuj. Kedua nama tersebut merupakan nama 'Ajam bagi dua kabilah, dengan demikian maka I'rabnya tidak menerima tanwin (orang-orang yang membuat kerusakan di muka bumi) mereka gemar merampok dan membuat kerusakan di kala mereka keluar dari sarangnya menuju kami (maka dapatkah kami memberikan sesuatu pembayaran kepadamu) yakni upah berupa harta; dan menurut qiraat yang lain lafal Kharjan dibaca Kharaajan (supaya kamu membuat dinding antara kami dan mereka?)\" tembok penghalang hingga mereka tidak dapat mencapai kami.",[["قَالُوا۟","Mereka berkata"],["يَـٰذَا","Wahai Dzulqarnain"],["ٱلْقَرْنَيْنِ","Wahai Dzulqarnain"],["إِنَّ","Sesungguhnya"],["يَأْجُوجَ","Yajuj"],["وَمَأْجُوجَ","dan Majuj"],["مُفْسِدُونَ","(adalah) perasuah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَهَلْ","Jadi boleh"],["نَجْعَلُ","kita buat"],["لَكَ","bagi kamu"],["خَرْجًا","sesuatu perbelanjaan"],["عَلَىٰٓ","[pada]"],["أَن","bahawa"],["تَجْعَلَ","kamu buat"],["بَيْنَنَا","antara kita"],["وَبَيْنَهُمْ","dan antara mereka"],["سَدًّۭا","penghalang"]]],"2235":["(Zulkarnain berkata, \"Apa yang telah dikuasakan kepadaku) menurut qiraat yang lain lafal Makkannii dibaca Makkananii tanpa diidghamkan (oleh Rabbku terhadapnya) terhadap harta benda dan lain-lainnya (adalah lebih baik) daripada pembayaran kalian yang akan kalian berikan kepadaku, maka aku tidak memerlukannya lagi, dan aku akan membuat tembok penghalang buat kalian sebagai sumbangan suka rela dariku sendiri (maka tolonglah aku dengan kekuatan) apa saja yang aku perlukan dari kalian (agar aku membuatkan dinding antara kamu dan mereka) yakni tembok penghalang yang kuat dan tak dapat ditembus.",[["قَالَ","Dia berkata"],["مَا","Apa"],["مَكَّنِّى","telah meneguhkan aku"],["فِيهِ","[di dalamnya]"],["رَبِّى","Tuhanku"],["خَيْرٌۭ","(lebih) baik"],["فَأَعِينُونِى","tetapi bantu aku"],["بِقُوَّةٍ","dengan kekuatan"],["أَجْعَلْ","aku akan buat"],["بَيْنَكُمْ","antara kamu"],["وَبَيْنَهُمْ","dan antara mereka"],["رَدْمًا","penghalang"]]],"2236":["(Berilah aku potongan-potongan besi)\" sebesar bata kecil yang akan dijadikan sebagai bahan bangunan tembok lalu Zulkarnain membangun tembok penghalang itu daripadanya, dan dia memakai kayu dan batu bara yang dimasukkan di tengah-tengah tembok besi itu. (Sehingga apabila besi itu telah sama rata dengan kedua puncak gunung itu) lafal Shadafaini dapat dibaca Shudufaini dan Shudfaini, artinya sisi bagian puncak kedua bukit itu telah rata dengan bangunan, kemudian dibuatkannyalah peniup-peniup dan api sepanjang bangunan tembok itu (berkatalah Zulkarnain, \"Tiuplah api itu)\" lalu api itu mereka tiup (Hingga apabila besi itu menjadi) berubah bentuknya menjadi (merah) bagaikan api (dia pun berkata, \"Berilah aku tembaga yang mendidih agar kutuangkan ke atas besi panas itu)\" maksudnya tembaga yang dilebur. Lafal Aatuunii dan lafal Ufrigh merupakan kedua Fi'il yang saling berebutan terhadap Ma'mulnya, kemudian dibuanglah Ma'mul dari Fi'il yang pertama karena beramalnya Fi'il yang kedua. Selanjutnya tembaga yang sudah dilebur itu dituangkan ke atas besi yang merah membara, sehingga masuklah tembaga itu ke dalam partikel-partikel potongan besi, akhirnya kedua logam itu menyatu.",[["ءَاتُونِى","Bawa aku"],["زُبَرَ","cadar"],["ٱلْحَدِيدِ ۖ","(dari) besi"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["سَاوَىٰ","dia (telah) meratakan"],["بَيْنَ","antara"],["ٱلصَّدَفَيْنِ","dua tebing itu"],["قَالَ","dia berkata"],["ٱنفُخُوا۟ ۖ","tiup"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["جَعَلَهُۥ","dia buat"],["نَارًۭا","kebakaran"],["قَالَ","dia berkata"],["ءَاتُونِىٓ","Bawa aku"],["أُفْرِغْ","aku tuang"],["عَلَيْهِ","atasnya"],["قِطْرًۭا","kuprum cair"]]],"2237":["(Maka mereka tidak dapat) yakni Yakjuj dan Makjuj itu (mendakinya) memanjat tembok itu karena terlalu tinggi dan terlalu licin (dan mereka tidak dapat pula melubanginya) karena tembok itu terlalu kuat dan tebal sekali.",[["فَمَا","Jadi tidak"],["ٱسْطَـٰعُوٓا۟","mereka mampu"],["أَن","kepada"],["يَظْهَرُوهُ","skala itu"],["وَمَا","dan bukan"],["ٱسْتَطَـٰعُوا۟","mereka mampu"],["لَهُۥ","di dalamnya"],["نَقْبًۭا","(untuk melakukan) sebarang penembusan"]]],"2238":["(Dia berkata) yakni Zulkarnain, (\"Ini) tembok ini atau bendungan ini, atau kemampuan di dalam membangun ini (adalah rahmat dari Rabbku) merupakan nikmat-Nya, sebab tembok ini dapat mencegah Yakjuj dan Makjuj untuk keluar (maka apabila sudah datang janji Rabbku) yakni saat mereka dapat keluar, bila hari kiamat telah dekat. (Dia akan menjadikannya hancur luluh) rata dengan tanah (dan janji Rabbku itu) tentang keluarnya mereka dan peristiwa-peristiwa lainnya (adalah benar)\" pasti terjadi.",[["قَالَ","Dia berkata"],["هَـٰذَا","Ini"],["رَحْمَةٌۭ","(adalah) rahmat"],["مِّن","daripada"],["رَّبِّى ۖ","Tuhanku"],["فَإِذَا","Tetapi apabila"],["جَآءَ","datang"],["وَعْدُ","(the) Janji"],["رَبِّى","(dari) Tuhanku"],["جَعَلَهُۥ","Dia akan berjaya"],["دَكَّآءَ ۖ","tahap"],["وَكَانَ","Dan adakah"],["وَعْدُ","(the) Janji"],["رَبِّى","(dari) Tuhanku"],["حَقًّۭا","benar"]]],"2239":["Selanjutnya Allah berfirman: (Kami biarkan sebagian di antara mereka pada hari itu) pada hari mereka keluar dari tembok itu (bercampur aduk dengan sebagian yang lain) mereka bercampur aduk karena saking banyaknya jumlah mereka (kemudian ditiup lagi sangkakala) untuk membangkitkan mereka menjadi hidup kembali (lalu Kami kumpulkan mereka itu) yakni seluruh makhluk pada suatu tempat di hari kiamat (semuanya).",[["۞ وَتَرَكْنَا","Dan Kami (akan) pergi"],["بَعْضَهُمْ","sebahagian mereka"],["يَوْمَئِذٍۢ","(pada) hari itu"],["يَمُوجُ","untuk melonjak"],["فِى","atas"],["بَعْضٍۢ ۖ","yang lain"],["وَنُفِخَ","dan (akan) ditiup"],["فِى","dalam"],["ٱلصُّورِ","sangkakala"],["فَجَمَعْنَـٰهُمْ","kemudian Kami (akan) mengumpulkan mereka"],["جَمْعًۭا","semua bersama"]]],"2240":["(Dan Kami tampakkan) Kami dekatkan (Jahanam pada hari itu kepada orang-orang kafir dengan jelas).",[["وَعَرَضْنَا","Dan Kami (akan) hadirkan"],["جَهَنَّمَ","Neraka"],["يَوْمَئِذٍۢ","(pada) hari itu"],["لِّلْكَـٰفِرِينَ","kepada orang-orang kafir"],["عَرْضًا","(di) paparan"]]],"2241":["(Yaitu orang-orang yang matanya) menjadi Badal atau kata ganti dari lafal Al-Kaafiriina yang pada ayat sebelumnya (dalam keadaan tertutup dari memperhatikan ayat-yat-Ku) yakni Alquran, karenanya mereka buta tidak dapat mengambil petunjuk darinya (dan adalah mereka tidak sanggup mendengar) artinya, mereka tidak mampu untuk mendengarkan dari nabi apa yang telah dibacakan kepada mereka, karena mereka membencinya, oleh sebab itu mereka tidak beriman kepadanya.",[["ٱلَّذِينَ","Mereka itu"],["كَانَتْ","telah"],["أَعْيُنُهُمْ","mata mereka"],["فِى","dalam"],["غِطَآءٍ","penutup"],["عَن","daripada"],["ذِكْرِى","zikir aku"],["وَكَانُوا۟","dan telah"],["لَا","tidak"],["يَسْتَطِيعُونَ","mampu"],["سَمْعًا","(untuk) mendengar"]]],"2242":["(Maka apakah orang-orang kafir menyangka bahwa mereka dapat mengambil hamba-hamba-Ku) yakni para Malaikat-Ku, Nabi 'Isa dan Nabi 'Uzair (menjadi penolong-penolong selain Aku?) yakni tuhan-tuhan yang dapat menolong mereka. Lafal Auliyaa-a ini menjadi Maf'ul Tsani daripada lafal Liyattakhidzuu, sedangkan Maf'ul Tsani daripada lafal Hasiba tidak disebutkan. Maksud ayat: Apakah mereka menyangka bahwa pengambilan mereka terhadap hal-hal yang telah disebutkan itu sebagai sesembahan mereka tidak membuat-Ku murka, dan Aku hanya berdiam diri tidak menghukum mereka? Tentu saja tidak. (Sesungguhnya Kami telah menyediakan neraka Jahanam bagi orang-orang kafir) yaitu bagi mereka dan bagi orang-orang kafir lainnya yang seperti mereka (sebagai tempat tinggal) maksudnya Jahanam itu telah disediakan buat mereka sebagaimana disediakannya tempat tinggal bagi tamu.",[["أَفَحَسِبَ","Kemudian fikirkan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["أَن","bahawa"],["يَتَّخِذُوا۟","mereka (boleh) mengambil"],["عِبَادِى","hamba-hamba-Ku"],["مِن","selain Aku"],["دُونِىٓ","selain Aku"],["أَوْلِيَآءَ ۚ","(sebagai) pelindung"],["إِنَّآ","Sesungguhnya Kami"],["أَعْتَدْنَا","Kami telah sediakan"],["جَهَنَّمَ","Neraka"],["لِلْكَـٰفِرِينَ","bagi orang-orang kafir"],["نُزُلًۭا","(sebagai) tempat penginapan"]]],"2243":["(Katakanlah, \"Apakah akan Kami beritahukan kepada kalian tentang orang-orang yang paling merugi perbuatannya?)\" lafal A'maalan menjadi Tamyiz atau keterangan pembeda yang bentuknya sama dengan Mumayyaz. Kemudian Allah swt. menjelaskan siapa mereka yang merugi itu, melalui firman berikutnya.",[["قُلْ","Katakanlah"],["هَلْ","hendaklah"],["نُنَبِّئُكُم","Kami maklumkan kepada kamu"],["بِٱلْأَخْسَرِينَ","daripada orang yang paling rugi"],["أَعْمَـٰلًا","(tentang) perbuatan mereka"]]],"2244":["(Yaitu orang-orang yang telah sia-sia perbuatannya dalam kehidupan dunia ini) amal perbuatan mereka batil tidak diterima (sedangkan mereka menyangka) menduga (bahwa mereka berbuat sebaik-baiknya) yang pasti mereka akan menerima pahala karenanya.",[["ٱلَّذِينَ","Itu"],["ضَلَّ","hilang"],["سَعْيُهُمْ","usaha mereka"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا","dunia"],["وَهُمْ","sedangkan mereka"],["يَحْسَبُونَ","fikir"],["أَنَّهُمْ","bahawa mereka"],["يُحْسِنُونَ","(sedang) memperoleh kebaikan"],["صُنْعًا","(dalam) kerja"]]],"2245":["(Mereka itu orang-orang yang kafir terhadap ayat-ayat Rabb mereka) kafir terhadap bukti-bukti yang menunjukkan kepada keesaan-Nya, baik berupa Alquran maupun lain-lainnya (dan kafir terhadap perjumpaan dengan Dia) ingkar pada adanya hari berbangkit, perhitungan amal perbuatan, pahala dan siksaan (maka hapuslah amalan-amalan mereka) yakni ditolak (dan Kami tidak mengadakan suatu penilaian bagi amalan mereka pada hari kiamat) Kami tidak menganggap sama sekali amal perbuatan mereka.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) orang-orang yang"],["كَفَرُوا۟","kufur"],["بِـَٔايَـٰتِ","dalam Ayat"],["رَبِّهِمْ","(dari) Tuhan mereka"],["وَلِقَآئِهِۦ","dan pertemuan (dengan)Nya"],["فَحَبِطَتْ","Maka (adalah) sia-sia"],["أَعْمَـٰلُهُمْ","perbuatan mereka"],["فَلَا","jadi tidak"],["نُقِيمُ","Kami akan menetapkan"],["لَهُمْ","bagi mereka"],["يَوْمَ","(pada) hari itu"],["ٱلْقِيَـٰمَةِ","Kiamat"],["وَزْنًۭا","sebarang berat"]]],"2246":["(Demikianlah) yakni perihal yang telah Kusebutkan sehubungan dengan dihapusnya amal perbuatan mereka dan lain-lainnya. Lafal Dzaalika menjadi Mubtada sedangkan Khabarnya ialah: (balasan mereka itu neraka Jahanam, disebabkan kekafiran mereka dan disebabkan mereka menjadikan ayat-ayat-Ku dan Rasul-rasul-Ku sebagai olok-olok) keduanya menjadi ejekan dan olokan mereka.",[["ذَٰلِكَ","Itu"],["جَزَآؤُهُمْ","(ialah) balasan mereka"],["جَهَنَّمُ","Neraka"],["بِمَا","kerana"],["كَفَرُوا۟","mereka kafir"],["وَٱتَّخَذُوٓا۟","dan mengambil"],["ءَايَـٰتِى","Ayat-ayat Aku"],["وَرُسُلِى","dan Rasul-rasulKu"],["هُزُوًا","(dalam) ejekan"]]],"2247":["(Sesungguhnya orang-orang yang beriman dan beramal saleh, bagi mereka) menurut ilmu Allah (adalah surga Firdaus) yaitu bagian tengah dan bagian teratas daripada surga. Idhafah di sini memberikan pengertian Bayan atau menjelaskan (menjadi tempat tinggal) tempat menetap mereka.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["كَانَتْ","untuk mereka akan menjadi"],["لَهُمْ","untuk mereka akan menjadi"],["جَنَّـٰتُ","Taman-taman"],["ٱلْفِرْدَوْسِ","(dari) Syurga"],["نُزُلًا","(sebagai) tempat penginapan"]]],"2248":["(Mereka kekal di dalamnya, mereka tidak ingin) tidak meminta (berpindah daripadanya) pindah ke tempat yang lain.",[["خَـٰلِدِينَ","Kekal selamanya"],["فِيهَا","di dalamnya"],["لَا","Tidak"],["يَبْغُونَ","mereka akan inginkan"],["عَنْهَا","daripadanya"],["حِوَلًۭا","sebarang pemindahan"]]],"2249":["(Katakanlah, \"Kalau sekiranya lautan) airnya (menjadi tinta) yaitu sarana untuk menulis (untuk menulis kalimat-kalimat Rabbku) yang menunjukkan kepada kebijaksanaan-kebijaksanaan dan keajaiban-keajaiban ciptaan-Nya, seumpamanya hal itu ditulis (sungguh habislah lautan itu) untuk menulisnya (sebelum habis) dapat dibaca Tanfadza atau Yanfadza, yakni sebelum habis ditulis (kalimat-kalimat Rabbku, meskipun Kami datangkan sebanyak itu) lautan yang sama (sebagai tambahan tintanya.\") niscaya tambahan ini pun akan habis pula, sedangkan kalimat-kalimat Rabbku masih belum habis ditulis. Lafal Madadan dinashabkan karena menjadi Tamyiz.",[["قُل","Katakanlah"],["لَّوْ","Jika"],["كَانَ","adalah"],["ٱلْبَحْرُ","laut"],["مِدَادًۭا","dakwat"],["لِّكَلِمَـٰتِ","untuk (the) Perkataan"],["رَبِّى","(dari) Tuhanku"],["لَنَفِدَ","pasti (akan) habis"],["ٱلْبَحْرُ","laut"],["قَبْلَ","sebelum"],["أَن","[bahawa]"],["تَنفَدَ","(telah) letih"],["كَلِمَـٰتُ","(the) Perkataan"],["رَبِّى","(dari) Tuhanku"],["وَلَوْ","walaupun"],["جِئْنَا","Kami bawa"],["بِمِثْلِهِۦ","(yang) menyukainya"],["مَدَدًۭا","(sebagai) suplemen"]]],"2250":["(Katakanlah, \"Sesungguhnya aku ini hanyalah seorang manusia) anak Adam (seperti kalian, yang diwahyukan kepadaku, 'Bahwa sesungguhnya Rabb kalian itu adalah Tuhan Yang Esa.') huruf Anna di sini Maktufah atau dicegah untuk beramal oleh sebab adanya Ma, sedangkan huruf Ma masih tetap status Mashdarnya. Maksudnya; yang diwahyukan kepadaku mengenai keesaan Tuhan (Barang siapa mengharap) bercita-cita (perjumpaan dengan Rabbnya) setelah dibangkitkan dan menerima pembalasan (maka hendaklah ia mengerjakan amal yang saleh dan janganlah ia mempersekutukan di dalam beribadah kepada Rabbnya) yakni sewaktu ia beribadah kepada-Nya, seumpamanya ia hanya ingin pamer (dengan seorang pun\").",[["قُلْ","Katakanlah"],["إِنَّمَآ","Hanya"],["أَنَا۠","aku"],["بَشَرٌۭ","(aku) seorang lelaki"],["مِّثْلُكُمْ","macam kamu"],["يُوحَىٰٓ","Telah didedahkan"],["إِلَىَّ","kepada aku"],["أَنَّمَآ","bahawa"],["إِلَـٰهُكُمْ","Tuhanmu"],["إِلَـٰهٌۭ","(ialah) Tuhan"],["وَٰحِدٌۭ ۖ","satu"],["فَمَن","Jadi sesiapa"],["كَانَ","ialah"],["يَرْجُوا۟","mengharap"],["لِقَآءَ","(untuk) mesyuarat"],["رَبِّهِۦ","(dengan) Tuhannya"],["فَلْيَعْمَلْ","biar dia buat"],["عَمَلًۭا","perbuatan"],["صَـٰلِحًۭا","soleh"],["وَلَا","dan bukan"],["يُشْرِكْ","bersekutu"],["بِعِبَادَةِ","dalam (beribadat)."],["رَبِّهِۦٓ","(dari) Tuhannya"],["أَحَدًۢا","sesiapa sahaja"]]],"2251":["(Kaf Ha Ya 'Ain Shad) hanya Allah yang mengetahui maksudnya.",[["كٓهيعٓصٓ","Kaaf Ha Ya Ain Sedih"]]],"2252":["Ini adalah (penjelasan tentang rahmat Rabb kamu kepada hamba-Nya) lafal 'abdahu menjadi Maf'ul dari Rahmah (Zakaria) sebagai penjelasan dari kata 'hamba' tadi.",[["ذِكْرُ","(A) menyebut"],["رَحْمَتِ","(dari) Rahmat"],["رَبِّكَ","Tuhanmu"],["عَبْدَهُۥ","(kepada) hamba-Nya"],["زَكَرِيَّآ","Zakariya"]]],"2253":["(Yaitu tatkala) lafal Idz berta'alluq kepada lafal Rahmah (ia berdoa kepada Rabbnya dengan seruan) yang mengandung doa (yang lembut) dengan suara yang pelan-pelan di tengah malam, karena berdoa di tengah malam itu lebih cepat untuk dikabulkan.",[["إِذْ","Apabila"],["نَادَىٰ","dia panggil"],["رَبَّهُۥ","(kepada) Tuhannya"],["نِدَآءً","panggilan"],["خَفِيًّۭا","rahsia"]]],"2254":["(Ia berkata, \"Ya Rabbku! Sesungguhnya telah lemah) menjadi lemah (tulang-tulangku) semuanya (dan kepala ini telah dipenuhi) (oleh uban) lafal Syaiban menjadi Tamyiz yang dipindahkan dari Fa'ilnya, maksudnya uban telah merata di rambut kepalanya sebagaimana meratanya nyala api pada kayu dan sesungguhnya aku bermaksud berdoa kepada-Mu (dan aku belum pernah dengan doaku kepada-Mu) (merasa kecewa, ya Rabbku!) artinya, merasa dikecewakan di masa-masa lalu; maka janganlah Engkau kecewakan aku di masa mendatang.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["إِنِّى","Sesungguhnya, [aku]"],["وَهَنَ","(telah) lemah"],["ٱلْعَظْمُ","tulang aku"],["مِنِّى","tulang aku"],["وَٱشْتَعَلَ","dan berkobar-kobar"],["ٱلرَّأْسُ","(aku) kepala"],["شَيْبًۭا","(dengan) putih"],["وَلَمْ","dan bukan"],["أَكُنۢ","aku telah"],["بِدُعَآئِكَ","dalam permohonanku (kepada) Engkau"],["رَبِّ","Tuhanku"],["شَقِيًّۭا","tidak diberkati"]]],"2255":["(Dan sesungguhnya aku khawatir terhadap mawaliku) yakni orang-orang dekat hubungan familinya denganku seperti anak-anak paman (sepeninggalku) yakni sesudah aku meninggal dunia, aku khawatir mereka akan menyia-nyiakan agama sebagaimana yang telah kusaksikan sendiri apa yang terjadi di kalangan orang-orang Bani Israel, yaitu mereka berani mengubah agamanya (sedangkan istriku adalah seorang yang mandul) tidak beranak (maka anugerahilah aku dari sisi Engkau) (seorang putra) anak lelaki.",[["وَإِنِّى","Dan sesungguhnya, aku"],["خِفْتُ","[Aku] takut"],["ٱلْمَوَٰلِىَ","para pengganti"],["مِن","selepas aku"],["وَرَآءِى","selepas aku"],["وَكَانَتِ","dan adalah"],["ٱمْرَأَتِى","isteri aku"],["عَاقِرًۭا","mandul"],["فَهَبْ","Jadi berikan"],["لِى","[kepada] aku"],["مِن","daripada"],["لَّدُنكَ","diri sendiri"],["وَلِيًّۭا","seorang waris"]]],"2256":["(Yang akan mewarisi aku) kalau dibaca Jazm berarti lafal Yaritsni menjadi jawab dari Fi'il Amar, dan kalau dibaca Rafa' yaitu Yaritsuni berarti menjadi kata sifat dari lafal Waliyyan (dan mewarisi) dapat dibaca Yaritsu atau Yarits (sebagian keluarga Ya'qub) kakekku dalam hal ilmu dan kenabian (dan jadikanlah ia, ya Rabbku, seorang yang diridai)\" di sisi Engkau.",[["يَرِثُنِى","Siapa yang akan mewarisi aku"],["وَيَرِثُ","dan mewarisi"],["مِنْ","daripada"],["ءَالِ","(keluarga)."],["يَعْقُوبَ ۖ","(dari) Yaqub"],["وَٱجْعَلْهُ","Dan buat dia"],["رَبِّ","Tuhanku"],["رَضِيًّۭا","menggembirakan"]]],"2257":["(Hai Zakaria, sesungguhnya Kami memberi kabar gembira kepadamu akan beroleh seorang anak) yang akan menjadi waris, sebagaimana yang kamu minta (yang namanya Yahya, yang sebelumnya Kami tidak pernah menciptakan orang yang serupa dengan dia) dalam hal namanya, yakni seseorang yang diberi nama Yahya.",[["يَـٰزَكَرِيَّآ","Wahai Zakariya"],["إِنَّا","Sesungguhnya Kami"],["نُبَشِّرُكَ","[Kami] memberi khabar gembira kepada kamu"],["بِغُلَـٰمٍ","seorang budak lelaki"],["ٱسْمُهُۥ","namanya"],["يَحْيَىٰ","(akan menjadi) Yahya"],["لَمْ","tidak"],["نَجْعَل","Kami (telah) menugaskan"],["لَّهُۥ","[untuk] itu"],["مِن","sebelum"],["قَبْلُ","sebelum"],["سَمِيًّۭا","(ini) nama"]]],"2258":["(Zakaria berkata, \"Ya Rabbku! Bagaimana) mana mungkin (akan ada anak bagiku, padahal istriku adalah seorang yang mandul dan aku sendiri sesungguhnya sudah mencapai umur yang sangat tua)\" lafal 'itiyyan berasal dari lafal 'Ataa artinya Yabisa atau kering, maksudnya ia telah mencapai umur seratus dua puluh tahun, dan istrinya telah mencapai umur sembilan puluh delapan tahun. Kata 'Itiyyun pada asalnya adalah 'Ituwwun. Kemudian huruf Ta dikasrahkan untuk meringankan pengucapannya lalu jadilah 'Itiwwun. Selanjutnya huruf Wawu yang pertama diganti menjadi huruf Ya demi penyesuaian dengan harakat Kasrah sebelumnya, dan huruf Wawu yang kedua diganti pula dengan huruf Ya supaya huruf Ya yang pertama dapat diidgamkan atau dimasukkan kepadanya, sehingga jadilah 'Itiyyun.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["أَنَّىٰ","Bagaimana"],["يَكُونُ","boleh"],["لِى","aku ada"],["غُلَـٰمٌۭ","seorang budak lelaki"],["وَكَانَتِ","manakala adalah"],["ٱمْرَأَتِى","isteri aku"],["عَاقِرًۭا","mandul"],["وَقَدْ","dan sesungguhnya"],["بَلَغْتُ","aku telah sampai"],["مِنَ","daripada"],["ٱلْكِبَرِ","usia tua"],["عِتِيًّۭا","melampau"]]],"2259":["(Allah berfirman) perkaranya memang (\"Demikianlah.\") cara menciptakan seorang anak lelaki dari kamu berdua (Rabbmu berfirman, \"Hal itu adalah mudah bagi-Ku) yaitu dengan memberikan kekuatan bersetubuh kepadamu, kemudian menjadikan rahim istrimu dapat menerima spermamu (dan sesungguhnya telah Aku ciptakan kamu sebelum itu, padahal kamu belum ada sama sekali)\" di waktu kamu belum diciptakan. Untuk menampilkan kekuasaan Allah yang mampu menciptakan hal yang besar ini, maka Dia memberikan ilham suatu pertanyaan, supaya pertanyaan itu kelak dijawab dengan hal yang membuktikan kekuasaan-Nya yang maha besar itu. Tatkala Zakaria merasa rindu akan kedatangan berita gembira kelahiran seorang putra itu.",[["قَالَ","Dia berkata"],["كَذَٰلِكَ","Demikianlah"],["قَالَ","berkata"],["رَبُّكَ","Tuhanmu"],["هُوَ","'Ia"],["عَلَىَّ","(adalah) mudah bagi-Ku"],["هَيِّنٌۭ","(adalah) mudah bagi-Ku"],["وَقَدْ","dan pastinya"],["خَلَقْتُكَ","Aku (telah) menciptakan kamu"],["مِن","sebelum"],["قَبْلُ","sebelum"],["وَلَمْ","manakala tidak"],["تَكُ","kamu dahulu"],["شَيْـًۭٔا","apa-apa.'"]]],"2260":["(Zakaria berkata, \"Ya Rabbku! Berilah aku suatu tanda)\" pertanda yang menunjukkan istriku mulai mengandung (Allah berfirman, \"Tanda bagimu) yang menunjukkan hal itu (adalah bahwa kamu tidak boleh bercakap-cakap dengan manusia) mencegah dirimu untuk tidak berbicara dengan mereka selain dari berzikir kepada Allah (selama tiga malam) yakni tiga hari tiga malam (padahal kamu sehat)\" lafal Sawiyyan berkedudukan menjadi Hal dari Fa'il lafal Takallama, maksudnya ia tidak berbicara dengan mereka tanpa sebab.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["ٱجْعَل","buat"],["لِّىٓ","untuk aku"],["ءَايَةًۭ ۚ","satu tanda"],["قَالَ","Dia berkata"],["ءَايَتُكَ","Tanda kamu"],["أَلَّا","(adalah) itu tidak"],["تُكَلِّمَ","kamu akan bercakap"],["ٱلنَّاسَ","(kepada) rakyat"],["ثَلَـٰثَ","(untuk) tiga"],["لَيَالٍۢ","malam-malam"],["سَوِيًّۭا","bunyi"]]],"2261":["(Maka ia keluar dari mihrab menuju kaumnya) yakni dari mesjid, sedang orang-orang menunggu pintu mesjid itu dibuka, karena mereka hendak melakukan salat di dalamnya, sesuai dengan kebiasaan mereka menurut perintah Zakaria (lalu ia memberi isyarat) (kepada mereka; hendaklah kalian bertasbih) maksudnya melakukan salat (di waktu pagi dan petang) yakni pada permulaan siang hari dan akhirnya, sebagaimana biasa. Setelah Nabi Zakaria mencegah dirinya untuk bercakap-cakap dengan mereka, pada saat itu diketahui bahwa istrinya mengandung Yahya. Selang dua tahun kemudian setelah Yahya lahir, Allah berfirman kepadanya.",[["فَخَرَجَ","Kemudian dia keluar"],["عَلَىٰ","kepada"],["قَوْمِهِۦ","umatnya"],["مِنَ","daripada"],["ٱلْمِحْرَابِ","ruang solat"],["فَأَوْحَىٰٓ","dan dia memberi isyarat"],["إِلَيْهِمْ","kepada mereka"],["أَن","kepada"],["سَبِّحُوا۟","bertasbih (Allah)"],["بُكْرَةًۭ","(dalam) pagi"],["وَعَشِيًّۭا","dan (pada) petang"]]],"2262":["(Hai Yahya! Ambillah Kitab itu) yakni kitab Taurat (dengan sungguh-sungguh) secara sungguh-sungguh. (Dan Kami berikan kepadanya hikmah) kenabian (selagi ia masih kanak-kanak) sewaktu berumur tiga tahun.",[["يَـٰيَحْيَىٰ","Wahai Yahya"],["خُذِ","tahan"],["ٱلْكِتَـٰبَ","Kitab Suci"],["بِقُوَّةٍۢ ۖ","dengan kekuatan"],["وَءَاتَيْنَـٰهُ","Dan Kami berikan kepadanya"],["ٱلْحُكْمَ","[kebijaksanaan]"],["صَبِيًّۭا","(ketika dia) kanak-kanak"]]],"2263":["(Dan rasa belas kasihan yang mendalam) terhadap manusia (dari sisi Kami) dari haribaan Kami (dan zakat) yakni senang bersedekah kepada mereka (Dan ia adalah seorang yang bertakwa) menurut suatu riwayat disebutkan, bahwa Nabi Yahya tidak pernah melakukan suatu dosa pun, dan hatinya tidak pernah mempunyai keinginan untuk melakukannya.",[["وَحَنَانًۭا","Dan kasih sayang"],["مِّن","daripada"],["لَّدُنَّا","Kami"],["وَزَكَوٰةًۭ ۖ","dan kesucian"],["وَكَانَ","dan dia"],["تَقِيًّۭا","soleh"]]],"2264":["(Dan seorang yang berbakti kepada kedua orang tuanya) yaitu selalu berbuat baik kepada keduanya (dan bukanlah ia orang yang sombong) takabur (lagi bukan pula ia orang yang durhaka) terhadap Rabbnya.",[["وَبَرًّۢا","Dan berbakti"],["بِوَٰلِدَيْهِ","kepada ibu bapanya"],["وَلَمْ","dan bukan"],["يَكُن","dia adalah"],["جَبَّارًا","seorang yang zalim"],["عَصِيًّۭا","ingkar"]]],"2265":["(Kesejahteraan) dari Kami (terlimpahkan kepadanya pada hari ia dilahirkan dan pada hari ia meninggal dan pada hari ia dibangkitkan hidup kembali) di saat-saat yang mengerikan yakni hari kiamat. Pada hari itu belum pernah ada pemandangan yang sengeri itu, maka Nabi Yahya selamat daripadanya.",[["وَسَلَـٰمٌ","Dan selamat sejahtera"],["عَلَيْهِ","atasnya"],["يَوْمَ","(hari itu)."],["وُلِدَ","dia dilahirkan"],["وَيَوْمَ","dan (hari)."],["يَمُوتُ","dia mati"],["وَيَوْمَ","dan (hari)."],["يُبْعَثُ","dia akan dibangkitkan"],["حَيًّۭا","hidup"]]],"2266":["(Dan ceritakanlah di dalam Kitab) yakni Alquran (tentang Maryam) kisahnya (yaitu ketika) (ia menjauhkan diri dari keluarganya ke suatu tempat di sebelah Timur) Maryam mengasingkan diri di suatu tempat di sebelah Timur rumahnya.",[["وَٱذْكُرْ","Dan sebutkan"],["فِى","dalam"],["ٱلْكِتَـٰبِ","Kitab"],["مَرْيَمَ","Maryam"],["إِذِ","apabila"],["ٱنتَبَذَتْ","dia menarik diri"],["مِنْ","daripada"],["أَهْلِهَا","keluarganya"],["مَكَانًۭا","(ke) tempat"],["شَرْقِيًّۭا","timur"]]],"2267":["(Maka ia mengadakan tabir yang menutupinya dari mereka) Maryam membuat tabir untuk melindungi dirinya sewaktu ia membuka penutup kepalanya, atau membuka pakaiannya atau menyucikan dirinya dari haid (lalu Kami mengutus kepadanya roh Kami) yakni malaikat Jibril (maka ia menjelma di hadapannya) sesudah Maryam memakai pakaiannya (dalam bentuk manusia yang sempurna) manusia sesungguhnya.",[["فَٱتَّخَذَتْ","Kemudian dia mengambil"],["مِن","daripada mereka"],["دُونِهِمْ","daripada mereka"],["حِجَابًۭا","skrin"],["فَأَرْسَلْنَآ","Kemudian Kami mengutus"],["إِلَيْهَا","kepada dia"],["رُوحَنَا","Roh kita"],["فَتَمَثَّلَ","kemudian dia menganggap baginya persamaan"],["لَهَا","kemudian dia menganggap baginya persamaan"],["بَشَرًۭا","(dari) seorang lelaki"],["سَوِيًّۭا","berkadar baik"]]],"2268":["(Maryam berkata, \"Sesungguhnya aku berlindung daripadamu kepada Tuhan Yang Maha Pemurah, jika kamu seorang yang bertakwa.\") kamu pasti dapat menahan diri daripadaku dengan bacaan Ta'awwudzku ini.",[["قَالَتْ","Dia berkata"],["إِنِّىٓ","Sesungguhnya aku"],["أَعُوذُ","[Aku] mencari perlindungan"],["بِٱلرَّحْمَـٰنِ","dengan Yang Maha Pemurah"],["مِنكَ","daripada kamu"],["إِن","jika"],["كُنتَ","kamu"],["تَقِيًّۭا","takut kepada Allah"]]],"2269":["(Ia berkata, \"Sesungguhnya aku ini adalah utusan Rabbmu, untuk memberimu seorang anak laki-laki yang suci)\" yang kelak menjadi nabi.",[["قَالَ","Dia berkata"],["إِنَّمَآ","Hanya"],["أَنَا۠","aku"],["رَسُولُ","seorang Rasul"],["رَبِّكِ","(dari) Tuhanmu"],["لِأَهَبَ","yang aku (boleh) kurniakan"],["لَكِ","pada kamu"],["غُلَـٰمًۭا","seorang anak lelaki"],["زَكِيًّۭا","tulen"]]],"2270":["(Maryam berkata, \"Bagaimana akan ada bagiku seorang anak laki-laki, sedangkan tidak pernah seorang manusia pun menyentuhku) yakni mengawiniku (dan aku bukan pula seorang pezina!)\" seorang pelacur.",[["قَالَتْ","Dia berkata"],["أَنَّىٰ","Bagaimana"],["يَكُونُ","boleh jadi"],["لِى","untuk aku"],["غُلَـٰمٌۭ","seorang anak lelaki"],["وَلَمْ","apabila tidak"],["يَمْسَسْنِى","telah menyentuh aku"],["بَشَرٌۭ","seorang lelaki"],["وَلَمْ","dan bukan"],["أَكُ","aku"],["بَغِيًّۭا","tidak suci"]]],"2271":["(Jibril berkata,) perkaranya memang (\"Demikianlah.\") yaitu akan diciptakan bagimu seorang anak laki-laki tanpa ayah (Rabbmu berfirman, \"Hal itu adalah mudah bagi-Ku) yaitu dengan cara Aku memerintahkan kepada malaikat Jibril supaya meniup dirimu, lalu karena itu kamu mengandung. Mengingat kalimat yang telah disebutkan mengandung makna illat atau kausalita, maka kalimat berikutnya di'athafkan kepadanya, yaitu (dan agar dapat Kami menjadikannya suatu tanda bagi manusia) yang menunjukkan akan kekuasaan-Ku (dan sebagai rahmat dari Kami) bagi orang-orang yang beriman kepadanya (dan hal itu adalah) penciptaan itu merupakan (suatu perkara yang sudah diputuskan)\" di dalam ilmu-Ku, malaikat Jibril meniupkan nafasnya ke dalam baju kurung Maryam, seketika itu juga Maryam merasakan di dalam kandungannya terdapat seorang bayi.",[["قَالَ","Dia berkata"],["كَذَٰلِكِ","Demikianlah"],["قَالَ","berkata"],["رَبُّكِ","Tuhanmu"],["هُوَ","'Ia"],["عَلَىَّ","(adalah) untuk-Ku"],["هَيِّنٌۭ ۖ","mudah"],["وَلِنَجْعَلَهُۥٓ","dan supaya Kami jadikan dia"],["ءَايَةًۭ","satu tanda"],["لِّلنَّاسِ","untuk umat manusia"],["وَرَحْمَةًۭ","dan Rahmat"],["مِّنَّا ۚ","daripada Kami"],["وَكَانَ","Dan (ia) adalah"],["أَمْرًۭا","sesuatu perkara"],["مَّقْضِيًّۭا","diputuskan.'"]]],"2272":["(Maka Maryam mengandungnya, lalu ia mengasingkan diri) menjauhkan diri (dengan membawa kandungannya ke tempat yang jauh) jauh dari keluarganya.",[["۞ فَحَمَلَتْهُ","Jadi dia mengandungkan dia"],["فَٱنتَبَذَتْ","dan dia menarik diri"],["بِهِۦ","dengan dia"],["مَكَانًۭا","(ke) tempat"],["قَصِيًّۭا","jauh"]]],"2273":["(Maka sewaktu datang kepadanya) ketika ia mengalami (rasa sakit akan melahirkan) yaitu rasa mulas karena akan melahirkan (-terpaksa ia bersandar- pada pangkal pohon kurma) yakni menyandarkan diri padanya, lalu ia melahirkan. Perlu diketahui bahwa sejak peniupan malaikat Jibril hingga melahirkan hanya memakan waktu sesaat saja (dia berkata, \"Aduhai alangkah baiknya aku) lafal Ya di sini menunjukkan makna Tanbih atau ungkapan kekecewaan (mati sebelum ini) yakni sebelum perkara ini (dan aku menjadi barang yang tidak berarti, lagi dilupakan)\" sebagai sesuatu yang tiada artinya, tidak dikenal dan tidak disebut-sebut.",[["فَأَجَآءَهَا","Kemudian memandu dia"],["ٱلْمَخَاضُ","sakit bersalin"],["إِلَىٰ","kepada"],["جِذْعِ","(the) batang"],["ٱلنَّخْلَةِ","(daripada) pokok kurma"],["قَالَتْ","Dia berkata"],["يَـٰلَيْتَنِى","O! aku harap"],["مِتُّ","Aku (telah) meninggal dunia"],["قَبْلَ","sebelum"],["هَـٰذَا","ini"],["وَكُنتُ","dan aku"],["نَسْيًۭا","(dalam) terlupa"],["مَّنسِيًّۭا","terlupa"]]],"2274":["(Maka Jibril menyerunya dari tempat yang lebih rendah,) pada saat itu malaikat Jibril berada di tempat yang lebih rendah dari tempat Maryam (\"Janganlah kamu bersedih hati, sesungguhnya Rabbmu telah menjadikan anak sungai di bawahmu\") yaitu sebuah sungai yang dahulunya kering kini berair kembali, berkat kekuasaan Allah.",[["فَنَادَىٰهَا","Jadi menangis kepadanya"],["مِن","daripada"],["تَحْتِهَآ","di bawahnya"],["أَلَّا","Itu (jangan) tidak"],["تَحْزَنِى","bersedih"],["قَدْ","sesungguhnya"],["جَعَلَ","(telah) meletakkan"],["رَبُّكِ","Tuhanmu"],["تَحْتَكِ","di bawah kamu"],["سَرِيًّۭا","sebuah aliran"]]],"2275":["(Dan goyanglah pangkal pohon kurma itu ke arahmu) yang pada saat itu kering. Huruf Ba dalam lafal Bijidz'i adalah Zaidah atau tambahan (niscaya pohon itu akan menggugurkan) asal kata Tusaaqith adalah Tatasaaqath kemudian Ta yang kedua diganti menjadi Sin, selanjutnya diidgamkan pada Sin yang kedua. Menurut qiraat yang lain tetap dibaca seperti lafal asalnya (buah kurma kepadamu) lafal Ruthaban adalah Tamyiz (yang masak-masak) lafal Janiyyan menjadi sifat dari lafal Ruthaban.",[["وَهُزِّىٓ","Dan goncang"],["إِلَيْكِ","terhadap kamu"],["بِجِذْعِ","(the) batang"],["ٱلنَّخْلَةِ","(daripada) pokok kurma"],["تُسَـٰقِطْ","ia akan jatuh"],["عَلَيْكِ","ke atas kamu"],["رُطَبًۭا","kurma segar"],["جَنِيًّۭا","matang"]]],"2276":["(Maka makanlah) dari buah kurma yang masak itu (dan minumlah) dari air sungai kecil itu (serta bersenang hatilah kamu) dengan anakmu itu. Lafal 'Ainan berfungsi sebagai Tamyiz yang dipindahkan dari Fa'ilnya, maksudnya selamat bersenang hati dengan anakmu itu. Atau dengan kata lain, kamu menjadi tenang dengan adanya anakmu itu sehingga kamu tidak memikirkan hal-hal yang lain. (Jika) lafal Immaa ini pada asalnya terdiri dari In Syarthiyah dan Ma Zaidah yang kemudian diidgamkan menjadi satu hingga menjadi Immaa (kamu melihat) dan lafal Tarayinna terbuang huruf Lam Fi'il dan 'Ain Fi'ilnya, kemudian harakat 'Ain Fi'ilnya dipindahkan pada huruf Ra, selanjutnya Ya Dhamir dikasrahkan karena bertemu dua sukun, sehingga jadilah Tarayinna (seorang manusia) kemudian ia menanyakan kepadamu tentang anakmu itu (maka katakanlah, \"Sesungguhnya aku bernazar shaum untuk Tuhan Yang Maha Pemurah) dengan menahan diri untuk tidak berbicara, baik mengenai perihal anaknya atau orang-orang lainnya, hal ini terbukti dengan perkataan selanjutnya (maka aku tidak akan berkata dengan seorang manusia pun pada hari ini)\" sesudah kejadian ini.",[["فَكُلِى","Jadi makan"],["وَٱشْرَبِى","dan minum"],["وَقَرِّى","dan sejuk"],["عَيْنًۭا ۖ","mata (kamu)."],["فَإِمَّا","Dan jika"],["تَرَيِنَّ","kamu lihat"],["مِنَ","daripada"],["ٱلْبَشَرِ","manusia"],["أَحَدًۭا","sesiapa sahaja"],["فَقُولِىٓ","kemudian berkata"],["إِنِّى","Sesungguhnya aku"],["نَذَرْتُ","[Aku] telah bersumpah"],["لِلرَّحْمَـٰنِ","kepada Yang Maha Pemurah"],["صَوْمًۭا","puasa"],["فَلَنْ","jadi tidak"],["أُكَلِّمَ","Aku akan bercakap"],["ٱلْيَوْمَ","hari ini"],["إِنسِيًّۭا","(kepada mana-mana) manusia"]]],"2277":["(Maka Maryam membawa anak itu kepada kaumnya dengan menggendongnya) lafal Tahmiluhu menjadi Hal atau kata keterangan keadaan. Sehingga kaumnya melihat anak itu (Kaumnya berkata, \"Hai Maryam! Sesungguhnya kamu telah melakukan sesuatu yang amat mungkar) suatu dosa yang sangat besar karena kamu memperoleh anak tanpa ayah.",[["فَأَتَتْ","Kemudian dia datang"],["بِهِۦ","dengan dia"],["قَوْمَهَا","(kepada) kaumnya"],["تَحْمِلُهُۥ ۖ","menggendongnya"],["قَالُوا۟","Mereka berkata"],["يَـٰمَرْيَمُ","Wahai Maryam"],["لَقَدْ","Sungguh"],["جِئْتِ","kamu (telah) membawa"],["شَيْـًۭٔا","satu perkara yang menakjubkan"],["فَرِيًّۭا","satu perkara yang menakjubkan"]]],"2278":["(Hai saudara perempuan Harun!) dia adalah seorang lelaki yang saleh, hal ini berarti Maryam pun serupa dengannya dalam hal memelihara kehormatan (Ayahmu sekali-kali bukanlah seorang yang buruk) bukan seorang pezina (dan ibumu sekali-kali bukanlah seorang pelacur)\" bukan pula seorang pezina, maka dari manakah anak ini.",[["يَـٰٓأُخْتَ","Wahai adik"],["هَـٰرُونَ","(dari) Harun"],["مَا","Tidak"],["كَانَ","adalah"],["أَبُوكِ","ayah kamu"],["ٱمْرَأَ","seorang lelaki yang jahat"],["سَوْءٍۢ","seorang lelaki yang jahat"],["وَمَا","dan bukan"],["كَانَتْ","adalah"],["أُمُّكِ","ibu kamu"],["بَغِيًّۭا","tidak suci"]]],"2279":["(Maka Maryam mengisyaratkan) kepada kaumnya (-seraya menunjuk- kepada anaknya) maksudnya supaya mereka bertanya kepada anaknya. (Mereka berkata, \"Bagaimana kami akan berbicara dengan anak) yang masih (kecil berada dalam ayunan?)\".",[["فَأَشَارَتْ","Kemudian dia menunjuk"],["إِلَيْهِ ۖ","kepadanya"],["قَالُوا۟","Mereka berkata"],["كَيْفَ","Bagaimana"],["نُكَلِّمُ","(boleh) kita bercakap"],["مَن","(kepada seorang) siapa"],["كَانَ","ialah"],["فِى","dalam"],["ٱلْمَهْدِ","buaian"],["صَبِيًّۭا","seorang kanak-kanak"]]],"2280":["(Isa berkata, \"Sesungguhnya aku ini hamba Allah, Dia memberiku Alkitab) yakni kitab Injil (dan Dia menjadikan aku seorang nabi).",[["قَالَ","Dia berkata"],["إِنِّى","Memang aku"],["عَبْدُ","seorang hamba"],["ٱللَّهِ","(milik) Allah"],["ءَاتَىٰنِىَ","Dia memberi aku"],["ٱلْكِتَـٰبَ","Kitab Suci"],["وَجَعَلَنِى","dan menjadikan aku"],["نَبِيًّۭا","seorang Nabi"]]],"2281":["(Dan Dia menjadikan aku seorang yang diberkati di mana saja aku berada) maksudnya Dia menjadikan diriku orang yang banyak memberi manfaat kepada manusia. Ungkapan ini merupakan berita tentang kedudukan yang telah dipastikan baginya (dan Dia memerintahkan kepadaku mendirikan salat dan menunaikan zakat) Allah memerintahkan kepadaku untuk melakukan kedua hal tersebut (selama aku hidup).",[["وَجَعَلَنِى","Dan Dia (telah) menjadikan aku"],["مُبَارَكًا","diberkati"],["أَيْنَ","di mana sahaja"],["مَا","di mana sahaja"],["كُنتُ","aku"],["وَأَوْصَـٰنِى","dan telah memerintahkan (kepada)ku"],["بِٱلصَّلَوٰةِ","[dari] solat"],["وَٱلزَّكَوٰةِ","dan zakat"],["مَا","selagi aku"],["دُمْتُ","selagi aku"],["حَيًّۭا","hidup"]]],"2282":["(Dan berbakti kepada ibuku) lafal Barran dinashabkan oleh lafal Ja'alani yang keberadaannya diperkirakan, maksudnya, Dia menjadikan aku sebagai orang yang berbakti kepada ibuku (dan Dia tidak menjadikan aku seorang yang sombong) orang yang merasa tinggi diri (lagi celaka) yang durhaka kepada Rabbnya.",[["وَبَرًّۢا","Dan berbakti"],["بِوَٰلِدَتِى","kepada ibu aku"],["وَلَمْ","dan bukan"],["يَجْعَلْنِى","Dia (telah) menjadikan aku"],["جَبَّارًۭا","kurang ajar"],["شَقِيًّۭا","tidak diberkati"]]],"2283":["(Dan kesejahteraan) dari Allah (semoga dilimpahkan kepadaku, pada hari aku dilahirkan, pada hari aku meninggal dan pada hari aku dibangkitkan hidup kembali)\" hal ini telah dikatakan pada kisah yang lalu, yaitu dalam doa Nabi Yahya.",[["وَٱلسَّلَـٰمُ","Dan damai sejahtera"],["عَلَىَّ","pada aku"],["يَوْمَ","(hari itu)."],["وُلِدتُّ","aku dilahirkan"],["وَيَوْمَ","dan (hari)."],["أَمُوتُ","aku akan mati"],["وَيَوْمَ","dan (hari) itu"],["أُبْعَثُ","Aku akan dibesarkan"],["حَيًّۭا","hidup"]]],"2284":["(Itulah Isa putra Maryam, yang mengatakan perkataan yang benar) jika lafal Alqaul dibaca Rafa', berarti menjadi Khabar dari Mubtada yang diperkirakan keberadaannya, maksudnya, perkataan Isa bin Maryam adalah perkataan yang benar. Kalau dibaca Nashab berarti ada lafal Qultu yang diperkirakan keberadaannya sebelumnya, maksudnya Aku mengatakan perkataan yang benar (yang mereka berbantah-bantahan tentang kebenarannya) lafal Yamtaruuna berasal dari kata Al Miryah; mereka meragukan kebenarannya, mereka adalah orang-orang Nasrani; mereka mengatakan perkataan yang dusta, yaitu, \"Sesungguhnya Isa itu adalah anak Allah\".",[["ذَٰلِكَ","Itu"],["عِيسَى","(adalah) Isa"],["ٱبْنُ","(si) anak lelaki"],["مَرْيَمَ ۚ","(dari) Maryam"],["قَوْلَ","satu kenyataan"],["ٱلْحَقِّ","(dari) kebenaran"],["ٱلَّذِى","itu yang"],["فِيهِ","mengenainya"],["يَمْتَرُونَ","mereka mempertikaikan"]]],"2285":["(Tidak layak bagi Allah mempunyai anak, Maha Suci Dia) dari hal tersebut. (Apabila Dia telah menetapkan sesuatu) yakni, Dia berkehendak untuk menciptakannya (maka Dia hanya berkata kepadanya, \"Jadilah\" maka jadilah dia) kalau dibaca Rafa' yaitu Yakuunu berarti ada lafal Huwa atau dia yang diperkirakan keberadaannya, kalau dibaca Nashab yaitu berarti dengan memperkirakan lafal An sebelumnya. Oleh sebab itu maka Nabi Isa diciptakan tanpa ayah.",[["مَا","Tidak"],["كَانَ","(ia) ialah"],["لِلَّهِ","kerana Allah"],["أَن","bahawa"],["يَتَّخِذَ","Dia patut ambil"],["مِن","mana-mana anak lelaki"],["وَلَدٍۢ ۖ","mana-mana anak lelaki"],["سُبْحَـٰنَهُۥٓ ۚ","Maha Suci Dia"],["إِذَا","Apabila"],["قَضَىٰٓ","Dia menetapkan"],["أَمْرًۭا","sesuatu perkara"],["فَإِنَّمَا","kemudian sahaja"],["يَقُولُ","Dia berkata"],["لَهُۥ","kepadanya"],["كُن","Jadilah"],["فَيَكُونُ","dan ia adalah"]]],"2286":["(Sesungguhnya Allah adalah Rabbku dan Rabb kalian, maka sembahlah Dia) jika dibaca Anna maka dengan memperkirakan keberadaan lafal Udzkur, maksudnya: Ingatlah, sesungguhnya Allah dan seterusnya. Jika dibaca Kasrah yaitu Inna maka dengan memperkirakan keberadaan lafal Qul sebelumnya, maksudnya: Katakanlah, sesungguhnya Allah; hal ini dibuktikan oleh firman lainnya, yaitu: Aku tidak pernah mengatakan kepada mereka melainkan apa yang Engkau perintahkan kepadaku untuk mengatakannya, yaitu, \"Sembahlah Allah, Rabbku dan Rabb kalian.\" (Q.S. Al-Maidah, 117). (ini) hal yang telah disebutkan tadi (adalah jalan) penuntun (yang lurus) yang dapat mengantarkan ke surga.",[["وَإِنَّ","Dan sesungguhnya"],["ٱللَّهَ","Allah"],["رَبِّى","(ialah) Tuhanku"],["وَرَبُّكُمْ","dan Tuhanmu"],["فَٱعْبُدُوهُ ۚ","maka sembahlah Dia"],["هَـٰذَا","Ini"],["صِرَٰطٌۭ","(adalah) jalan"],["مُّسْتَقِيمٌۭ","lurus"]]],"2287":["(Maka berselisihlah golongan-golongan yang ada di antara mereka) yakni orang-orang Nasrani, yaitu sehubungan dengan perihal Isa, apakah dia anak Allah, atau tuhan di samping Allah, ataukah tuhan yang ketiga. (Maka kecelakaanlah) azab yang sangat keras (bagi orang-orang kafir) disebabkan apa yang telah disebutkan tadi dan hal-hal lainnya (pada waktu menyaksikan hari yang besar) yakni kehadiran mereka di hari kiamat dan kengerian-kengerian yang terjadi pada waktu itu.",[["فَٱخْتَلَفَ","Tetapi berbeza"],["ٱلْأَحْزَابُ","mazhab-mazhab"],["مِنۢ","daripada kalangan mereka"],["بَيْنِهِمْ ۖ","daripada kalangan mereka"],["فَوَيْلٌۭ","jadi celaka"],["لِّلَّذِينَ","kepada mereka yang"],["كَفَرُوا۟","kufur"],["مِن","daripada"],["مَّشْهَدِ","(yang) bersaksi"],["يَوْمٍ","(dari) sehari"],["عَظِيمٍ","yang besar"]]],"2288":["(Alangkah terangnya pendengaran mereka dan alangkah tajamnya penglihatan mereka) kedua lafal ini merupakan Shighat atau ungkapan rasa takjub, maknanya sama dengan lafal Ma Asma'ahum dan Ma Absharahum (pada hari mereka datang kepada Kami) di akhirat kelak. (Tetapi orang-orang yang zalim) menurut ungkapan meletakkan isim Zhahir pada tempat isim Mudhmar' (pada hari ini) yakni di dunia (berada dalam kesesatan yang nyata) nyata kesesatannya, disebabkan mereka tuli tidak mau mendengarkan perkara yang hak, dan mereka buta tidak mau melihat yang benar. Maksudnya, hai orang yang diajak bicara sepatutnya kamu merasa takjub dan heran terhadap pendengaran dan penglihatan mereka di akhirat, sesudah di dunia mereka tuli dan buta.",[["أَسْمِعْ","Bagaimana mereka akan mendengar"],["بِهِمْ","Bagaimana mereka akan mendengar"],["وَأَبْصِرْ","dan bagaimana (mereka akan) melihat"],["يَوْمَ","(the) Hari"],["يَأْتُونَنَا ۖ","mereka akan datang kepada Kami"],["لَـٰكِنِ","tetapi"],["ٱلظَّـٰلِمُونَ","orang yang zalim"],["ٱلْيَوْمَ","hari ini"],["فِى","(ada) dalam"],["ضَلَـٰلٍۢ","ralat"],["مُّبِينٍۢ","yang nyata"]]],"2289":["(Dan berilah mereka peringatan) takut-takutilah hai Muhammad, orang-orang kafir Mekah itu (tentang hari penyesalan) yaitu hari kiamat sewaktu orang yang berbuat jahat merasa menyesal sekali karena tidak mau berbuat kebaikan di dunia (yaitu ketika segala perkara telah diputus) bagi mereka di hari kiamat, yaitu mereka harus menerima azab (Dan mereka) di dunia (dalam kelalaian) tentang hari penyesalan itu (dan mereka tidak pula beriman) kepada adanya hari penyesalan itu.",[["وَأَنذِرْهُمْ","Dan beri amaran kepada mereka"],["يَوْمَ","hari"],["ٱلْحَسْرَةِ","(dari) Penyesalan"],["إِذْ","apabila"],["قُضِىَ","telah diputuskan"],["ٱلْأَمْرُ","perkara itu"],["وَهُمْ","Dan mereka"],["فِى","(ada) dalam"],["غَفْلَةٍۢ","kelalaian"],["وَهُمْ","dan mereka"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"2290":["(Sesungguhnya Kami) lafal Nahnu berfungsi sebagai Taukid atau kata pengukuh (mewarisi bumi dan semua orang-orang yang ada di dalamnya) baik yang berakal maupun yang lainnya, yaitu dengan membinasakan mereka (dan hanya kepada Kamilah mereka dikembalikan) pada hari kiamat untuk menerima pembalasan.",[["إِنَّا","Sesungguhnya Kami"],["نَحْنُ","[Kami]"],["نَرِثُ","[Kami] akan mewarisi"],["ٱلْأَرْضَ","bumi"],["وَمَنْ","dan sesiapa"],["عَلَيْهَا","(ada) di atasnya"],["وَإِلَيْنَا","dan kepada Kami"],["يُرْجَعُونَ","mereka akan dikembalikan"]]],"2291":["(Dan ceritakanlah) kepada mereka (tentang Ibrahim di dalam Al-Kitab ini) Alquran, yaitu tentang kisahnya. (Sesungguhnya ia adalah seorang yang sangat membenarkan) seorang yang sangat jujur dalam keimanannya (lagi seorang nabi) hal ini dijelaskan dalam ayat selanjutnya.",[["وَٱذْكُرْ","Dan sebutkan"],["فِى","dalam"],["ٱلْكِتَـٰبِ","Kitab"],["إِبْرَٰهِيمَ ۚ","Ibrahim"],["إِنَّهُۥ","Sesungguhnya dia"],["كَانَ","adalah"],["صِدِّيقًۭا","seorang lelaki kebenaran"],["نَّبِيًّا","seorang Nabi"]]],"2292":["(Yaitu ketika ia berkata kepada bapaknya) yang bernama Azar, (\"Wahai bapakku!) huruf Ta pada lafal Abati ganti dari Ya Idhafah, karena keduanya tidak dapat dikumpulkan menjadi satu. Azar adalah penyembah berhala (Mengapa kamu menyembah sesuatu yang tidak mendengar, tidak melihat dan tidak dapat menolong kamu) tidak dapat mencukupimu (sedikit pun?) baik berupa manfaat maupun bahaya.",[["إِذْ","Apabila"],["قَالَ","dia berkata"],["لِأَبِيهِ","kepada bapanya"],["يَـٰٓأَبَتِ","Wahai ayahku"],["لِمَ","kenapa"],["تَعْبُدُ","(Apakah) kamu menyembah"],["مَا","itu yang"],["لَا","tidak"],["يَسْمَعُ","mendengar"],["وَلَا","dan bukan"],["يُبْصِرُ","nampak"],["وَلَا","dan bukan"],["يُغْنِى","faedah"],["عَنكَ","[kepada] kamu"],["شَيْـًۭٔا","(dalam) apa-apa"]]],"2293":["(Wahai bapakku! Sesungguhnya telah datang kepadaku sebagian ilmu pengetahuan yang tidak datang kepadamu, maka ikutilah aku, niscaya aku akan menunjukkan kepadamu jalan) penuntun (yang lurus) tidak menyimpang dari kebenaran.",[["يَـٰٓأَبَتِ","Wahai ayahku"],["إِنِّى","Sesungguhnya, [aku]"],["قَدْ","sesungguhnya"],["جَآءَنِى","(telah) datang kepada aku"],["مِنَ","daripada"],["ٱلْعِلْمِ","pengetahuan itu"],["مَا","apa"],["لَمْ","tidak"],["يَأْتِكَ","datang kepada kamu"],["فَٱتَّبِعْنِىٓ","jadi ikut aku"],["أَهْدِكَ","Aku akan membimbing kamu"],["صِرَٰطًۭا","jalan"],["سَوِيًّۭا","malah"]]],"2294":["(Wahai bapakku! Janganlah kamu menyembah setan) dengan ketaatanmu kepadanya, yaitu menyembah berhala. (Sesungguhnya setan itu durhaka kepada Tuhan Yang Maha Pemurah) yang banyak durhakanya.",[["يَـٰٓأَبَتِ","Wahai ayahku"],["لَا","Jangan"],["تَعْبُدِ","ibadah"],["ٱلشَّيْطَـٰنَ ۖ","syaitan"],["إِنَّ","Sesungguhnya"],["ٱلشَّيْطَـٰنَ","syaitan"],["كَانَ","ialah"],["لِلرَّحْمَـٰنِ","kepada Yang Maha Pemurah"],["عَصِيًّۭا","ingkar"]]],"2295":["(Wahai bapakku! Sesungguhnya aku khawatir bahwa kamu akan ditimpa azab dari Tuhan Yang Maha Pemurah) jika kamu tidak bertobat (maka kamu menjadi kawan bagi setan)\" yaitu menjadi penolong dan temannya di neraka.",[["يَـٰٓأَبَتِ","Wahai ayahku"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["أَن","bahawa"],["يَمَسَّكَ","akan menyentuh kamu"],["عَذَابٌۭ","azab"],["مِّنَ","daripada"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["فَتَكُونَ","jadi kamu akan menjadi"],["لِلشَّيْطَـٰنِ","kepada Syaitan"],["وَلِيًّۭا","seorang kawan"]]],"2296":["(Bapaknya berkata, \"Bencikah kamu kepada tuhan-tuhanku, hai Ibrahim?) maka sebab itu kamu mencelanya. (Jika kamu tidak berhenti) mencaci makinya (maka niscaya kamu akan kurajam) dengan batu, atau dengan perkataan yang jelek, maka hati-hatilah kamu terhadapku (dan tinggalkanlah aku buat waktu yang lama)\" yakni dalam masa yang lama.",[["قَالَ","Dia berkata"],["أَرَاغِبٌ","Adakah kamu benci"],["أَنتَ","Adakah kamu benci"],["عَنْ","(dari)"],["ءَالِهَتِى","tuhanku"],["يَـٰٓإِبْرَٰهِيمُ ۖ","Wahai Ibrahim"],["لَئِن","Pasti, jika"],["لَّمْ","tidak"],["تَنتَهِ","kamu berhenti"],["لَأَرْجُمَنَّكَ ۖ","pasti, aku akan merejam kamu"],["وَٱهْجُرْنِى","jadi tinggalkan aku"],["مَلِيًّۭا","(untuk) masa yang berpanjangan"]]],"2297":["(Ibrahim berkata, \"Semoga keselamatan dilimpahkan kepadamu) dariku, maksudnya aku tidak akan lagi menimpakan hal-hal yang tidak diinginkan kepadamu (aku akan memintakan ampun bagimu kepada Rabbku. Sesungguhnya Dia sangat baik kepadaku\") lafal Hafiyyan berasal dari lafal Hafaa, yang artinya sangat baik hingga Dia selalu memperkenankan doaku. Kemudian Nabi Ibrahim memenuhi janjinya itu, sebagaimana disebutkan di dalam surah Asy-Syu'ara, yaitu, \".. dan ampunilah bapakku...\" (Q.S. Asy-Syu'ara, 86). Hal ini dilakukan oleh Nabi Ibrahim sebelum jelas baginya bahwa bapaknya itu adalah musuh Allah, sebagaimana yang telah disebutkan di dalam surah At-Taubah.",[["قَالَ","Dia berkata"],["سَلَـٰمٌ","Damai (semoga)"],["عَلَيْكَ ۖ","pada kamu"],["سَأَسْتَغْفِرُ","Aku akan meminta ampun"],["لَكَ","bagi kamu"],["رَبِّىٓ ۖ","(dari) Tuhanku"],["إِنَّهُۥ","Sesungguhnya Dia"],["كَانَ","ialah"],["بِى","kepada aku"],["حَفِيًّۭا","Selalu Pemurah"]]],"2298":["(Dan aku akan menjauhkan diri daripada kalian dan daripada apa yang kalian seru) yang kalian sembah (selain Allah, dan aku akan berdoa) yakni aku akan menyembah (kepada Rabbku, mudah-mudahan aku dengan berdoa kepada Rabbku) dengan beribadah kepada-Nya (tidak akan kecewa)\" sebagaimana kalian kecewa karena menyembah berhala-berhala itu.",[["وَأَعْتَزِلُكُمْ","Dan aku akan tinggalkan kamu"],["وَمَا","dan apa"],["تَدْعُونَ","kamu menyeru"],["مِن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["وَأَدْعُوا۟","dan aku akan menyeru"],["رَبِّى","Tuhanku"],["عَسَىٰٓ","Boleh jadi"],["أَلَّآ","itu tidak"],["أَكُونَ","aku akan jadi"],["بِدُعَآءِ","dalam seruan"],["رَبِّى","(kepada) Tuhanku"],["شَقِيًّۭا","tidak diberkati"]]],"2299":["(Ketika Ibrahim sudah menjauhkan diri dari mereka dan dari apa yang mereka sembah selain Allah) dia pergi ke tanah suci (Kami anugerahkan kepadanya) dua orang putra yang menjadi penghibur hatinya (Ishak dan Yakub. Dan masing-masingnya) di antara keduanya (Kami angkat menjadi nabi).",[["فَلَمَّا","Maka apabila"],["ٱعْتَزَلَهُمْ","dia meninggalkan mereka"],["وَمَا","dan apa"],["يَعْبُدُونَ","mereka menyembah"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["وَهَبْنَا","[dan] Kami kurniakan"],["لَهُۥٓ","[kepada] dia"],["إِسْحَـٰقَ","Ishak"],["وَيَعْقُوبَ ۖ","dan Yaqub"],["وَكُلًّۭا","dan masing-masing (daripada mereka)"],["جَعَلْنَا","Kami buat"],["نَبِيًّۭا","seorang Nabi"]]],"2300":["(Dan Kami anugerahkan kepada mereka) bertiga Nabi Ibrahim, Nabi Ishak, dan Nabi Yakub (sebagian dari rahmat Kami,) berupa harta benda dan anak-anak (dan Kami jadikan mereka buah tutur yang baik lagi tinggi) mereka selalu menjadi pujian dan sanjungan semua pemeluk agama.",[["وَوَهَبْنَا","Dan Kami kurniakan"],["لَهُم","kepada mereka"],["مِّن","daripada"],["رَّحْمَتِنَا","Kerahiman Kami"],["وَجَعَلْنَا","dan Kami jadikan"],["لَهُمْ","bagi mereka"],["لِسَانَ","sebutan yang benar"],["صِدْقٍ","sebutan yang benar"],["عَلِيًّۭا","tinggi"]]],"2301":["(Dan ceritakanlah kisah Musa di dalam Alquran ini. Sesungguhnya ia adalah seorang yang mukhlis) dapat dibaca Mukhlishan dan Mukhlashan, artinya seorang yang ikhlas di dalam beribadah dan Allah membersihkan dirinya dari hal-hal yang kotor (di samping ia adalah seorang rasul dan nabi).",[["وَٱذْكُرْ","Dan sebutkan"],["فِى","dalam"],["ٱلْكِتَـٰبِ","Kitab"],["مُوسَىٰٓ ۚ","Musa"],["إِنَّهُۥ","Sesungguhnya dia"],["كَانَ","adalah"],["مُخْلَصًۭا","dipilih"],["وَكَانَ","dan adalah"],["رَسُولًۭا","seorang Rasul"],["نَّبِيًّۭا","seorang Nabi"]]],"2302":["(Dan Kami telah memanggilnya) melalui firman-Nya, \"Hai Musa! Sesungguhnya Aku adalah Allah...\" (Q.S. Al-Qashash, 30). (dari arah Thur) nama sebuah bukit (sebelah kanan) yakni dari sebelah kanan Nabi Musa ketika ia baru datang dari negeri Madyan (dan Kami telah mendekatkannya kepada Kami waktu dia munajat) bermunajat, yaitu Allah memperdengarkan Kalam-Nya kepadanya.",[["وَنَـٰدَيْنَـٰهُ","Dan Kami panggil dia"],["مِن","daripada"],["جَانِبِ","(sisi)."],["ٱلطُّورِ","(dari) Gunung"],["ٱلْأَيْمَنِ","yang betul"],["وَقَرَّبْنَـٰهُ","dan membawanya dekat"],["نَجِيًّۭا","(untuk) perbualan"]]],"2303":["(Dan Kami telah menganugerahkan kepadanya sebagian rahmat Kami) sebagian dari nikmat Kami (yaitu saudaranya, Harun) Lafal Haruna menjadi Badal atau Athaf Bayan (menjadi seorang nabi) lafal Nabiyyan ini menjadi Hal atau kata keterangan yang dimaksud daripada pemberian itu; hal ini merupakan pengabulan dari doa Nabi Musa sendiri yang meminta kepada Allah, supaya Dia mengangkat saudara tuanya menjadi rasul pula.",[["وَوَهَبْنَا","Dan Kami kurniakan"],["لَهُۥ","[kepada] dia"],["مِن","daripada"],["رَّحْمَتِنَآ","Kerahiman Kami"],["أَخَاهُ","abangnya"],["هَـٰرُونَ","Harun"],["نَبِيًّۭا","seorang Nabi"]]],"2304":["(Dan ceritakanlah kisah Ismail di dalam Alquran. Sesungguhnya ia adalah seorang yang benar janjinya) sekali-kali ia tidak menjanjikan sesuatu melainkan ia memenuhinya. Disebutkan bahwa ia pernah menunggu seseorang yang telah berjanji kepadanya, selama tiga hari atau satu tahun, sehingga orang yang berjanji itu datang kepadanya di tempat yang dijanjikan itu, dan ternyata Nabi Ismail masih menunggu di tempat itu (dan dia adalah seorang rasul) untuk kabilah Jurhum (dan nabi).",[["وَٱذْكُرْ","Dan sebutkan"],["فِى","dalam"],["ٱلْكِتَـٰبِ","Kitab"],["إِسْمَـٰعِيلَ ۚ","Ismail"],["إِنَّهُۥ","Sesungguhnya dia"],["كَانَ","adalah"],["صَادِقَ","benar"],["ٱلْوَعْدِ","(dengan) janjinya"],["وَكَانَ","dan adalah"],["رَسُولًۭا","seorang Rasul"],["نَّبِيًّۭا","seorang Nabi"]]],"2305":["(Dan ia menyuruh ahlinya) yakni kaumnya (untuk salat dan menunaikan zakat dan ia adalah seorang yang diridai di sisi Rabbnya) lafal Mardhiyyan asalnya Mardhuwwun, kedua huruf Wawunya diganti menjadi Ya. Selanjutnya harakat Dhammah Dhadhnya diganti menjadi Kasrah, akhirnya jadi Mardhiyyun, oleh karena kedudukannya menjadi Khabar Kaana maka bacaannya menjadi Mardhiyyan.",[["وَكَانَ","Dan dia menggunakan"],["يَأْمُرُ","(untuk) menyuruh"],["أَهْلَهُۥ","(pada) umatnya"],["بِٱلصَّلَوٰةِ","solat"],["وَٱلزَّكَوٰةِ","dan zakat"],["وَكَانَ","dan adalah"],["عِندَ","dekat"],["رَبِّهِۦ","Tuhannya"],["مَرْضِيًّۭا","menggembirakan"]]],"2306":["(Dan ceritakanlah kisah Idris di dalam Alquran) Nabi Idris adalah buyut Nabi Ibrahim atau ayah kakek Nabi Nuh (Sesungguhnya ia adalah seorang yang sangat membenarkan dan seorang nabi).",[["وَٱذْكُرْ","Dan sebutkan"],["فِى","dalam"],["ٱلْكِتَـٰبِ","Kitab"],["إِدْرِيسَ ۚ","Idris"],["إِنَّهُۥ","Sesungguhnya dia"],["كَانَ","adalah"],["صِدِّيقًۭا","jujur"],["نَّبِيًّۭا","seorang Nabi"]]],"2307":["(Dan Kami telah mengangkatnya ke martabat yang tinggi) ia masih tetap hidup sampai sekarang bertempat di langit keempat atau keenam, atau ketujuh atau berada di dalam surga. Ia dimasukkan ke dalam surga setelah terlebih dahulu mencicipi rasanya mati lalu dihidupkan kembali, setelah itu ia tidak mau keluar lagi dari dalam surga.",[["وَرَفَعْنَـٰهُ","Dan Kami telah membangkitkannya"],["مَكَانًا","(ke) jawatan"],["عَلِيًّا","tinggi"]]],"2308":["(Mereka itu) kalimat ini menjadi Mubtada (adalah orang-orang yang telah diberi nikmat oleh Allah) menjadi sifat daripada lafal Ulaaika (yaitu para nabi) menjadi Bayan atau keterangan dari lafal Ulaaika yang kedudukannya sama dengan sifat. Lafal-lafal yang sesudahnya sampai kepada Jumlah Syarat menjadi sifat dari lafal Nabiyyiin. Maka firman-Nya (dari keturunan Adam) yakni Nabi Idris (dan dari orang-orang yang Kami muatkan bersama Nuh) di dalam bahteranya, maksudnya adalah Nabi Ibrahim yaitu cucu daripada anak Nabi Nuh yang bernama Sam (dan dari keturunan Ibrahim) yakni Nabi Ismail dan Nabi Ishaq serta Nabi Yakub, (dan) dari keturunan (Israel) yang dimaksud adalah Nabi Musa, Nabi Harun, Nabi Zakaria, Nabi Yahya, dan Nabi Isa (dan dari orang-orang yang telah Kami beri petunjuk dan telah Kami pilih) daripada mereka. Khabar dari lafal Ulaaika yang di permulaan ayat tadi ialah (\"Apabila dibacakan kepada mereka ayat-ayat Allah Yang Maha Pemurah, maka mereka menyungkur dengan bersujud dan menangis\"). Lafal Sujjadan dan Bukiyyan adalah bentuk jamak dari lafal Saajidun dan Baakin. Maksudnya jadilah kalian orang-orang seperti mereka. Asal kata Bukiyyun adalah Bukiwyun, kemudian huruf Wawunya diganti menjadi Ya dan harakat Dhammahnya diganti pula dengan Kasrah, sehingga menjadi Buhiyyun.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) orang-orang yang"],["أَنْعَمَ","Allah kurniakan nikmat"],["ٱللَّهُ","Allah kurniakan nikmat"],["عَلَيْهِم","ke atas mereka"],["مِّنَ","daripada (antara)"],["ٱلنَّبِيِّـۧنَ","para Nabi"],["مِن","daripada"],["ذُرِّيَّةِ","(the) zuriat"],["ءَادَمَ","(dari) Adam"],["وَمِمَّنْ","dan daripada mereka"],["حَمَلْنَا","Kami membawa"],["مَعَ","dengan"],["نُوحٍۢ","Nuh"],["وَمِن","dan daripada"],["ذُرِّيَّةِ","(the) zuriat"],["إِبْرَٰهِيمَ","(dari) Ibrahim"],["وَإِسْرَٰٓءِيلَ","dan Israel"],["وَمِمَّنْ","dan daripada (mereka) yang"],["هَدَيْنَا","Kami membimbing"],["وَٱجْتَبَيْنَآ ۚ","dan Kami pilih"],["إِذَا","Apabila"],["تُتْلَىٰ","telah dibacakan"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتُ","(the) Ayat"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["خَرُّوا۟","mereka jatuh"],["سُجَّدًۭا","sujud"],["وَبُكِيًّۭا ۩","dan menangis"]]],"2309":["(Maka datanglah sesudah mereka pengganti yang jelek yang menyia-nyiakan salat) dengan cara meninggalkannya seperti orang-orang Yahudi dan Nasrani (dan memperturutkan hawa nafsunya) gemar melakukan perbuatan-perbuatan maksiat (maka mereka kelak akan menemui kesesatan) ghayya adalah nama sebuah lembah di neraka Jahanam, mereka akan dijerumuskan ke dalamnya.",[["۞ فَخَلَفَ","Kemudian berjaya"],["مِنۢ","selepas mereka"],["بَعْدِهِمْ","selepas mereka"],["خَلْفٌ","pengganti"],["أَضَاعُوا۟","yang lalai"],["ٱلصَّلَوٰةَ","solat"],["وَٱتَّبَعُوا۟","dan mereka mengikut"],["ٱلشَّهَوَٰتِ ۖ","nafsu"],["فَسَوْفَ","tidak lama lagi"],["يَلْقَوْنَ","mereka akan berjumpa"],["غَيًّا","jahat"]]],"2310":["(Kecuali) yakni berbeda halnya dengan (orang yang bertobat, beriman dan beramal saleh, mereka itu akan masuk surga dan mereka tidak dianiaya) tidak dirugikan (barang sedikit pun) dari pahala mereka.",[["إِلَّا","Kecuali"],["مَن","(satu) siapa"],["تَابَ","bertaubat"],["وَءَامَنَ","dan beriman"],["وَعَمِلَ","dan lakukan"],["صَـٰلِحًۭا","kebaikan (perbuatan)"],["فَأُو۟لَـٰٓئِكَ","Kemudian mereka"],["يَدْخُلُونَ","akan masuk"],["ٱلْجَنَّةَ","Syurga"],["وَلَا","dan bukan"],["يُظْلَمُونَ","mereka akan dizalimi"],["شَيْـًۭٔا","(dalam) apa-apa"]]],"2311":["(Yaitu surga Adn) menjadi tempat tinggal mereka. Lafaz 'Adn menjadi Badal daripada lafal Jannatin (yang telah dijanjikan oleh Tuhan Yang Maha Pemurah kepada hamba-hamba-Nya, sekalipun surga itu tidak tampak). Lafal Bil Ghaibi menjadi Hal, maksudnya walaupun surga itu tidak kelihatan oleh mereka. (Sesungguhnya janji Allah itu) yakni apa yang telah dijanjikan oleh-Nya (pasti akan ditepati). Lafal Ma'tiyyan maknanya Aatiyan; asalnya adalah Ma'tiwyun. Yang dimaksud dengan janji-Nya adalah surga yang akan ditempati oleh orang-orang yang berhak memasukinya.",[["جَنَّـٰتِ","Taman-taman"],["عَدْنٍ","(dari) Eden"],["ٱلَّتِى","yang"],["وَعَدَ","dijanjikan"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["عِبَادَهُۥ","(kepada) hamba-hamba-Nya"],["بِٱلْغَيْبِ ۚ","dengan perkara ghaib"],["إِنَّهُۥ","Sesungguhnya, [ia]"],["كَانَ","ialah"],["وَعْدُهُۥ","janji dia"],["مَأْتِيًّۭا","pasti datang"]]],"2312":["(Mereka tidak mendengar perkataan yang tidak berguna di dalam surga) pembicaraan yang tak berarti (kecuali) mereka hanya mendengar (ucapan Salam) dari para Malaikat buat mereka, atau dari sebagian mereka kepada sebagian yang lain. (Bagi mereka rezekinya di surga itu tiap-tiap pagi dan petang) dalam perkiraan kedua waktu tersebut menurut perhitungan waktu di dunia, karena sesungguhnya di dalam surga itu tidak ada siang dan malam tetapi yang ada hanyalah cahaya dan nur yang abadi.",[["لَّا","Tidak"],["يَسْمَعُونَ","mereka akan mendengar"],["فِيهَا","di dalamnya"],["لَغْوًا","cakap kosong"],["إِلَّا","tetapi"],["سَلَـٰمًۭا ۖ","kedamaian"],["وَلَهُمْ","Dan untuk mereka"],["رِزْقُهُمْ","(adalah) peruntukan mereka"],["فِيهَا","di dalamnya"],["بُكْرَةًۭ","pagi"],["وَعَشِيًّۭا","dan petang"]]],"2313":["(Itulah surga yang akan Kami wariskan) Kami anugerahkan dan Kami tempatkan di dalamnya (kepada hamba-hamba Kami yang selalu bertakwa) yang berlaku taat kepada-Nya. Ayat berikut diturunkan ketika wahyu datang sangat terlambat selama beberapa hari, kemudian Nabi saw. berkata kepada malaikat Jibril ketika datang kepadanya, \"Apakah gerangan yang menyebabkan engkau tidak menziarahi aku selama ini\".",[["تِلْكَ","Ini"],["ٱلْجَنَّةُ","(ialah) Syurga"],["ٱلَّتِى","yang"],["نُورِثُ","Kami berikan (sebagai) pusaka"],["مِنْ","[daripada] (kepada)"],["عِبَادِنَا","hamba kita"],["مَن","(yang) siapa"],["كَانَ","ialah"],["تَقِيًّۭا","soleh"]]],"2314":["(Dan tidaklah kami turun melainkan dengan perintah Rabbmu, kepunyaan-Nyalah apa-apa yang ada di hadapan kita) yakni berupa semua perkara akhirat (apa-apa yang ada di belakang kita) berupa semua perkara duniawi (dan apa-apa yang ada di antara keduanya) apa yang ada dalam waktu sekarang sampai dengan datangnya hari kiamat. Yang dimaksud ialah bahwa pengetahuan mengenai kesemuanya itu berada pada-Nya (dan tidaklah Rabbmu lupa) lafal Nasiyyan bermakna Naasiyan, maksudnya, Allah tidak akan meninggalkanmu disebabkan wahyu yang terlambat datang kepadamu.",[["وَمَا","Dan tidak"],["نَتَنَزَّلُ","kami turun"],["إِلَّا","kecuali"],["بِأَمْرِ","oleh (the) Perintah"],["رَبِّكَ ۖ","Tuhanmu"],["لَهُۥ","KepunyaanNya (milik)"],["مَا","apa"],["بَيْنَ","(ada) di hadapan kita"],["أَيْدِينَا","(ada) di hadapan kita"],["وَمَا","dan apa"],["خَلْفَنَا","(ada) di belakang kita"],["وَمَا","dan apa"],["بَيْنَ","(adalah) antara"],["ذَٰلِكَ ۚ","bahawa"],["وَمَا","Dan tidak"],["كَانَ","ialah"],["رَبُّكَ","Tuhanmu"],["نَسِيًّۭا","pelupa"]]],"2315":["Dia adalah (Rabb) yang menguasai (langit dan bumi dan apa-apa yang ada di antara keduanya, maka sembahlah Dia dan berteguh hatilah dalam beribadah kepada-Nya) bersikap sabarlah dalam menjalankan dua perkara tersebut. (Apakah kamu mengetahui ada seorang yang sama dengan Dia) yang patut disembah seperti Dia, tentu saja tidak.",[["رَّبُّ","Tuhan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَا","(adalah) antara keduanya"],["فَٱعْبُدْهُ","maka sembahlah Dia"],["وَٱصْطَبِرْ","dan berterusan"],["لِعِبَـٰدَتِهِۦ ۚ","dalam ibadah-Nya"],["هَلْ","buat"],["تَعْلَمُ","kamu tahu"],["لَهُۥ","untuk Dia"],["سَمِيًّۭا","sebarang persamaan"]]],"2316":["(Dan berkata manusia,) mereka yang ingkar kepada adanya hari berbangkit, yaitu Ubay bin Khalaf atau Walid bin Mughirah, ayat ini diturunkan berkenaan dengan sikapnya itu (\"Betulkah apabila) dapat dibaca Aidza dan Ayidza (aku telah mati, bahwa aku sungguh-sungguh akan dibangkitkan menjadi hidup kembali?\") yakni akan dihidupkan kembali dari kuburan sebagaimana yang telah dikatakan oleh Muhammad. Kata tanya di sini mengandung makna Nafi atau kalimat negatif, maksudnya, Aku tidak akan dihidupkan kembali sesudah mati. Huruf Ma adalah Zaidah yang faedahnya untuk mengukuhkan kalimat, demikian pula huruf Lamnya. Kemudian Allah menyanggah perkataan mereka itu melalui firman-Nya:",[["وَيَقُولُ","Dan berkata"],["ٱلْإِنسَـٰنُ","lelaki itu"],["أَءِذَا","Apa! apabila"],["مَا","Apa! apabila"],["مِتُّ","aku sudah mati"],["لَسَوْفَ","pasti akan"],["أُخْرَجُ","aku dibawa keluar"],["حَيًّا","hidup"]]],"2317":["(Dan tidakkah manusia itu memikirkan) asal kata Yadzdzakkaru ini adalah Yatadzakkaru, kemudian huruf Ta diganti menjadi Dzal, lalu diidghamkan ke dalam huruf Dzal asal sehingga menjadi Yadzdzakkaru. Tetapi menurut qiraat yang lain dibaca Yadzkuru (bahwa sesungguhnya Kami telah menciptakannya dahulu, sedangkan ia tidak ada sama sekali) oleh karenanya mengapa ia tidak mengambil kesimpulan dari permulaan itu kepada pengembalian, yakni kembali kepada-Nya.",[["أَوَلَا","tidak"],["يَذْكُرُ","ingat"],["ٱلْإِنسَـٰنُ","lelaki itu"],["أَنَّا","bahawa Kami"],["خَلَقْنَـٰهُ","Kami cipta dia"],["مِن","sebelum"],["قَبْلُ","sebelum"],["وَلَمْ","manakala tidak"],["يَكُ","dia adalah"],["شَيْـًۭٔا","sesuatu"]]],"2318":["(Demi Rabbmu, sesungguhnya akan Kami bangkitkan mereka) orang-orang yang ingkar kepada adanya hari berbangkit itu (bersama dengan setan) Kami mengumpulkan masing-masing dari mereka bersama setan-setannya dalam keadaan terbelenggu (kemudian akan Kami datangkan mereka ke sekeliling Jahanam) dari luarnya (dengan berlutut) berjalan dengan lututnya. Lafal Jitsiyyan adalah bentuk jamak dari lafal jaatsin, asal katanya adalah Jitsuwwun atau Jitsuwyun yang akar katanya berasal dari Jatsaa-Yajtsuu atau Jatsaa Yajtsii. Ada dua pendapat sehubungan dengan lafal ini.",[["فَوَرَبِّكَ","Maka demi Tuhanmu"],["لَنَحْشُرَنَّهُمْ","sesungguhnya Kami akan mengumpulkan mereka"],["وَٱلشَّيَـٰطِينَ","dan syaitan"],["ثُمَّ","kemudian"],["لَنُحْضِرَنَّهُمْ","sesungguhnya Kami akan mendatangkan mereka"],["حَوْلَ","sekeliling"],["جَهَنَّمَ","Neraka"],["جِثِيًّۭا","bengkok (di) lutut"]]],"2319":["(Kemudian pasti akan Kami tarik dari tiap-tiap golongan) yakni setiap kelompok dari mereka (siapa di antara mereka yang sangat durhaka kepada Tuhan Yang Maha Pemurah) sangat berani berbuat durhaka kepada-Nya.",[["ثُمَّ","Kemudian"],["لَنَنزِعَنَّ","sesungguhnya Kami akan mengheret"],["مِن","daripada"],["كُلِّ","setiap"],["شِيعَةٍ","mazhab"],["أَيُّهُمْ","mereka"],["أَشَدُّ","(yang) paling teruk"],["عَلَى","terhadap"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["عِتِيًّۭا","(dalam) pemberontakan"]]],"2320":["(Dan kemudian Kami sungguh lebih mengetahui orang-orang yang lebih utama terhadapnya) lebih berhak terhadap Jahanam, yaitu orang yang sangat durhaka kepada-Nya dan orang-orang yang sama seperti mereka (untuk dimasukkan ke dalamnya) yang lebih utama masuk Jahanam dan lebih layak untuk menempatinya. Maka Kami memulai dengan mereka. Asal kata Shiliyyun adalah Shiliwyun, berasal dari Fi'il Shaliya atau Shalaa.",[["ثُمَّ","Kemudian"],["لَنَحْنُ","pasti, Kami"],["أَعْلَمُ","tahu yang terbaik"],["بِٱلَّذِينَ","[dari] mereka yang"],["هُمْ","[mereka]"],["أَوْلَىٰ","(adalah) paling layak"],["بِهَا","di dalamnya"],["صِلِيًّۭا","(dari) dibakar"]]],"2321":["(Dan tidak) (daripada kalian) seorang pun (melainkan mendatangi neraka itu) neraka Jahanam. (Hal itu bagi Rabbmu adalah suatu kemestian yang sudah ditetapkan) telah dipastikan dan telah diputuskan oleh-Nya, hal ini tidak akan diabaikan-Nya.",[["وَإِن","Dan (ada) tidak"],["مِّنكُمْ","(mana-mana) daripada kamu"],["إِلَّا","tetapi"],["وَارِدُهَا ۚ","(akan) melewatinya"],["كَانَ","(Ini) ialah"],["عَلَىٰ","ke atas"],["رَبِّكَ","Tuhanmu"],["حَتْمًۭا","suatu yang tidak dapat dielakkan"],["مَّقْضِيًّۭا","diputuskan"]]],"2322":["(Kemudian Kami akan menyelamatkan) dapat dibaca Nunajjii dan Nunjii (orang-orang yang bertakwa) orang-orang yang memelihara dirinya dari kemusyrikan dan kekafiran, Kami akan selamatkan daripadanya (dan Kami akan membiarkan orang-orang yang zalim) orang-orang yang melakukan kemusyrikan dan kekafiran (di dalam neraka dalam keadaan berlutut) berdiri di atas lutut mereka.",[["ثُمَّ","Kemudian"],["نُنَجِّى","Kami akan hantar"],["ٱلَّذِينَ","orang yang"],["ٱتَّقَوا۟","ditakuti (Allah)"],["وَّنَذَرُ","dan Kami akan pergi"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["فِيهَا","di dalamnya"],["جِثِيًّۭا","bengkok (di) lutut"]]],"2323":["(Dan apabila dibacakan kepada mereka) yaitu mereka orang-orang Mukmin dan orang-orang kafir (ayat-ayat Kami) dari Alquran (yang terang) jelas keadaan dan maksudnya (niscaya orang-orang yang kafir berkata kepada orang-orang yang beriman, \"Manakah di antara kedua golongan) kami dan kalian (yang lebih baik tempat tinggalnya) yaitu, tempat menetap dan rumahnya. Lafal Maqaaman berasal dari kata kerja Qaama, kalau dibaca Muqaaman berarti berasal dari kata kerja Aqaama (dan lebih indah tempat pertemuannya\"). Lafal Nadiyyan bermakna An-Naadi artinya tempat berkumpulnya kaum, yang mereka berbincang-bincang di dalamnya. Mereka bermaksud bahwa kamilah yang lebih baik daripada kalian. Kemudian Allah berfirman,",[["وَإِذَا","Dan apabila"],["تُتْلَىٰ","dibacakan"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتُنَا","Ayat Kami"],["بَيِّنَـٰتٍۢ","yang nyata"],["قَالَ","berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لِلَّذِينَ","kepada mereka yang"],["ءَامَنُوٓا۟","beriman"],["أَىُّ","yang mana"],["ٱلْفَرِيقَيْنِ","(dari) dua kumpulan itu"],["خَيْرٌۭ","(lebih) baik"],["مَّقَامًۭا","(dalam) kedudukan"],["وَأَحْسَنُ","dan terbaik"],["نَدِيًّۭا","(dalam) perhimpunan"]]],"2324":["(\"Berapa banyak) alangkah banyaknya (umat yang telah Kami binasakan sebelum mereka) yaitu umat-umat di masa silam (sedangkan mereka adalah lebih bagus alat rumah tangganya) yakni harta bendanya lebih banyak dan perabotan rumah tangga mereka jauh lebih bagus (dan lebih sedap dipandang mata\") lebih indah dipandang mata. Lafal Ri'yan berasal dari kata Ar-Ru'yah. Maksudnya, sebagaimana Kami telah membinasakan umat-umat dahulu disebabkan kekafirannya, maka Kami pun akan membinasakan mereka pula.",[["وَكَمْ","Dan berapa banyak"],["أَهْلَكْنَا","Kami musnahkan"],["قَبْلَهُم","sebelum mereka"],["مِّن","daripada"],["قَرْنٍ","satu generasi"],["هُمْ","mereka"],["أَحْسَنُ","(adalah) lebih baik"],["أَثَـٰثًۭا","(dalam) harta benda"],["وَرِءْيًۭا","dan rupa"]]],"2325":["(Katakanlah! \"Barang siapa yang berada di dalam kesesatan) kalimat ayat ini mengandung syarat sedangkan Jawabnya ialah (maka biarlah diperpanjang) kalimat perintah di sini bermakna kalimat berita, artinya hendaknya diperpanjang (tempo baginya oleh Yang Maha Pemurah dengan sesungguhnya) di dunia ini dengan memperturutkan apa yang ia kehendaki (sehingga apabila mereka telah melihat apa yang diancamkan kepadanya, baik siksa) seperti dibunuh dan ditahan (maupun kiamat) yang pengertiannya mencakup juga neraka Jahanam tempat mereka dimasukkan ke dalamnya (maka mereka akan mengetahui siapa yang lebih jelek kedudukannya dan lebih lemah penolong-penolongnya\") yakni pembantu-pembantunya; apakah mereka ataukah orang-orang yang beriman, pembantu-pembantu mereka adalah setan sedangkan pembantu-pembantu orang-orang yang beriman di dalam menghadapi mereka adalah para Malaikat.",[["قُلْ","Katakanlah"],["مَن","Siapa pun"],["كَانَ","ialah"],["فِى","dalam"],["ٱلضَّلَـٰلَةِ","[kesalahan]."],["فَلْيَمْدُدْ","maka pasti akan memanjang"],["لَهُ","baginya"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["مَدًّا ۚ","sambungan"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["رَأَوْا۟","mereka lihat"],["مَا","apa"],["يُوعَدُونَ","mereka telah dijanjikan"],["إِمَّا","sama ada"],["ٱلْعَذَابَ","azab"],["وَإِمَّا","atau"],["ٱلسَّاعَةَ","Jam itu"],["فَسَيَعْلَمُونَ","maka mereka akan tahu"],["مَنْ","yang"],["هُوَ","[dia]"],["شَرٌّۭ","(adalah) paling teruk"],["مَّكَانًۭا","(dalam) kedudukan"],["وَأَضْعَفُ","dan lebih lemah"],["جُندًۭا","(dalam) angkatan"]]],"2326":["(Dan Allah akan menambah kepada mereka yang telah mendapat petunjuk) berkat iman mereka (hidayah) berkat ayat-ayat yang diturunkan kepada mereka (Dan amal-amal saleh yang kekal itu) yaitu ketaatan kepada Allah yang selalu dilakukan oleh seseorang (lebih baik pahalanya di sisi Rabbmu dan lebih baik kesudahannya) akhir dan kesudahan daripadanya, berbeda dengan amal perbuatan orang-orang kafir. Pengertian perbandingan kebaikan di sini sebagai kebalikan daripada perkataan orang-orang kafir, yaitu ketika mereka mengatakan, \"Manakah di antara kedua golongan yang lebih baik kedudukannya?\"",[["وَيَزِيدُ","Dan Allah menambah"],["ٱللَّهُ","Dan Allah menambah"],["ٱلَّذِينَ","orang yang"],["ٱهْتَدَوْا۟","menerima hidayah"],["هُدًۭى ۗ","(dalam) bimbingan"],["وَٱلْبَـٰقِيَـٰتُ","Dan yang kekal"],["ٱلصَّـٰلِحَـٰتُ","perbuatan baik"],["خَيْرٌ","(adalah) lebih baik"],["عِندَ","dekat"],["رَبِّكَ","Tuhanmu"],["ثَوَابًۭا","(untuk) pahala"],["وَخَيْرٌۭ","dan lebih baik"],["مَّرَدًّا","(untuk) pulangan"]]],"2327":["(Maka apakah kamu telah melihat orang yang kafir kepada ayat-ayat Kami) maksudnya 'Ashi bin Wa'il (dan ia mengatakan,) kepada Khabbab bin Art yang mengatakan kepadanya, bahwa engkau kelak akan dibangkitkan hidup kembali sesudah mati. Pada saat itu Khabbab sedang menagih utang kepadanya (\"Pasti aku akan diberi) seandainya aku dibangkitkan hidup kembali (harta dan anak\") maka pada saat itu aku akan membayar utangku kepadamu. Allah berfirman menyanggahnya:",[["أَفَرَءَيْتَ","Kemudian, adakah kamu melihat"],["ٱلَّذِى","dia yang"],["كَفَرَ","kufur"],["بِـَٔايَـٰتِنَا","dalam Ayat-ayat Kami"],["وَقَالَ","dan berkata"],["لَأُوتَيَنَّ","Pasti, aku akan diberikan"],["مَالًۭا","kekayaan"],["وَوَلَدًا","dan kanak-kanak"]]],"2328":["(Adakah dia melihat yang gaib) apakah dia mengetahuinya sehingga ia berani mengatakan, bahwa dia akan diberi seperti apa yang dikatakannya itu. Lafal Aththala'a ini disebabkan sudah cukup hanya dengan memakai Hamzah Istifham, maka Hamzah Washalnya dibuang (atau ia telah membuat perjanjian di sisi Tuhan Yang Maha Pemurah?) sehingga ia berani mengatakan, bahwa Allah akan memberikan kepadanya apa yang telah dikatakannya itu.",[["أَطَّلَعَ","Adakah dia telah melihat"],["ٱلْغَيْبَ","(ke dalam) perkara ghaib"],["أَمِ","atau"],["ٱتَّخَذَ","adakah dia telah mengambil"],["عِندَ","daripada"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["عَهْدًۭا","sebuah janji"]]],"2329":["(Sekali-kali tidak) hal itu tidak akan diberikan kepadanya (Kami akan menulis) Kami memerintahkan untuk menuliskan (apa yang ia katakan itu dan benar-benar Kami akan memperpanjang azab baginya) Kami akan menambahkan kepada azab kekafirannya azab yang lain, karena perkataannya itu.",[["كَلَّا ۚ","Bahkan"],["سَنَكْتُبُ","Kami akan merakam"],["مَا","apa"],["يَقُولُ","katanya"],["وَنَمُدُّ","dan Kami akan memanjangkan"],["لَهُۥ","baginya"],["مِنَ","daripada"],["ٱلْعَذَابِ","azab"],["مَدًّۭا","secara meluas"]]],"2330":["(Dan Kami akan mewarisi apa yang ia katakan itu) yaitu harta benda dan anak (dan ia akan datang kepada Kami) kelak pada hari kiamat (dengan seorang diri) dalam keadaan tidak punya harta benda dan tidak punya anak.",[["وَنَرِثُهُۥ","Dan Kami akan mewarisinya"],["مَا","apa"],["يَقُولُ","katanya"],["وَيَأْتِينَا","dan dia akan datang kepada Kami"],["فَرْدًۭا","bersendirian"]]],"2331":["(Dan mereka telah mengambil) orang-orang kafir Mekah (selain dari Allah) yakni berhala-berhala (sebagai tuhan-tuhan) yang mereka sembah (agar tuhan-tuhan itu menjadi pelindung bagi mereka) maksudnya memberikan syafaat kepada mereka di hadapan Allah supaya mereka jangan diazab oleh-Nya.",[["وَٱتَّخَذُوا۟","Dan mereka telah mengambil"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["ءَالِهَةًۭ","tuhan"],["لِّيَكُونُوا۟","bahawa mereka mungkin"],["لَهُمْ","bagi mereka"],["عِزًّۭا","satu penghormatan"]]],"2332":["(Sekali-kali tidak) tiada sesuatu pun yang dapat mencegah azab mereka. (Kelak mereka itu akan mengingkari) yakni tuhan-tuhan sembahan mereka itu (penyembahan mereka) artinya mereka akan mengingkari penyembahan orang-orang yang mempertuhankan mereka, sebagaimana dijelaskan pula oleh ayat lain, yaitu firman-Nya, \"Mereka sekali-kali tidak menyembah Kami...\" (Q.S. Al-Qashash, 63). (dan tuhan-tuhan itu akan menjadi musuh bagi mereka) yakni berhala-berhala itu justru akan menjadi musuh orang-orang yang menyembahnya kelak di akhirat.",[["كَلَّا ۚ","Bahkan"],["سَيَكْفُرُونَ","mereka akan menafikan"],["بِعِبَادَتِهِمْ","ibadat mereka (kepada mereka)"],["وَيَكُونُونَ","dan mereka akan menjadi"],["عَلَيْهِمْ","terhadap mereka"],["ضِدًّا","pihak lawan"]]],"2333":["(Tidakkah kamu lihat, bahwasanya Kami telah mengirim setan-setan itu) yakni pengaruh mereka (kepada orang-orang kafir untuk menghasut mereka) untuk menggerakkan mereka melakukan perbuatan-perbuatan maksiat (dengan sungguh-sungguh).",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّآ","bahawa Kami"],["أَرْسَلْنَا","[Kami] telah menghantar"],["ٱلشَّيَـٰطِينَ","syaitan"],["عَلَى","ke atas"],["ٱلْكَـٰفِرِينَ","orang kafir"],["تَؤُزُّهُمْ","menghasut mereka"],["أَزًّۭا","(dengan) hasutan"]]],"2334":["(Maka janganlah kamu tergesa-gesa terhadap mereka) untuk mendatangkan azab buat mereka (karena sesungguhnya Kami hanya menghitung untuk mereka) hari-hari atau nafas-nafas mereka (dengan perhitungan yang teliti) hingga tiba saatnya azab mereka.",[["فَلَا","Jadi (jangan)"],["تَعْجَلْ","tergesa-gesa"],["عَلَيْهِمْ ۖ","terhadap mereka"],["إِنَّمَا","Hanya"],["نَعُدُّ","Kami mengira"],["لَهُمْ","bagi mereka"],["عَدًّۭا","nombor"]]],"2335":["Ingatlah (hari ketika Kami mengumpulkan orang-orang yang takwa) berkat keimanan mereka (kepada Tuhan Yang Maha Pemurah sebagai perutusan yang terhormat). Lafal Wafdun adalah bentuk jamak dan lafal Waafidun, artinya delegasi.",[["يَوْمَ","(The) Hari"],["نَحْشُرُ","Kami akan berkumpul"],["ٱلْمُتَّقِينَ","orang yang soleh"],["إِلَى","kepada"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["وَفْدًۭا","(sebagai) perwakilan"]]],"2336":["(Dan Kami akan menghalau orang-orang yang durhaka) karena kekafiran mereka (ke neraka Jahanam dalam keadaan dahaga). Lafal Wirdun adalah bentuk jamak dari lafal Waaridun artinya berjalan dalam keadaan dahaga.",[["وَنَسُوقُ","Dan Kami akan memandu"],["ٱلْمُجْرِمِينَ","penjenayah"],["إِلَىٰ","kepada"],["جَهَنَّمَ","Neraka"],["وِرْدًۭا","dahaga"]]],"2337":["(Mereka tidak dapat memberi) manusia semuanya (syafaat kecuali orang yang telah mengadakan perjanjian di sisi Tuhan Yang Maha Pemurah) yakni kesaksian bahwa tiada Tuhan selain Allah dan tiada daya serta tiada kekuatan melainkan berkat pertolongan Allah.",[["لَّا","Tidak"],["يَمْلِكُونَ","mereka akan mempunyai kuasa"],["ٱلشَّفَـٰعَةَ","(dari) syafaat"],["إِلَّا","kecuali"],["مَنِ","(dia) siapa"],["ٱتَّخَذَ","telah mengambil"],["عِندَ","daripada"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["عَهْدًۭا","sebuah perjanjian"]]],"2338":["(Dan mereka berkata,) orang-orang Yahudi dan Nasrani dan orang-orang yang menyangka bahwa malaikat-malaikat itu adalah anak-anak perempuan Allah (\"Tuhan Yang Maha Pemurah mempunyai anak\") maka Allah menyanggah perkataan mereka itu melalui firman-Nya,",[["وَقَالُوا۟","Dan mereka berkata"],["ٱتَّخَذَ","Telah mengambil"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["وَلَدًۭا","seorang anak lelaki"]]],"2339":["(\"Sesungguhnya kalian telah mendatangkan sesuatu perkara yang sangat mungkar) yaitu suatu perkara mungkar yang sangat besar.",[["لَّقَدْ","Sesungguhnya"],["جِئْتُمْ","kamu telah mengemukakan"],["شَيْـًٔا","sesuatu perkara"],["إِدًّۭا","kejam"]]],"2340":["(Hampir-hampir) dapat dibaca Takaadu dan Yakaadu (langit pecah) terbelah, dan menurut qiraat yang lain lafal Yatafaththarna dibaca Yanfathirna (karena ucapan itu dan bumi belah dan gunung-gunung runtuh) yakni terbalik menindih mereka disebabkan.",[["تَكَادُ","hampir"],["ٱلسَّمَـٰوَٰتُ","langit"],["يَتَفَطَّرْنَ","terkoyak"],["مِنْهُ","daripadanya"],["وَتَنشَقُّ","dan berpecah belah"],["ٱلْأَرْضُ","bumi"],["وَتَخِرُّ","dan runtuh"],["ٱلْجِبَالُ","gunung itu"],["هَدًّا","(dalam) kemusnahan"]]],"2341":["(mereka mendakwakan Allah Yang Maha Pemurah mempunyai anak\"). Allah berfirman,",[["أَن","Itu"],["دَعَوْا۟","mereka menyeru"],["لِلرَّحْمَـٰنِ","kepada Yang Maha Pemurah"],["وَلَدًۭا","seorang anak lelaki"]]],"2342":["(\"Dan tidak layak bagi Allah Yang Maha Pemurah mempunyai anak\") yakni tidak patut bagi-Nya hal yang demikian itu.",[["وَمَا","Dan tidak"],["يَنۢبَغِى","adalah sesuai"],["لِلرَّحْمَـٰنِ","untuk Yang Maha Pemurah"],["أَن","bahawa"],["يَتَّخِذَ","Dia patut ambil"],["وَلَدًا","seorang anak lelaki"]]],"2343":["(Tidak ada) (seorang pun di langit dan di bumi melainkan akan datang kepada Tuhan Yang Maha Pemurah selaku seorang hamba) yang hina dan tunduk patuh kepada-Nya kelak di hari kiamat, termasuk Uzair dan Isa juga.",[["إِن","Tidak"],["كُلُّ","semua"],["مَن","yang"],["فِى","(ada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["إِلَّآ","tetapi"],["ءَاتِى","(akan) datang"],["ٱلرَّحْمَـٰنِ","(kepada) Yang Maha Pemurah"],["عَبْدًۭا","(sebagai) hamba"]]],"2344":["(Sesungguhnya Allah telah menentukan jumlah mereka dan menghitung mereka dengan hitungan yang teliti) maka tidak samar bagi-Nya mengenai jumlah mereka secara keseluruhan atau pun secara rinci dan tiada seorang pun yang terlewat dari perhitungan-Nya.",[["لَّقَدْ","Sesungguhnya"],["أَحْصَىٰهُمْ","Dia telah menghitung mereka"],["وَعَدَّهُمْ","dan mengira mereka"],["عَدًّۭا","pengiraan"]]],"2345":["(Dan tiap-tiap mereka akan datang kepada Allah pada hari kiamat dengan sendiri-sendiri) tanpa harta dan tanpa pembantu yang dapat membelanya.",[["وَكُلُّهُمْ","Dan kesemuanya"],["ءَاتِيهِ","(akan) datang (kepada)Nya"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["فَرْدًا","bersendirian"]]],"2346":["(Sesungguhnya orang-orang yang beriman dan beramal saleh, kelak Allah Yang Maha Pemurah akan menanamkan dalam hati mereka rasa kasih sayang) di antara sesama mereka; mereka saling kasih-mengasihi dan sayang-menyayangi dan Allah swt. mencintai mereka semuanya.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan baik"],["سَيَجْعَلُ","akan mengurniakan"],["لَهُمُ","bagi mereka"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["وُدًّۭا","kasih sayang"]]],"2347":["(Maka sesungguhnya telah Kami mudahkan dia) Alquran itu (dengan bahasamu) bahasa Arab (agar kamu dapat memberi kabar gembira dengan Alquran itu kepada orang-orang yang bertakwa) yaitu orang-orang yang beruntung memperoleh iman (dan agar kamu memberi peringatan) menakut-nakuti (dengannya kepada kaum yang membangkang). Lafal Luddan adalah bentuk jamak dari lafal Aladdun artinya banyak membantah dengan kebatilan, mereka adalah orang-orang kafir Mekah.",[["فَإِنَّمَا","Jadi, hanya"],["يَسَّرْنَـٰهُ","Kami (telah) memudahkannya"],["بِلِسَانِكَ","dalam lidah kamu"],["لِتُبَشِّرَ","supaya kamu memberi khabar gembira"],["بِهِ","dengannya"],["ٱلْمُتَّقِينَ","(kepada) orang-orang yang soleh"],["وَتُنذِرَ","dan memberi amaran"],["بِهِۦ","dengannya"],["قَوْمًۭا","suatu kaum"],["لُّدًّۭا","bermusuhan"]]],"2348":["(Dan berapa banyak) banyak sekali (telah Kami binasakan umat-umat sebelum mereka) umat-umat di masa silam disebabkan kedustaan mereka terhadap Rasul (Adakah kamu melihat) menemukan (seorang pun dari mereka atau kamu dengar suara mereka yang samar-samar?) Tentu saja tidak. Sebagaimana Kami telah membinasakan umat-umat di masa silam maka niscaya pula Kami akan membinasakan mereka, disebabkan kekafiran mereka itu.",[["وَكَمْ","Dan berapa banyak"],["أَهْلَكْنَا","Kami (telah) memusnahkan"],["قَبْلَهُم","sebelum mereka"],["مِّن","daripada"],["قَرْنٍ","satu generasi"],["هَلْ","boleh"],["تُحِسُّ","kamu rasa"],["مِنْهُم","daripada mereka"],["مِّنْ","sebarang"],["أَحَدٍ","satu"],["أَوْ","atau"],["تَسْمَعُ","dengar"],["لَهُمْ","daripada mereka"],["رِكْزًۢا","satu bunyi"]]],"2349":["(Tha Ha) hanya Allahlah yang mengetahui maksudnya",[["طه","Ta Ha"]]],"2350":["(Kami tidak menurunkan Alquran ini kepadamu) hai Muhammad (agar kamu menjadi susah) supaya kamu letih dan payah disebabkan apa yang kamu kerjakan sesudah ia diturunkan, sehingga kamu harus berkepanjangan berdiri di dalam melakukan salat malam. Maksudnya berilah kesempatan istirahat bagi dirimu.",[["مَآ","Tidak"],["أَنزَلْنَا","Kami (telah) menurunkan"],["عَلَيْكَ","kepada kamu"],["ٱلْقُرْءَانَ","al-Quran"],["لِتَشْقَىٰٓ","agar kamu tertekan"]]],"2351":["(Tetapi) Kami turunkan Alquran ini (sebagai peringatan) melalui apa yang dikandungnya (bagi orang yang takut) kepada Allah.",[["إِلَّا","(Tetapi)"],["تَذْكِرَةًۭ","(sebagai) peringatan"],["لِّمَن","untuk (mereka) yang"],["يَخْشَىٰ","bertakwa"]]],"2352":["(Yaitu diturunkan) lafal Tanziilan ini menjadi Badal dari lafal Fi'il yang menashabkannya, yakni Nazzalahu Tanziilan (dari Allah yang menciptakan bumi dan langit yang tinggi). Lafal Al 'Ula merupakan bentuk jamak dari kata 'Ulyaa, keadaannya sama dengan lafal Kubraa dan Kubar.",[["تَنزِيلًۭا","Satu wahyu"],["مِّمَّنْ","daripada (Dia) Siapa"],["خَلَقَ","dicipta"],["ٱلْأَرْضَ","bumi"],["وَٱلسَّمَـٰوَٰتِ","dan syurga"],["ٱلْعُلَى","[yang] tinggi"]]],"2353":["Yaitu (Tuhan Yang Maha Pemurah, yang di atas Arasy) lafal Arasy ini menurut pengertian bahasa diartikan singgasana raja (berkuasa) yakni bersemayam sesuai dengan keagungan dan kebesaran-Nya.",[["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["عَلَى","atas"],["ٱلْعَرْشِ","takhta"],["ٱسْتَوَىٰ","ditegakkan"]]],"2354":["(Kepunyaan-Nyalah semua yang ada di langit, semua yang ada di bumi, semua yang ada di antara keduanya) yakni makhluk-makhluk yang ada di antara keduanya (dan semua yang di bawah tanah) yaitu lapisan tanah yang masih basah, yang dimaksud adalah di bawah semua lapisan bumi yang tujuh, karena lapisan bumi yang berjumlah tujuh itu berada di bawah lapisan tanah yang basah.",[["لَهُۥ","KepunyaanNya (milik)"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["وَمَا","dan apa sahaja"],["بَيْنَهُمَا","(adalah) di antara mereka"],["وَمَا","dan apa sahaja"],["تَحْتَ","(ada) di bawah"],["ٱلثَّرَىٰ","tanah"]]],"2355":["(Dan jika kamu mengeraskan ucapanmu) di dalam berzikir atau berdoa, maka sesungguhnya Allah tidak memerlukan suara keras engkau sewaktu melakukan hal tersebut (maka sesungguhnya Dia mengetahui rahasia dan yang lebih tersembunyi) daripada rahasia, maksudnya adalah semua apa yang ada dalam hati manusia yang tidak diungkapkannya, maka janganlah engkau memayahkan dirimu dengan mengeraskan suaramu.",[["وَإِن","Dan jika"],["تَجْهَرْ","kamu bercakap dengan kuat"],["بِٱلْقَوْلِ","perkataan itu"],["فَإِنَّهُۥ","maka sesungguhnya Dia"],["يَعْلَمُ","mengetahui"],["ٱلسِّرَّ","rahsia"],["وَأَخْفَى","dan lebih tersembunyi"]]],"2356":["(Dialah Allah, tidak ada Tuhan melainkan Dia, Dia mempunyai Asmaulhusna) jumlahnya sebanyak yang disebutkan di dalam hadis yaitu sembilan puluh sembilan nama-nama yang baik. Lafal Al Husna bentuk Muannats daripada lafal Al Ahsan.",[["ٱللَّهُ","Allah"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["لَهُ","KepunyaanNya (milik)"],["ٱلْأَسْمَآءُ","Nama-nama"],["ٱلْحُسْنَىٰ","yang Maha Indah"]]],"2357":["(Apakah) telah (datang kepadamu kisah Musa?)",[["وَهَلْ","Dan telah"],["أَتَىٰكَ","datang kepada kamu"],["حَدِيثُ","penceritaan itu"],["مُوسَىٰٓ","(dari) Musa"]]],"2358":["(Ketika ia melihat api, lalu berkatalah ia kepada keluarganya) yakni kepada istrinya, (\"Tinggallah kamu) di sini, hal itu terjadi sewaktu ia berada dalam perjalanan dari Madyan menuju ke negeri Mesir (sesungguhnya aku melihat) menyaksikan (api, mudah-mudahan aku dapat membawa sedikit daripadanya untuk kalian) berupa obor yang dinyalakan pada sumbu atau kayu (atau aku akan mendapatkan petunjuk di tempat itu\") yang dapat menunjukkan jalan; karena pada saat itu Nabi Musa kehilangan arah jalan disebabkan gelapnya malam. Nabi Musa mengungkapkan kata-katanya dengan memakai istilah La'alla yang artinya mudah-mudahan karena ia merasa kurang pasti dengan apa yang telah dijanjikannya itu.",[["إِذْ","Apabila"],["رَءَا","dia nampak"],["نَارًۭا","api"],["فَقَالَ","lalu dia berkata"],["لِأَهْلِهِ","kepada keluarganya"],["ٱمْكُثُوٓا۟","Tinggal di sini"],["إِنِّىٓ","sesungguhnya, aku"],["ءَانَسْتُ","[Aku] merasakan"],["نَارًۭا","api"],["لَّعَلِّىٓ","mungkin aku (boleh)"],["ءَاتِيكُم","bawa kamu"],["مِّنْهَا","daripadanya"],["بِقَبَسٍ","jenama yang terbakar"],["أَوْ","atau"],["أَجِدُ","aku dapati"],["عَلَى","di"],["ٱلنَّارِ","api"],["هُدًۭى","bimbingan"]]],"2359":["(Maka ketika ia datang ke tempat api itu) yaitu di pohon 'Ausaj (ia dipanggil, \"Hai Musa!)",[["فَلَمَّآ","Kemudian apabila"],["أَتَىٰهَا","dia datang kepadanya"],["نُودِىَ","dia dipanggil"],["يَـٰمُوسَىٰٓ","Wahai Musa"]]],"2360":["(Sesungguhnya Aku) dibaca Innii karena dengan menganggap lafal Nudiya bermakna Qiila. Dan bila dibaca Annii maka diperkirakan adanya huruf Ba sebelumnya (inilah) lafal Anaa di sini berfungsi mentaukidkan makna yang terkandung di dalam Ya Mutakallim (Rabbmu, maka tanggalkanlah kedua terompahmu; sesungguhnya kamu berada di lembah yang suci) lembah yang disucikan, atau lembah yang diberkati (Thuwa) menjadi Badal atau 'Athaf Bayan. Kalau dibaca Thuwan maka dianggap sebagai nama tempat saja dan jika dibaca Thuwa dalam bentuk lafal yang Muannats, maka dianggap sebagai nama daerah dan 'Alamiyah, sehingga tidak menerima harakat Tanwin.",[["إِنِّىٓ","Sesungguhnya, [aku]"],["أَنَا۠","Aku"],["رَبُّكَ","Tuhanmu"],["فَٱخْلَعْ","jadi keluarkan"],["نَعْلَيْكَ ۖ","kasut kamu"],["إِنَّكَ","Sesungguhnya kamu"],["بِٱلْوَادِ","(berada) di lembah"],["ٱلْمُقَدَّسِ","yang suci"],["طُوًۭى","(daripada) Tuwa"]]],"2361":["(Dan Aku telah memilih kamu) dari kaummu (maka dengarkanlah apa yang akan diwahyukan kepadamu) dari-Ku.",[["وَأَنَا","Dan aku"],["ٱخْتَرْتُكَ","(telah) memilih kamu"],["فَٱسْتَمِعْ","jadi dengar"],["لِمَا","ke apa"],["يُوحَىٰٓ","didedahkan"]]],"2362":["(Sesungguhnya Aku ini adalah Allah, tiada Tuhan selain Aku, maka sembahlah Aku dan dirikanlah salat untuk mengingat Aku) di dalam salat itu.",[["إِنَّنِىٓ","Sesungguhnya, [aku]"],["أَنَا","Aku"],["ٱللَّهُ","Allah"],["لَآ","(Ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّآ","tetapi"],["أَنَا۠","aku"],["فَٱعْبُدْنِى","maka sembahlah Aku"],["وَأَقِمِ","dan mendirikan"],["ٱلصَّلَوٰةَ","solat"],["لِذِكْرِىٓ","untuk ingatan-Ku"]]],"2363":["(Sesungguhnya hari kiamat itu akan datang Aku merahasiakan waktunya) dari manusia dan menampakkan kepada mereka hanya dekatnya hari kiamat melalui alamat-alamatnya supaya mendapatkan balasan) di hari itu (tiap-tiap diri itu dengan apa yang ia usahakan) apakah kebaikan ataukah keburukan.",[["إِنَّ","Sesungguhnya"],["ٱلسَّاعَةَ","Jam itu"],["ءَاتِيَةٌ","(akan) datang"],["أَكَادُ","aku hampir"],["أُخْفِيهَا","[Aku] menyembunyikannya"],["لِتُجْزَىٰ","itu boleh dibalas"],["كُلُّ","setiap"],["نَفْسٍۭ","jiwa"],["بِمَا","bagi apa"],["تَسْعَىٰ","ia berusaha"]]],"2364":["(Maka sekali-kali janganlah kamu dipalingkan) dibelokkan (daripadanya) dari iman kepada adanya hari kiamat (oleh orang yang tidak beriman kepadanya dan oleh orang yang mengikuti hawa nafsunya) untuk ingkar kepada adanya hari kiamat (yang menyebabkan kamu jadi binasa\") sedangkan mereka pasti akan binasa.",[["فَلَا","Jadi (jangan)"],["يَصُدَّنَّكَ","(biarkan) mengelakkan kamu"],["عَنْهَا","daripadanya"],["مَن","(satu) siapa"],["لَّا","tidak"],["يُؤْمِنُ","beriman"],["بِهَا","di dalamnya"],["وَٱتَّبَعَ","dan mengikuti"],["هَوَىٰهُ","keinginannya"],["فَتَرْدَىٰ","supaya kamu tidak binasa"]]],"2365":["(Apakah itu) yang berada (di tangan kananmu, hai Musa?) Kata tanya atau Istifham di sini mengandung makna Taqrir, maksudnya supaya Allah menurunkan mukjizat kepada Nabi Musa dengan melalui tongkatnya itu.",[["وَمَا","Dan apa"],["تِلْكَ","(ialah) itu"],["بِيَمِينِكَ","di tangan kanan kamu"],["يَـٰمُوسَىٰ","Wahai Musa"]]],"2366":["(Berkata Musa, \"Ini adalah tongkatku, aku bertelekan) berpegangan (padanya) sewaktu aku melompat dan berjalan (dan aku pukul) aku memukul daun-daun pohon (dengannya) supaya daun-daun itu berjatuhan (untuk kambingku) lalu kambing-kambingku itu memakannya (dan bagiku ada lagi padanya keperluan). Lafal Ma'aarib adalah bentuk jamak dari lafal Ma'ribah atau Ma'rabah atau Ma'rubah, artinya keperluan-keperluan (yang lain\") seperti untuk memikul bekal dan air minum, serta untuk mengusir binatang buas. Kemudian Allah menambahkan jawaban, sebagai penjelasan bahwa pada tongkat itu masih terdapat kegunaan lainnya, yaitu:",[["قَالَ","Dia berkata"],["هِىَ","Ia"],["عَصَاىَ","(adalah) kakitangan aku"],["أَتَوَكَّؤُا۟","aku bersandar"],["عَلَيْهَا","atasnya"],["وَأَهُشُّ","dan aku menurunkan daun"],["بِهَا","dengannya"],["عَلَىٰ","bagi"],["غَنَمِى","domba aku"],["وَلِىَ","dan untuk aku"],["فِيهَا","di dalamnya"],["مَـَٔارِبُ","(adalah) kegunaan"],["أُخْرَىٰ","lain"]]],"2367":["(Allah berfirman, \"Lemparkanlah tongkat itu, hai Musa!\")",[["قَالَ","Dia berkata"],["أَلْقِهَا","Buang ke bawah"],["يَـٰمُوسَىٰ","Wahai Musa"]]],"2368":["(Lalu dilemparkannyalah tongkat itu, maka tiba-tiba ia menjadi seekor ular) yang sangat besar (yang merayap) yakni berjalan cepat dengan perutnya seperti ular kecil, di dalam ayat lain disebutkan Al Jaan, bukan Hayyatun.",[["فَأَلْقَىٰهَا","Jadi dia melemparkannya ke bawah"],["فَإِذَا","dan lihatlah"],["هِىَ","Ia"],["حَيَّةٌۭ","(adalah) seekor ular"],["تَسْعَىٰ","bergerak dengan pantas"]]],"2369":["(Allah berfirman, \"Peganglah ia dan jangan takut) kepadanya (Kami akan mengembalikannya kepada keadaannya) lafal Siiratahaa dinashabkan dengan mencabut huruf Jarnya, maksudnya ke dalam bentuknya (yang semula) kemudian Nabi Musa memasukkan tangannya ke mulut ular besar itu, maka kembalilah kepada keadaan semula yaitu menjadi tongkat lagi. Jelaslah bahwa tempat untuk memasukkan tangannya adalah tempat pegangan tongkat, yaitu di antara kedua rahang ular tersebut. Allah swt. sengaja memperlihatkan hal itu kepada Nabi Musa, supaya ia jangan kaget bila tongkat itu berubah menjadi ular besar di hadapan raja Firaun nanti.",[["قَالَ","Dia berkata"],["خُذْهَا","rebutlah"],["وَلَا","dan jangan"],["تَخَفْ ۖ","bertakwa"],["سَنُعِيدُهَا","Kami akan mengembalikannya"],["سِيرَتَهَا","(kepada) keadaannya"],["ٱلْأُولَىٰ","yang dahulu"]]],"2370":["(Dan kepitkanlah tanganmu) yang sebelah kanan, yang dimaksud adalah telapak tangannya (ke ketiakmu) yakni dijepitkan pada tubuhmu yang sebelah kiri, yaitu pada tempat antara ketiak dan lenganmu, kemudian keluarkanlah ia (niscaya ia keluar) dalam keadaan berbeda dengan warna kulit yang sebelumnya, yaitu (menjadi putih cemerlang tanpa cacat) putih bersinar dengan cemerlang sebagaimana sinar matahari, dan sinarnya itu menyilaukan pandangan mata (sebagai mukjizat yang lain) tangan itu bisa menjadi putih bersinar; lafal Baidhaa'a dan lafal Aayatan Ukhraa keduanya menjadi Hal atau kata keterangan keadaan bagi Dhamir yang terkandung di dalam lafal Takhruj.",[["وَٱضْمُمْ","Dan mendekatlah"],["يَدَكَ","tangan kamu"],["إِلَىٰ","kepada"],["جَنَاحِكَ","sebelah kamu"],["تَخْرُجْ","ia akan keluar"],["بَيْضَآءَ","putih"],["مِنْ","tanpa sebarang"],["غَيْرِ","tanpa sebarang"],["سُوٓءٍ","penyakit"],["ءَايَةً","(sebagai) tanda"],["أُخْرَىٰ","yang lain"]]],"2371":["(Untuk Kami perlihatkan kepadamu) Kami sengaja melakukan hal itu bilamana kamu sewaktu-waktu mau menggunakannya, untuk memperlihatkan kepadamu (sebagian tanda-tanda kekuasaan Kami) bukti kekuasaan Kami (yang sangat besar) bukti yang besar bagi kerasulanmu. Apabila Nabi Musa hendak mengembalikan tangannya seperti semula, maka ia mengepitkannya lagi pada ketiaknya seperti yang dilakukannya semula, kemudian mengeluarkannya kembali.",[["لِنُرِيَكَ","Supaya Kami perlihatkan kepadamu"],["مِنْ","daripada"],["ءَايَـٰتِنَا","Tanda-Tanda Kami"],["ٱلْكُبْرَى","yang Terhebat"]]],"2372":["(Pergilah) sebagai seorang Rasul (kepada Firaun) dan orang-orang yang mengikutinya (sesungguhnya ia telah melampaui batas)\" sangat keterlaluan di dalam kekafirannya, hingga ia berani mengaku menjadi tuhan.",[["ٱذْهَبْ","Pergi"],["إِلَىٰ","kepada"],["فِرْعَوْنَ","Firaun"],["إِنَّهُۥ","Sesungguhnya dia"],["طَغَىٰ","(telah) melanggar"]]],"2373":["(Berkata Musa, \"Ya Rabbku! Lapangkanlah untukku dadaku,) maksudnya lapangkanlah dadaku supaya mampu mengemban risalah-Mu.",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["ٱشْرَحْ","Kembangkan"],["لِى","untuk aku"],["صَدْرِى","payudara aku"]]],"2374":["(Dan mudahkanlah) permudahlah (untukku urusanku) supaya aku dapat menyampaikannya.",[["وَيَسِّرْ","Dan kemudahan"],["لِىٓ","untuk aku"],["أَمْرِى","tugas aku"]]],"2375":["(Dan lepaskanlah kekakuan dari lidahku) keadaan ini terjadi sejak lidahnya terbakar bara api yang ia masukkan ke dalam mulutnya sewaktu masih kecil.",[["وَٱحْلُلْ","Dan buka ikatan"],["عُقْدَةًۭ","(the) knot"],["مِّن","daripada"],["لِّسَانِى","lidah aku"]]],"2376":["(Supaya mereka mengerti) yakni dapat memahami (perkataanku) di waktu aku menyampaikan risalah kepada mereka.",[["يَفْقَهُوا۟","Supaya mereka faham"],["قَوْلِى","ucapan aku"]]],"2377":["(Dan jadikanlah untukku seorang pembantu) orang yang membantuku di dalam menyampaikan risalah-Mu (dari keluargaku).",[["وَٱجْعَل","Dan melantik"],["لِّى","untuk aku"],["وَزِيرًۭا","seorang menteri"],["مِّنْ","daripada"],["أَهْلِى","keluarga aku"]]],"2378":["(Yaitu Harun) lafal Haaruna menjadi Maf'ul Tsani (saudaraku) lafal Akhii menjadi 'Athaf Rayan.",[["هَـٰرُونَ","Harun"],["أَخِى","abang aku"]]],"2379":["(Teguhkanlah dengan dia kekuatanku) kemampuanku.",[["ٱشْدُدْ","Mengukuhkan"],["بِهِۦٓ","melalui dia"],["أَزْرِى","kekuatan aku"]]],"2380":["(Dan jadikanlah ia sekutu dalam urusanku) yakni ikut mengemban risalah ini. Kedua Fi'il tadi yaitu Usydud dan Asyrik dapat pula dibaca sebagai Fi'il Mudhari' yang dijazamkan sehingga menjadi Asydud Bihi dan Usyrik-hu, keduanya merupakan Jawab dari Thalab atau permintaan.",[["وَأَشْرِكْهُ","Dan buat dia berkongsi"],["فِىٓ","[dalam]"],["أَمْرِى","tugas aku"]]],"2381":["(Supaya kami dapat bertasbih kepada-Mu) yakni melakukan tasbih (dengan banyak).",[["كَىْ","Itu"],["نُسَبِّحَكَ","kami boleh memuliakan Engkau"],["كَثِيرًۭا","banyak"]]],"2382":["(Dan dapat mengingat-Mu) berzikir kepada-Mu (dengan banyak pula).",[["وَنَذْكُرَكَ","Dan [kami] mengingati Engkau"],["كَثِيرًا","banyak"]]],"2383":["(Sesungguhnya Engkau adalah Maha Mengetahui keadaan kami)\" Maha Mengetahuinya, oleh sebab itu maka Engkau akan memberikan nikmat-Mu kepadaku dengan mengangkat Harun menjadi Rasul.",[["إِنَّكَ","Sesungguhnya, [Engkau]"],["كُنتَ","kamu adalah"],["بِنَا","daripada kita"],["بَصِيرًۭا","Maha Melihat"]]],"2384":["(Allah berfirman, \"Sesungguhnya telah dikabulkan permintaanmu, hai Musa) sebagai anugerah Kami kepadamu.",[["قَالَ","Dia berkata"],["قَدْ","Sesungguhnya"],["أُوتِيتَ","kamu dianugerahkan"],["سُؤْلَكَ","permintaan kamu"],["يَـٰمُوسَىٰ","Wahai Musa"]]],"2385":["(Dan sesungguhnya Kami telah memberi nikmat kepadamu pada kali yang lain).",[["وَلَقَدْ","Dan sesungguhnya"],["مَنَنَّا","Kami menganugerahkan nikmat"],["عَلَيْكَ","pada kamu"],["مَرَّةً","lain kali"],["أُخْرَىٰٓ","lain kali"]]],"2386":["(Yaitu ketika) lafal Idz di sini mengandung makna Ta'lil (mengilhamkan kepada ibumu) di dalam mimpi, atau berupa inspirasi, yaitu sewaktu ibumu melahirkan dirimu, dan ia merasa khawatir Firaun akan membunuhmu bersama-sama dengan anak-anak lelaki lainnya yang baru dilahirkan saat itu (suatu yang diilhamkan\") mengenai urusanmu. Selanjutnya dijelaskan ilham tersebut dalam firman selanjutnya:",[["إِذْ","Apabila"],["أَوْحَيْنَآ","Kami memberi inspirasi"],["إِلَىٰٓ","kepada"],["أُمِّكَ","ibu kamu"],["مَا","apa"],["يُوحَىٰٓ","diilhamkan"]]],"2387":["(Yaitu, \"Letakkanlah ia) tarohlah ia (di dalam sebuah peti, kemudian lemparkanlah ia) yakni peti itu (ke sungai) yakni sungai Nil (maka pasti sungai itu membawanya ke tepi) ke pinggirnya. Kata perintah di sini mengandung makna kalimat berita (supaya diambil oleh musuh-Ku dan musuhnya) yaitu raja Firaun. (Dan Aku telah melimpahkan) sesudah Firaun mengambil anakmu darimu (kepadamu kasih sayang yang datang daripada-Ku) supaya semua orang merasa kasih sayang kepadamu, lalu Firaun akan merasa sayang kepadamu, demikian pula setiap orang yang melihatmu (dan supaya kamu diasuh di bawah pengawasan-Ku) kamu dipelihara di bawah asuhan dan penjagaan-Ku.",[["أَنِ","Itu"],["ٱقْذِفِيهِ","buang dia"],["فِى","dalam"],["ٱلتَّابُوتِ","dada"],["فَٱقْذِفِيهِ","kemudian membuangnya"],["فِى","dalam"],["ٱلْيَمِّ","sungai itu"],["فَلْيُلْقِهِ","kemudian biarkan membuangnya"],["ٱلْيَمُّ","sungai itu"],["بِٱلسَّاحِلِ","di bank"],["يَأْخُذْهُ","akan membawanya"],["عَدُوٌّۭ","seorang musuh"],["لِّى","kepada-Ku"],["وَعَدُوٌّۭ","dan musuh"],["لَّهُۥ ۚ","kepadanya"],["وَأَلْقَيْتُ","Dan aku membuang"],["عَلَيْكَ","atas kamu"],["مَحَبَّةًۭ","cinta"],["مِّنِّى","daripada Aku"],["وَلِتُصْنَعَ","dan supaya kamu dibesarkan"],["عَلَىٰ","bawah"],["عَيْنِىٓ","mata aku"]]],"2388":["(Yaitu ketika) lafal Idz di sini bermakna Ta'lil (saudaramu yang perempuan berjalan) namanya Maryam untuk menyelidiki beritamu. Karena sesungguhnya Firaun dan keluarganya telah mendatangkan orang-orang perempuan yang menyusui, sedangkan kamu tidak mau menerima air susu seorang pun di antara mereka (lalu ia berkata, 'Bolehkah saya menunjukkan kepada kalian orang yang akan memeliharanya?') kemudian usulnya itu ternyata diperkenankan oleh keluarga Firaun, maka segera Maryam mendatangkan ibunya, lalu Nabi Musa mau menerima air susunya. (Maka Kami mengembalikanmu kepada ibumu, agar senang hatinya) karena bertemu kembali denganmu (dan tidak berduka cita) sejak saat itu. (Dan kamu pernah membunuh seorang manusia) yaitu seorang bangsa Qibti di Mesir. Maka kamu merasa susah dan khawatir setelah membunuh orang itu terhadap pembalasan raja Firaun (lalu Kami selamatkan kamu dari kesusahan dan Kami telah mencobamu dengan beberapa cobaan) Kami telah mengujimu dengan beberapa cobaan selain dari peristiwa itu, kemudian Kami selamatkan pula kamu daripadanya (maka kamu tinggal beberapa tahun) yakni selama sepuluh tahun (di antara penduduk Madyan) sesudah kamu datang ke tempat itu dari negeri Mesir, yaitu kamu tinggal di tempat Nabi Syuaib yang kemudian ia mengawinkanmu dengan putrinya (kemudian kamu datang menurut waktu yang ditetapkan) di dalam ilmu-Ku dengan membawa risalah, yaitu dalam usia empat puluh tahun (hai Musa!).",[["إِذْ","Apabila"],["تَمْشِىٓ","sedang pergi"],["أُخْتُكَ","adik kamu"],["فَتَقُولُ","dan dia berkata"],["هَلْ","hendaklah"],["أَدُلُّكُمْ","aku tunjukkan"],["عَلَىٰ","[ke]"],["مَن","(satu) siapa"],["يَكْفُلُهُۥ ۖ","akan menyusu dan membesarkannya"],["فَرَجَعْنَـٰكَ","Maka Kami kembalikan kamu"],["إِلَىٰٓ","kepada"],["أُمِّكَ","ibu kamu"],["كَىْ","bahawa"],["تَقَرَّ","boleh disejukkan"],["عَيْنُهَا","matanya"],["وَلَا","dan bukan"],["تَحْزَنَ ۚ","dia bersedih"],["وَقَتَلْتَ","Dan kamu membunuh"],["نَفْسًۭا","seorang lelaki"],["فَنَجَّيْنَـٰكَ","tetapi Kami telah menyelamatkan kamu"],["مِنَ","daripada"],["ٱلْغَمِّ","kesusahan itu"],["وَفَتَنَّـٰكَ","dan Kami mencuba kamu"],["فُتُونًۭا ۚ","(dengan) percubaan"],["فَلَبِثْتَ","Kemudian kamu kekal"],["سِنِينَ","(beberapa) tahun"],["فِىٓ","dengan"],["أَهْلِ","kaum"],["مَدْيَنَ","(dari) Madyan"],["ثُمَّ","Kemudian"],["جِئْتَ","kamu datang"],["عَلَىٰ","di"],["قَدَرٍۢ","ketetapan (masa)"],["يَـٰمُوسَىٰ","Wahai Musa"]]],"2389":["(Dan Aku telah memilihmu) telah menjadikanmu sebagai orang yang terpilih (untuk diri-Ku) untuk mengemban risalah.",[["وَٱصْطَنَعْتُكَ","Dan aku (telah) memilih kamu"],["لِنَفْسِى","untuk diri aku sendiri"]]],"2390":["(Pergilah kamu beserta saudaramu) kepada manusia (dengan membawa ayat-ayat-Ku) yang berjumlah sembilan ayat (dan janganlah kamu berdua lalai) melalaikan (dalam mengingat-Ku) yaitu dengan cara bertasbih dan cara-cara lainnya.",[["ٱذْهَبْ","Pergi"],["أَنتَ","kamu"],["وَأَخُوكَ","dan abang kamu"],["بِـَٔايَـٰتِى","dengan Tanda-tanda-Ku"],["وَلَا","dan jangan"],["تَنِيَا","mengendur"],["فِى","dalam"],["ذِكْرِى","zikir aku"]]],"2391":["(Pergilah kamu berdua kepada Firaun, sesungguhnya dia telah melampaui batas) karena ia mengaku menjadi tuhan.",[["ٱذْهَبَآ","Pergilah kamu berdua"],["إِلَىٰ","kepada"],["فِرْعَوْنَ","Firaun"],["إِنَّهُۥ","Sesungguhnya dia"],["طَغَىٰ","(telah) melanggar"]]],"2392":["(Maka berbicaralah kamu berdua kepadanya dengan kata-kata yang lemah lembut) untuk menyadarkannya supaya jangan mengaku menjadi tuhan (mudah-mudahan ia ingat) yakni sadar dan mau menerimanya (atau takut\") kepada Allah lalu karenanya ia mau sadar. Ungkapan 'mudah-mudahan' berkaitan dengan pengetahuan Nabi Musa dan Nabi Harun. Adapun menurut pengetahuan Allah, maka Dia telah mengetahui bahwa Firaun tidak akan mau sadar dari perbuatannya.",[["فَقُولَا","Dan bercakap"],["لَهُۥ","kepadanya"],["قَوْلًۭا","satu perkataan"],["لَّيِّنًۭا","lemah lembut"],["لَّعَلَّهُۥ","mungkin dia"],["يَتَذَكَّرُ","boleh ambil iktibar"],["أَوْ","atau"],["يَخْشَىٰ","bertakwa"]]],"2393":["(Berkatalah mereka berdua, \"Ya Rabb kami! Sesungguhnya kami khawatir bahwa ia segera menyiksa kami) mengambil keputusan yang cepat untuk menyiksa kami (atau akan bertambah melampaui batas\") terhadap kami, yakni bertambah takabbur.",[["قَالَا","Mereka berkata"],["رَبَّنَآ","Wahai Tuhan kami"],["إِنَّنَا","Sesungguhnya kami"],["نَخَافُ","bertakwa"],["أَن","bahawa"],["يَفْرُطَ","dia akan menyegerakan"],["عَلَيْنَآ","terhadap kita"],["أَوْ","atau"],["أَن","bahawa"],["يَطْغَىٰ","dia akan melampaui batas"]]],"2394":["(Allah berfirman, \"Janganlah kamu berdua takut sesungguhnya Aku beserta kamu berdua) Aku akan membantu kamu berdua (Aku mendengar) apa yang dikatakannya (dan melihat) apa yang dikerjakannya.",[["قَالَ","Dia berkata"],["لَا","Jangan"],["تَخَافَآ ۖ","bertakwa"],["إِنَّنِى","Sesungguhnya, Aku"],["مَعَكُمَآ","dengan kamu berdua"],["أَسْمَعُ","aku dengar"],["وَأَرَىٰ","dan aku nampak"]]],"2395":["(Maka datanglah kamu berdua kepadanya dan katakanlah, \" Sesungguhnya kami berdua adalah utusan Rabbmu, maka lepaskanlah Bani Israel bersama kami) untuk berangkat ke negeri Syam (dan janganlah kamu menyiksa mereka) lepaskanlah mereka dari perbudakanmu yang telah kamu pekerjakan dengan kerja-kerja yang berat seperti menggali, membangun bangunan dan mengangkat barang-barang yang berat. (Sesungguhnya kami telah datang kepadamu dengan membawa bukti) yakni hujah (dari Rabbmu) yang membenarkan kerasulan kami. (Dan keselamatan itu dilimpahkan kepada orang yang mengikuti petunjuk) keselamatan dari azab bagi orang yang mengikutinya.",[["فَأْتِيَاهُ","Jadi pergilah kepadanya"],["فَقُولَآ","dan katakan"],["إِنَّا","Sesungguhnya kami"],["رَسُولَا","kedua-duanya (adalah) Rasul"],["رَبِّكَ","Tuhanmu"],["فَأَرْسِلْ","jadi hantar"],["مَعَنَا","dengan kami"],["بَنِىٓ","(the) Bani Israel"],["إِسْرَٰٓءِيلَ","(the) Bani Israel"],["وَلَا","dan jangan"],["تُعَذِّبْهُمْ ۖ","menyeksa mereka"],["قَدْ","Sesungguhnya"],["جِئْنَـٰكَ","kami datang kepada kamu"],["بِـَٔايَةٍۢ","dengan Tanda"],["مِّن","daripada"],["رَّبِّكَ ۖ","Tuhanmu"],["وَٱلسَّلَـٰمُ","Dan kedamaian"],["عَلَىٰ","pada"],["مَنِ","(satu) siapa"],["ٱتَّبَعَ","mengikuti"],["ٱلْهُدَىٰٓ","Petunjuk"]]],"2396":["(Sesungguhnya telah diwahyukan kepada kami, bahwa siksa itu ditimpakan kepada orang-orang yang mendustakan) apa yang kami datangkan ini (dan berpaling\") daripadanya. Kemudian Nabi Musa dan Nabi Harun mendatangi Firaun dan keduanya mengatakan semuanya itu kepadanya.",[["إِنَّا","Sesungguhnya kami"],["قَدْ","sesungguhnya"],["أُوحِىَ","ia telah didedahkan"],["إِلَيْنَآ","kepada kami"],["أَنَّ","bahawa"],["ٱلْعَذَابَ","azab"],["عَلَىٰ","(akan) pada"],["مَن","(satu) siapa"],["كَذَّبَ","menafikan"],["وَتَوَلَّىٰ","dan berpaling"]]],"2397":["(Berkata Firaun, \"Maka siapakah Rabbmu berdua, hai Musa?\") ungkapan ini ditujukan kepada Nabi Musa, karena dialah asal pembawa risalah Allah dan yang mendapatkan pemeliharaan dari-Nya.",[["قَالَ","Dia berkata"],["فَمَن","Kemudian siapa"],["رَّبُّكُمَا","(ialah) Tuhanmu"],["يَـٰمُوسَىٰ","Wahai Musa"]]],"2398":["(Musa berkata, \"Rabb kami ialah yang telah memberikan kepada tiap-tiap sesuatu) yakni tiap-tiap makhluk (bentuk kejadiannya) yang membedakannya daripada makhluk yang lain (kemudian memberinya petunjuk\") sehingga mengetahui makanan, minuman dan cara mengembangkan keturunannya serta hal-hal lain yang menyangkut kehidupannya.",[["قَالَ","Dia berkata"],["رَبُّنَا","Wahai Tuhan kami"],["ٱلَّذِىٓ","(ialah) Yang"],["أَعْطَىٰ","memberi"],["كُلَّ","(kepada) setiap"],["شَىْءٍ","perkara"],["خَلْقَهُۥ","bentuknya"],["ثُمَّ","kemudian"],["هَدَىٰ","Dia memberi petunjuk"]]],"2399":["(Berkatalah ia) yakni Firaun, (\"Maka bagaimanakah) keadaan (umat-umat) yakni bangsa-bangsa (yang dahulu?\") seperti kaum Nabi Nuh, kaum Nabi Hud, kaum Nabi Luth dan kaum Nabi Saleh, tentang penyembahan mereka kepada berhala-berhala.",[["قَالَ","Dia berkata"],["فَمَا","Kemudian apa"],["بَالُ","(adalah) kes"],["ٱلْقُرُونِ","(dari) generasi"],["ٱلْأُولَىٰ","(daripada) yang dahulu"]]],"2400":["(Ia berkata) yakni Nabi Musa, (\"Pengetahuan tentang itu) pengetahuan mengenai keadaan mereka berada (di sisi Rabbku, di dalam sebuah kitab) yaitu Lohmahfuz; Dia akan membalas mereka kelak di hari kiamat. (Tidak akan salah) tidak akan lenyap (dari Rabbku) segala sesuatu (dan tidak pula lupa) akan sesuatu.",[["قَالَ","Dia berkata"],["عِلْمُهَا","Pengetahuannya"],["عِندَ","(adalah) dengan"],["رَبِّى","Tuhanku"],["فِى","dalam"],["كِتَـٰبٍۢ ۖ","sebuah Rekod"],["لَّا","Tidak"],["يَضِلُّ","silap"],["رَبِّى","Tuhanku"],["وَلَا","dan bukan"],["يَنسَى","lupa"]]],"2401":["Dia (yang telah menjadikan bagi kalian) di antara sekian banyak makhluk-Nya (bumi sebagai hamparan) tempat berpijak (dan Dia memudahkan) mempermudah (bagi kalian di bumi itu jalan-jalan) tempat-tempat untuk berjalan (dan Dia menurunkan dari langit air hujan) yakni merupakan hujan. Allah berfirman menggambarkan apa yang telah disebutkan-Nya itu sebagai nikmat dari-Nya, kepada Nabi Musa dan dianggap sebagai khithab untuk penduduk Mekah. (Maka Kami tumbuhkan dengan air hujan itu berjenis-jenis) bermacam-macam (tumbuh-tumbuhan yang beraneka ragam). Lafal Syattaa ini menjadi kata sifat daripada lafal Azwaajan, maksudnya, yang berbeda-beda warna dan rasa serta lain-lainnya. Lafal syattaa ini adalah bentuk jamak dari lafal Syatiitun, wazannya sama dengan lafal Mardhaa sebagai jamak dari lafal Mariidhun. Ia berasal dari kata kerja Syatta artinya Tafarraqa atau berbeda-beda.",[["ٱلَّذِى","Dia yang"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلْأَرْضَ","bumi"],["مَهْدًۭا","(sebagai) katil"],["وَسَلَكَ","dan dimasukkan"],["لَكُمْ","bagi kamu"],["فِيهَا","di dalamnya"],["سُبُلًۭا","cara"],["وَأَنزَلَ","dan diturunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَأَخْرَجْنَا","kemudian Kami (telah) melahirkan"],["بِهِۦٓ","dengannya"],["أَزْوَٰجًۭا","berpasangan"],["مِّن","daripada"],["نَّبَاتٍۢ","tumbuhan"],["شَتَّىٰ","pelbagai"]]],"2402":["(Makanlah) daripadanya (dan gembalakanlah ternak kalian) di dalamnya. Lafal An'am adalah bentuk jamak dari lafal Ni'amun, yang artinya mencakup unta, sapi dan kambing. Dikatakan, Ru'tul An'aama atau aku menggembalakan ternak dan Ra'aituhaa atau aku telah menggembalakannya. Pengertian yang terkandung di dalam perintah ini menunjukkan makna ibahah atau boleh dan sekaligus sebagai pengingat akan nikmat-nikmat-Nya. Jumlah keseluruhan ayat ini menjadi kata keterangan keadaan daripada Dhamir yang terkandung di dalam lafal Akhrajnaa. Maksudnya, Kami memperbolehkan bagi kalian untuk memakannya dan mengembalakan ternak padanya. (sesungguhnya pada yang demikian itu) yakni pada hal-hal yang telah disebutkan dalam ayat ini (terdapat tanda-tanda) pelajaran-pelajaran (bagi orang-orang yang berakal) lafal Nuhaa adalah bentuk jamak dan lafal Nuhyah, wazannya sama dengan lafal Ghurfah yang jamaknya Ghuraf. Akal dinamakan dengan istilah ini, karena dapat mencegah pemiliknya dari melakukan perbuatan-perbuatan yang buruk.",[["كُلُوا۟","makan"],["وَٱرْعَوْا۟","dan padang rumput"],["أَنْعَـٰمَكُمْ ۗ","lembu kamu"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّأُو۟لِى","untuk pemilik"],["ٱلنُّهَىٰ","(daripada) kecerdasan"]]],"2403":["(Dari bumi itulah) dari tanah (Kami menjadikan kalian) dengan menciptakan nenek moyang kalian Adam daripadanya (dan kepadanya Kami akan mengembalikan kalian) kalian akan dikuburkan di dalamnya sesudah mati (dan daripadanya Kami akan mengeluarkan kalian) pada hari berbangkit (pada kali) untuk kali (yang lain) sebagaimana Kami mengeluarkan kalian pada permulaan penciptaan kalian.",[["۞ مِنْهَا","Daripadanya"],["خَلَقْنَـٰكُمْ","Kami mencipta kamu"],["وَفِيهَا","dan di dalamnya"],["نُعِيدُكُمْ","Kami akan pulangkan kamu"],["وَمِنْهَا","dan daripadanya"],["نُخْرِجُكُمْ","Kami akan membawa kamu keluar"],["تَارَةً","masa"],["أُخْرَىٰ","yang lain"]]],"2404":["(Dan sesungguhnya telah Kami perlihatkan kepadanya) kepada Firaun (ayat-ayat Kami semuanya) yang berjumlah sembilan ayat itu (maka ia mendustakan) nya dan menuduh bahwa ayat-ayat itu adalah sihir (dan ia enggan) untuk mengesakan Allah swt.",[["وَلَقَدْ","Dan sesungguhnya"],["أَرَيْنَـٰهُ","Kami menunjukkan kepadanya"],["ءَايَـٰتِنَا","Tanda-Tanda Kami"],["كُلَّهَا","kesemuanya"],["فَكَذَّبَ","tetapi dia menafikan"],["وَأَبَىٰ","dan menolak"]]],"2405":["(Berkata Firaun, \"Adakah kamu datang kepada kami untuk mengusir kami dari negeri kami) yakni dari negeri Mesir, kemudian kamu menjadi raja padanya (dengan sihirmu, hai Musa?\")",[["قَالَ","Dia berkata"],["أَجِئْتَنَا","Adakah kamu datang kepada kami"],["لِتُخْرِجَنَا","untuk menghalau kami keluar"],["مِنْ","daripada"],["أَرْضِنَا","tanah kita"],["بِسِحْرِكَ","dengan sihirmu"],["يَـٰمُوسَىٰ","Wahai Musa"]]],"2406":["(\"Dan kami pun pasti akan mendatangkan pula kepadamu sihir semacam itu) yang akan melawannya (maka buatlah suatu waktu antara kami dan kamu) untuk pertemuan itu (yang kami tidak akan menyalahinya dan tidak pula kamu, di suatu tempat) lafal Makaanan ini dinashabkan dengan mencabut huruf Jarnya, maksudnya, di tempat (yang pertengahan\") lafal Suwan dapat pula dibaca Siwan, artinya, tempat yang letaknya pertengahan, dari arah mana saja didatangi oleh kedua pihak jaraknya sama.",[["فَلَنَأْتِيَنَّكَ","Kemudian kami pasti akan menghasilkan untuk kamu"],["بِسِحْرٍۢ","sihir"],["مِّثْلِهِۦ","suka"],["فَٱجْعَلْ","Jadi buat"],["بَيْنَنَا","antara kita"],["وَبَيْنَكَ","dan antara kamu"],["مَوْعِدًۭا","temu janji"],["لَّا","tidak"],["نُخْلِفُهُۥ","kita akan gagalkannya"],["نَحْنُ","[kami]"],["وَلَآ","dan bukan"],["أَنتَ","kamu"],["مَكَانًۭا","(di) suatu tempat"],["سُوًۭى","malah"]]],"2407":["(Berkatalah ia) Nabi Musa, (\"Waktu untuk pertemuan kami dengan kalian itu adalah hari raya) yakni hari raya Firaun dan kaumnya, yang pada hari itu mereka berhias diri dan berkumpul-kumpul (dan hendaklah dikumpulkan manusia) semua penduduk negeri Mesir dikumpulkan (pada waktu matahari naik sepenggalah\") untuk menyaksikan apa yang akan terjadi.",[["قَالَ","Dia berkata"],["مَوْعِدُكُمْ","Janji temu kamu"],["يَوْمُ","(ada pada) hari"],["ٱلزِّينَةِ","(dari) perayaan itu"],["وَأَن","dan bahawa"],["يُحْشَرَ","akan dihimpunkan"],["ٱلنَّاسُ","manusia"],["ضُحًۭى","(pada) tengah hari"]]],"2408":["(Maka Firaun meninggalkan) pergi meninggalkan tempat itu (lalu ia mengatur tipu muslihatnya) ia mulai mengumpulkan para ahli sihirnya (kemudian ia datang) bersama mereka pada waktu yang telah ditentukan itu.",[["فَتَوَلَّىٰ","Kemudian pergi"],["فِرْعَوْنُ","Firaun"],["فَجَمَعَ","dan disatukan"],["كَيْدَهُۥ","rancangannya"],["ثُمَّ","kemudian"],["أَتَىٰ","datang"]]],"2409":["(Berkata Musa kepada mereka,) jumlah para ahli sihir Firaun ada tujuh puluh dua orang; setiap orang dari mereka memegang tali dan tongkat (\"Celakalah kalian) maksudnya semoga Allah menimpakan kecelakaan kepada kalian (janganlah kalian mengada-adakan kedustaan terhadap Allah) dengan menyekutukan seseorang bersama-Nya (maka Dia membinasakan kalian) ia dapat dibaca Fayushitakum dan Fayashitakum, artinya Dia akan membinasakan kalian, karena perbuatan musyrik itu (dengan siksa\") dari sisi-Nya. (Dan sesungguhnya telah kecewa) merugi (orang yang mengada-adakan kedustaan) terhadap Allah.",[["قَالَ","Berkata"],["لَهُم","kepada mereka"],["مُّوسَىٰ","Musa"],["وَيْلَكُمْ","Celakalah kamu"],["لَا","Jangan"],["تَفْتَرُوا۟","mencipta"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["كَذِبًۭا","satu pembohongan"],["فَيُسْحِتَكُم","supaya Dia tidak membinasakan kamu"],["بِعَذَابٍۢ ۖ","dengan hukuman"],["وَقَدْ","Dan sesungguhnya"],["خَابَ","dia gagal"],["مَنِ","yang"],["ٱفْتَرَىٰ","dicipta"]]],"2410":["(Maka mereka berbantah-bantahan di antara mereka tentang urusannya) yakni mengenai Nabi Musa dan saudaranya itu (dan mereka merahasiakan percakapan) mereka yang menyangkut Nabi Musa dan Nabi Harun.",[["فَتَنَـٰزَعُوٓا۟","Kemudian mereka mempertikaikan"],["أَمْرَهُم","(dalam) urusan mereka"],["بَيْنَهُمْ","antara mereka"],["وَأَسَرُّوا۟","dan mereka merahsiakan"],["ٱلنَّجْوَىٰ","perbualan peribadi itu"]]],"2411":["(Mereka berkata) kepada diri mereka sendiri, (\"Sesungguhnya dua orang ini) ungkapan Haadzaani dijadikan hujah atau alasan bagi sebagian ahli Nahwu yang menetapkan huruf Alif pada isim Tatsniyah dalam tiga keadaan. Akan tetapi menurut qiraat Abu 'Amr, lafal Haadzaani ini dibaca Haadzaini (adalah benar-benar ahli sihir yang hendak mengusir kalian, dari negeri kalian dengan sihirnya dan hendak melenyapkan kedudukan kalian yang utama\") lafal Mutslaa adalah bentuk Muannats dari lafal Amtsal; maksudnya yang mulia. Artinya, keduanya akan melenyapkan kemuliaan kalian, bila mereka berdua dibiarkan menang, kemudian kalian cenderung kepada keduanya.",[["قَالُوٓا۟","Mereka berkata"],["إِنْ","Sesungguhnya"],["هَـٰذَٰنِ","dua ini"],["لَسَـٰحِرَٰنِ","[dua] ahli silap mata"],["يُرِيدَانِ","mereka berniat"],["أَن","bahawa"],["يُخْرِجَاكُم","mereka menghalau kamu keluar"],["مِّنْ","daripada"],["أَرْضِكُم","tanah kamu"],["بِسِحْرِهِمَا","dengan sihir mereka"],["وَيَذْهَبَا","dan hapuskan"],["بِطَرِيقَتِكُمُ","dengan cara kamu"],["ٱلْمُثْلَىٰ","yang boleh dicontohi"]]],"2412":["(\"Maka himpunkanlah segala daya upaya kalian) semua kekuatan dan keahlian sihir kalian. Kalau dibaca Fajma'uu berasal dari lafal Jama'a dan kalau dibaca Fa-ajmi'uu berasal dari lafal Ajma'a, artinya kerahkanlah (kemudian datanglah dengan berbaris). Lafal Shaffan adalah Hal atau kata keterangan keadaan, maksudnya dalam keadaan berbaris (dan sesungguhnya beruntunglah) yakni akan memperoleh keuntungan (orang yang menang pada hari ini\") yakni yang dapat mengalahkan musuhnya.",[["فَأَجْمِعُوا۟","Jadi satukan"],["كَيْدَكُمْ","rancangan kamu"],["ثُمَّ","kemudian"],["ٱئْتُوا۟","datang"],["صَفًّۭا ۚ","(dalam) baris"],["وَقَدْ","Dan sesungguhnya"],["أَفْلَحَ","(akan) berjaya"],["ٱلْيَوْمَ","hari ini"],["مَنِ","yang"],["ٱسْتَعْلَىٰ","mengatasi"]]],"2413":["(Mereka berkata, \"Hai Musa!) Pilihlah (apakah kamu yang melemparkan dahulu) tongkatmu (atau kamikah orang yang mula-mula melemparkan?\") tongkat.",[["قَالُوا۟","Mereka berkata"],["يَـٰمُوسَىٰٓ","Wahai Musa"],["إِمَّآ","sama ada"],["أَن","[bahawa]"],["تُلْقِىَ","kamu buang"],["وَإِمَّآ","atau"],["أَن","[bahawa]"],["نَّكُونَ","kita akan jadi"],["أَوَّلَ","yang pertama"],["مَنْ","yang"],["أَلْقَىٰ","membaling"]]],"2414":["(Berkata Musa, \"Silakan kamu sekalian melemparkan\") maka mereka melemparkannya. (Maka tiba-tiba tali-tali dan tongkat-tongkat mereka) asal kata 'Ishiyyun adalah 'Ushuwwun, kemudian kedua huruf Wawu ditukar menjadi Ya, selanjutnya harakat huruf 'Ain dan Shad dikasrahkan, maka menjadi 'Ishiyyun (terbayang kepada Musa seakan-akan karena pengaruh sihir mereka ia) merupakan ular-ular (yang berjalan) atau merayap pada perutnya.",[["قَالَ","Dia berkata"],["بَلْ","Bahkan"],["أَلْقُوا۟ ۖ","kamu buang"],["فَإِذَا","Kemudian lihatlah"],["حِبَالُهُمْ","tali mereka"],["وَعِصِيُّهُمْ","dan kakitangan mereka"],["يُخَيَّلُ","nampaknya"],["إِلَيْهِ","kepadanya"],["مِن","oleh"],["سِحْرِهِمْ","sihir mereka"],["أَنَّهَا","bahawa mereka"],["تَسْعَىٰ","(sedang) bergerak"]]],"2415":["(Maka timbullah perasaan) muncul perasaan (takut dalam hati Musa) dia merasa takut karena ternyata sihir mereka sejenis dengan mukjizatnya, sehingga akibatnya akan mengaburkan mana yang hak dan mana yang batil di mata orang banyak, yang nantinya mereka tidak mau beriman, disebabkan kejadian itu.",[["فَأَوْجَسَ","Begitu terasa"],["فِى","dalam"],["نَفْسِهِۦ","dirinya sendiri"],["خِيفَةًۭ","ketakutan"],["مُّوسَىٰ","Musa"]]],"2416":["(Kami berkata) kepada Musa, (\"Janganlah kamu takut, sesungguhnya kamulah yang paling unggul) kamulah yang akan mengungguli mereka.",[["قُلْنَا","Kami berkata"],["لَا","Jangan"],["تَخَفْ","bertakwa"],["إِنَّكَ","Sesungguhnya kamu"],["أَنتَ","kamu"],["ٱلْأَعْلَىٰ","(akan) unggul"]]],"2417":["(Dan lemparkanlah apa yang ada di tangan kananmu) yakni tongkat (niscaya ia akan menelan) yakni akan melahap (apa yang mereka perbuat. Sesungguhnya apa yang mereka perbuat itu adalah tipu daya tukang sihir) ulah tukang sihir belaka. (Dan tidak akan menang tukang sihir itu, dari mana saja ia datang\") dengan sihirnya itu. Lalu Nabi Musa melemparkan tongkatnya, maka tongkat Nabi Musa itu menjadi ular yang besar dan menelan semua apa yang diperbuat oleh para ahli sihir.",[["وَأَلْقِ","Dan buang"],["مَا","apa"],["فِى","(berada) dalam"],["يَمِينِكَ","tangan kanan kamu"],["تَلْقَفْ","ia akan menelan"],["مَا","apa"],["صَنَعُوٓا۟ ۖ","mereka telah buat"],["إِنَّمَا","Hanya"],["صَنَعُوا۟","mereka (telah) buat"],["كَيْدُ","satu helah"],["سَـٰحِرٍۢ ۖ","(dari) ahli sihir"],["وَلَا","dan bukan"],["يُفْلِحُ","akan berjaya"],["ٱلسَّاحِرُ","ahli silap mata"],["حَيْثُ","di mana sahaja"],["أَتَىٰ","dia datang"]]],"2418":["(Lalu tukang-tukang sihir itu tersungkur dengan bersujud) yakni mereka bersujud kepada Allah swt. (seraya berkata, \"Kami telah percaya kepada Rabb Harun dan Musa\").",[["فَأُلْقِىَ","Maka dilemparkan ke bawah"],["ٱلسَّحَرَةُ","ahli sihir"],["سُجَّدًۭا","sujud"],["قَالُوٓا۟","Mereka berkata"],["ءَامَنَّا","Kami beriman"],["بِرَبِّ","di dalam Tuhan"],["هَـٰرُونَ","(dari) Harun"],["وَمُوسَىٰ","dan Musa"]]],"2419":["(Berkatalah) Firaun, (\"Apakah kalian telah beriman) dapat dibaca A-amantum dan Aamantum (kepada Musa sebelum aku memberi izin) sebelum aku mengizinkan (kepadamu sekalian. Sesungguhnya ia adalah pemimpin kalian) guru kalian (yang mengajarkan sihir kepada kalian. Maka sesungguhnya aku akan memotong tangan dan kaki kamu sekalian dengan bersilang secara bertimbal balik) lafal Min Khilaafin berkedudukan menjadi Hal, artinya secara bersilang, yaitu tangan kanan dengan kaki kiri (dan sesungguhnya aku akan menyalib kalian pada pangkal pohon kurma) yakni pada pohon kurma (dan sesungguhnya kalian akan mengetahui siapa di antara kita) yakni diri Firaun sendiri dan Rabb Nabi Musa (yang lebih pedih dan lebih kekal siksaannya\") bila ada orang yang melanggar kepadanya.",[["قَالَ","Dia berkata"],["ءَامَنتُمْ","kamu beriman"],["لَهُۥ","[kepada] dia"],["قَبْلَ","sebelum"],["أَنْ","[bahawa]"],["ءَاذَنَ","Aku memberi kebenaran"],["لَكُمْ ۖ","kepada kamu"],["إِنَّهُۥ","Sesungguhnya dia"],["لَكَبِيرُكُمُ","(ialah) ketua kamu"],["ٱلَّذِى","orang yang"],["عَلَّمَكُمُ","ajar kamu"],["ٱلسِّحْرَ ۖ","sihir itu"],["فَلَأُقَطِّعَنَّ","Jadi pasti aku akan potong"],["أَيْدِيَكُمْ","tangan kamu"],["وَأَرْجُلَكُم","dan kaki kamu"],["مِّنْ","daripada"],["خِلَـٰفٍۢ","sisi bertentangan"],["وَلَأُصَلِّبَنَّكُمْ","dan sesungguhnya Aku akan menyalibkan kamu"],["فِى","pada"],["جُذُوعِ","(the) batang"],["ٱلنَّخْلِ","(daripada) kurma"],["وَلَتَعْلَمُنَّ","dan pasti kamu akan mengetahuinya"],["أَيُّنَآ","yang mana antara kita"],["أَشَدُّ","(adalah) lebih parah"],["عَذَابًۭا","(dalam) hukuman"],["وَأَبْقَىٰ","dan lebih tahan lama"]]],"2420":["(Mereka berkata, \"Kami sekali-kali tidak akan mengutamakan kamu) kami tidak akan memilih kamu (daripada bukti-bukti yang nyata yang telah datang kepada kami) bukti-bukti yang menunjukkan kebenaran Nabi Musa (dan daripada Tuhan yang telah menciptakan kami) yakni Allah yang telah menjadikan kami. Kalimat ini dapat diartikan sebagai Qasam atau sumpah atau di'athafkan kepada lafal Ma (maka putuskanlah apa yang hendak kamu putuskan) artinya lakukanlah apa yang kamu ucapkan itu. (Sesungguhnya kamu hanya akan dapat memutuskan pada kehidupan di dunia saja) dinashabkannya lafal Al-Hayaatad Dun-yaa menunjukkan makna Ittisa', maksudnya peradilan di dunia dan kelak kamu akan mendapat balasan yang setimpal di akhirat akibat dari perbuatanmu itu.",[["قَالُوا۟","Mereka berkata"],["لَن","tidak pernah"],["نُّؤْثِرَكَ","kami akan lebih suka kamu"],["عَلَىٰ","atas"],["مَا","apa"],["جَآءَنَا","telah datang kepada kita"],["مِنَ","daripada"],["ٱلْبَيِّنَـٰتِ","bukti-bukti yang jelas"],["وَٱلَّذِى","dan Yang Esa"],["فَطَرَنَا ۖ","mencipta kita"],["فَٱقْضِ","Jadi dekri"],["مَآ","apa sahaja"],["أَنتَ","kamu"],["قَاضٍ ۖ","(sedang) memutuskan"],["إِنَّمَا","Hanya"],["تَقْضِى","kamu boleh membuat keputusan"],["هَـٰذِهِ","(untuk) ini"],["ٱلْحَيَوٰةَ","kehidupan"],["ٱلدُّنْيَآ","dunia"]]],"2421":["(Sesungguhnya kami telah beriman kepada Rabb kami, agar Dia mengampuni kesalahan-kesalahan kami) dari kemusyrikan dan dosa-dosa lainnya yang pernah kami lakukan (dan sihir yang telah kamu paksakan kepada kami melakukannya) mulai dari belajar sampai dengan mempraktekkannya untuk melawan Nabi Musa. (Dan Allah lebih baik) pahala-Nya daripada kamu, jika Dia ditaati (dan lebih kekal\") azab-Nya daripada kamu, jika didurhakai.",[["إِنَّآ","Sesungguhnya, [kami]"],["ءَامَنَّا","kami beriman"],["بِرَبِّنَا","dalam Tuhan kita"],["لِيَغْفِرَ","agar Dia mengampuni"],["لَنَا","bagi kami"],["خَطَـٰيَـٰنَا","dosa kita"],["وَمَآ","dan apa"],["أَكْرَهْتَنَا","kamu paksa kami"],["عَلَيْهِ","di atasnya"],["مِنَ","daripada"],["ٱلسِّحْرِ ۗ","sihir itu"],["وَٱللَّهُ","Dan Allah"],["خَيْرٌۭ","(adalah) Terbaik"],["وَأَبْقَىٰٓ","dan Kekal"]]],"2422":["Allah berfirman (Sesungguhnya barang siapa yang datang kepada Rabbnya dalam keadaan berdosa) yakni dalam keadaan kafir, sebagaimana Firaun (maka sesungguhnya baginya neraka Jahanam. Ia tidak mati di dalamnya) sehingga ia dapat istirahat dari kepedihan azab (dan tidak pula hidup) dengan kehidupan yang layak dan bermanfaat bagi dirinya.",[["إِنَّهُۥ","Sesungguhnya dia"],["مَن","yang"],["يَأْتِ","datang"],["رَبَّهُۥ","(kepada) Tuhannya"],["مُجْرِمًۭا","(sebagai) penjenayah"],["فَإِنَّ","maka sesungguhnya"],["لَهُۥ","baginya"],["جَهَنَّمَ","(ialah) Neraka"],["لَا","Tidak"],["يَمُوتُ","dia akan mati"],["فِيهَا","di dalamnya"],["وَلَا","dan bukan"],["يَحْيَىٰ","hidup"]]],"2423":["(Dan barang siapa yang datang kepada Rabbnya dalam keadaan beriman, lagi sungguh-sungguh telah beramal saleh) mengerjakan amal-amal fardu dan amal-amal sunah (maka mereka itulah orang-orang yang memperoleh kedudukan-kedudukan yang tinggi) lafal Al 'Ulaa adalah bentuk jamak daripada lafal Al 'Ulyaa muannats daripada lafal Al A'laa artinya yang paling tinggi.",[["وَمَن","Tetapi siapa pun"],["يَأْتِهِۦ","datang kepada-Nya"],["مُؤْمِنًۭا","(sebagai) seorang yang beriman"],["قَدْ","sesungguhnya"],["عَمِلَ","dia telah lakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan yang soleh"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["لَهُمُ","bagi mereka"],["ٱلدَّرَجَـٰتُ","(akan) pangkat"],["ٱلْعُلَىٰ","[yang] tinggi"]]],"2424":["(Yaitu surga Adn) sebagai tempat tinggalnya, lafal Jannaatu 'Adnin merupakan penjelasan daripada kedudukan tadi (yang mengalir sungai-sungai di bawahnya, mereka kekal di dalamnya. Dan itu adalah balasan bagi orang yang bersih) daripada dosa-dosa.",[["جَنَّـٰتُ","Taman-taman"],["عَدْنٍۢ","(dari) Eden"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","kekal selama-lamanya"],["فِيهَا ۚ","di dalamnya"],["وَذَٰلِكَ","Dan bahawa"],["جَزَآءُ","(ialah) ganjarannya"],["مَن","(untuk dia) siapa"],["تَزَكَّىٰ","menyucikan dirinya"]]],"2425":["(Dan sesungguhnya telah Kami wahyukan kepada Musa, \"Pergilah kalian dengan hamba-hamba-Ku di malam hari) jika dibaca Asri berasal dari Asraa dan jika dibaca Anisri dengan memakai Hamzah Washal, berasal dari kata Saraa, demikian menurut dua pendapat mengenainya, artinya: bawalah mereka pergi di malam hari dari negeri Mesir (maka buatlah untuk mereka) dengan tongkatmu itu (jalan yang kering di laut itu) artinya, jalan yang keadaannya telah kering. Nabi Musa mengerjakan apa yang telah diperintahkan kepadanya, lalu Allah mengeringkan jalan yang dilalui mereka, sehingga mereka dapat melaluinya (kamu tak usah khawatir akan tersusul) dapat terkejar oleh Firaun (dan tidak usah takut\") tenggelam.",[["وَلَقَدْ","Dan sesungguhnya"],["أَوْحَيْنَآ","Kami memberi inspirasi"],["إِلَىٰ","kepada"],["مُوسَىٰٓ","Musa"],["أَنْ","bahawa"],["أَسْرِ","Perjalanan pada waktu malam"],["بِعِبَادِى","dengan hamba-hamba-Ku"],["فَٱضْرِبْ","dan mogok"],["لَهُمْ","bagi mereka"],["طَرِيقًۭا","satu laluan"],["فِى","dalam"],["ٱلْبَحْرِ","laut"],["يَبَسًۭا","kering"],["لَّا","tidak"],["تَخَـٰفُ","takut"],["دَرَكًۭا","untuk dipintas"],["وَلَا","dan bukan"],["تَخْشَىٰ","sedang takut"]]],"2426":["(Maka Firaun dengan bala tentaranya mengejar mereka) Firaun pun ikut bersama dengan bala tentaranya (lalu mereka ditutup oleh laut) yakni laut itu melanda mereka (yang menenggelamkan mereka) akhirnya Firaun bersama dengan balatentaranya tenggelam.",[["فَأَتْبَعَهُمْ","Kemudian mengikuti mereka"],["فِرْعَوْنُ","Firaun"],["بِجُنُودِهِۦ","dengan pasukannya"],["فَغَشِيَهُم","tetapi menutupi mereka"],["مِّنَ","daripada"],["ٱلْيَمِّ","laut"],["مَا","apa"],["غَشِيَهُمْ","menutupi mereka"]]],"2427":["(Dan Firaun telah menyesatkan kaumnya) dengan menyeru mereka supaya menyembah dirinya (dan tidak memberi petunjuk) akan tetapi justru Firaun menjerumuskan mereka ke dalam kebinasaan, berbeda halnya dengan apa yang telah diungkapkannya, yang kemudian disitir oleh firman-Nya, yaitu: (Firaun berkata), \"Dan aku tiada menunjukkan kepada kalian melainkan jalan yang benar\" (Q.S. Al-Mukmin 29).",[["وَأَضَلَّ","Dan disesatkan"],["فِرْعَوْنُ","Firaun"],["قَوْمَهُۥ","umatnya"],["وَمَا","dan (tidak) tidak"],["هَدَىٰ","membimbing mereka"]]],"2428":["(Hai Bani Israel! Sesungguhnya Kami telah menyelamatkan kamu sekalian dari musuh kalian) yakni Firaun dengan menenggelamkannya (dan Kami telah mengadakan perjanjian dengan kamu sekalian di sebelah kanan bukit Thur) kemudian Kami memberikan kitab Taurat kepada Musa untuk diamalkan (dan Kami telah menurunkan kepada kamu sekalian manna dan salwa) yaitu dinamakan pula Taranjabin dan burung Sammani. Sedangkan orang-orang yang diseru dalam ayat ini adalah orang-orang Yahudi yang hidup di masa Nabi saw. Allah swt. berbicara kepada mereka seraya mengingatkan akan nikmat-nikmat yang telah dilimpahkan-Nya kepada kakek moyang mereka di zaman Nabi Musa. Dimaksud sebagai pendahuluan terhadap apa yang akan diungkapkan oleh Allah pada firman selanjutnya, yaitu:",[["يَـٰبَنِىٓ","Wahai Bani Israil"],["إِسْرَٰٓءِيلَ","Wahai Bani Israil"],["قَدْ","Sesungguhnya"],["أَنجَيْنَـٰكُم","Kami menghantar kamu"],["مِّنْ","daripada"],["عَدُوِّكُمْ","musuh kamu"],["وَوَٰعَدْنَـٰكُمْ","dan Kami telah mengadakan perjanjian dengan kamu"],["جَانِبَ","di (sisi)."],["ٱلطُّورِ","(dari) Gunung"],["ٱلْأَيْمَنَ","yang betul"],["وَنَزَّلْنَا","dan Kami turunkan"],["عَلَيْكُمُ","kepada kamu"],["ٱلْمَنَّ","iaitu Manna"],["وَٱلسَّلْوَىٰ","dan burung puyuh"]]],"2429":["(Makanlah di antara rezeki yang baik yang telah kami berikan kepada kalian) yakni nikmat yang telah dilimpahkan kepada kalian (dan janganlah melampaui batas padanya) seumpamanya kalian mengingkari nikmat-nikmat itu (yang menyebabkan kemurkaan-Ku menimpa kalian) bila dibaca Yahilla artinya wajib kemurkaan-Ku menimpa kalian. Dan jika dibaca Yahulla artinya, pasti kemurkaan-Ku menimpa kalian (Dan barang siapa ditimpa oleh kemurkaan-Ku) lafal Yahlil dapat pula dibaca Yahlul (maka sungguh binasalah ia) terjerumuslah ia ke dalam neraka.",[["كُلُوا۟","makan"],["مِن","daripada"],["طَيِّبَـٰتِ","(yang) perkara yang baik"],["مَا","yang"],["رَزَقْنَـٰكُمْ","Kami telah menyediakan kamu"],["وَلَا","dan jangan"],["تَطْغَوْا۟","langgar"],["فِيهِ","di dalamnya"],["فَيَحِلَّ","jangan sampai turun"],["عَلَيْكُمْ","ke atas kamu"],["غَضَبِى ۖ","Kemarahan aku"],["وَمَن","Dan sesiapa"],["يَحْلِلْ","pada siapa yang turun"],["عَلَيْهِ","pada siapa yang turun"],["غَضَبِى","Kemarahan aku"],["فَقَدْ","sesungguhnya"],["هَوَىٰ","dia (telah) binasa"]]],"2430":["(Dan sesungguhnya Aku Maha Pengampun bagi orang yang bertobat) dari kemusyrikan (dan beriman) mentauhidkan Allah (dan beramal saleh) yakni mengamalkan fardu dan sunah (kemudian tetap di jalan yang benar) tetap mengamalkan apa yang telah disebutkan di atas hingga umurnya habis.",[["وَإِنِّى","Tetapi sesungguhnya, Aku"],["لَغَفَّارٌۭ","Yang Maha Pengampun"],["لِّمَن","daripada sesiapa sahaja"],["تَابَ","bertaubat"],["وَءَامَنَ","dan beriman"],["وَعَمِلَ","dan melakukan"],["صَـٰلِحًۭا","benar (perbuatan)"],["ثُمَّ","kemudian"],["ٱهْتَدَىٰ","tetap dibimbing"]]],"2431":["(Mengapa kamu datang lebih cepat daripada kaummu) lebih cepat dari janji yang telah ditentukan untuk mengambil kitab Taurat (hai Musa?)",[["۞ وَمَآ","Dan apa"],["أَعْجَلَكَ","membuat kamu menyegerakan"],["عَن","daripada"],["قَوْمِكَ","orang kamu"],["يَـٰمُوسَىٰ","Wahai Musa"]]],"2432":["(Berkata Musa, \"Itulah mereka) dekat denganku berdatangan (sedang menyusul aku dan aku bersegera kepada-Mu, Ya Rabbku, supaya Engkau rida\") kepadaku, lebih daripada keridaan-Mu kepadaku sebelumnya. Sebelum menjawab pertanyaan Allah, Nabi Musa terlebih dahulu memohon maaf kepada-Nya, hal ini dia lakukan menurut dugaannya. Akan tetapi ternyata kenyataannya berbeda dengan apa yang diduga sebelumnya, yaitu ketika Allah berfirman pada ayat selanjutnya.",[["قَالَ","Dia berkata"],["هُمْ","mereka"],["أُو۟لَآءِ","(ada) dekat"],["عَلَىٰٓ","ke atas"],["أَثَرِى","jejak aku"],["وَعَجِلْتُ","dan aku bergegas"],["إِلَيْكَ","kepada kamu"],["رَبِّ","Tuhanku"],["لِتَرْضَىٰ","agar Engkau redha"]]],"2433":["(Berfirman Allah) subhaanahu wa taala, (\"Maka sesungguhnya Kami telah menguji kaummu sesudah kamu tinggalkan) sesudah kamu berpisah meninggalkan mereka (dan mereka telah disesatkan oleh Samiri\") yang menjerumuskan mereka sehingga mereka menyembah anak sapi.",[["قَالَ","Dia berkata"],["فَإِنَّا","Tetapi sesungguhnya, Kami"],["قَدْ","[sesungguhnya]"],["فَتَنَّا","Kami (telah) mencuba"],["قَوْمَكَ","orang kamu"],["مِنۢ","selepas kamu"],["بَعْدِكَ","selepas kamu"],["وَأَضَلَّهُمُ","dan telah menyesatkan mereka"],["ٱلسَّامِرِىُّ","Samiri"]]],"2434":["(Kemudian Musa kembali kepada kaumnya dengan marah) disebabkan tingkah laku kaumnya itu (dan bersedih hati) yakni dengan hati yang sangat sedih (Berkata Musa, \"Hai kaumku! Bukankah Rabb kalian telah menjanjikan kepada kalian suatu janji yang baik?) janji yang benar, bahwa Dia akan memberi kitab Taurat kepada kalian. (Maka apakah terasa lama masa yang berlalu itu bagi kalian) yakni masa perpisahanku dengan kalian (atau kalian menghendaki agar menimpa) (kalian kemurkaan dari Rabb kalian) disebabkan kalian menyembah anak sapi (dan kalian melanggar perjanjian kalian dengan aku?\") padahal sebelumnya kalian telah berjanji akan datang sesudahku, tetapi ternyata kalian tidak mau datang.",[["فَرَجَعَ","Kemudian Musa kembali"],["مُوسَىٰٓ","Kemudian Musa kembali"],["إِلَىٰ","kepada"],["قَوْمِهِۦ","umatnya"],["غَضْبَـٰنَ","marah"],["أَسِفًۭا ۚ","(dan) bersedih"],["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["أَلَمْ","tidak"],["يَعِدْكُمْ","janji kamu"],["رَبُّكُمْ","Tuhanmu"],["وَعْدًا","sebuah janji"],["حَسَنًا ۚ","kebaikan"],["أَفَطَالَ","Kemudian, memang nampak panjang"],["عَلَيْكُمُ","kepada kamu"],["ٱلْعَهْدُ","janji itu"],["أَمْ","atau"],["أَرَدتُّمْ","adakah kamu inginkan"],["أَن","bahawa"],["يَحِلَّ","turun"],["عَلَيْكُمْ","ke atas kamu"],["غَضَبٌۭ","(yang) Kemarahan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["فَأَخْلَفْتُم","jadi kamu patah"],["مَّوْعِدِى","(janji) kepada aku"]]],"2435":["(Mereka berkata, \"Kami sekali-kali tidak melanggar perjanjianmu dengan kemauan kami sendiri) lafal Bimalkinaa dapat pula dibaca Bimilkinaa atau Bimulkinaa, artinya dengan kehendak kami sendiri, atau dengan kemauan kami sendiri (tetapi kami disuruh membawa) dapat dibaca Hammalnaa atau Hummilnaa (beban-beban) yakni beban yang berat-berat (dari perhiasan kaum itu) yakni perhiasan milik kaum Firaun, yang mereka pinjam dahulu untuk keperluan pengantin, kini perhiasan itu masih berada di tangan mereka (maka kami telah melemparkannya) kami mencampakkannya ke dalam api atas perintah Samiri (dan demikian pula) sebagaimana kami melemparkannya (Samiri melemparkannya\") yakni ia pun ikut melemparkan perhiasan kaum Firaun yang masih ada padanya dan ia melemparkan pula tanah Yang ia ambil dari bekas teracak kuda malaikat Jibril dengan cara seperti berikut ini.",[["قَالُوا۟","Mereka berkata"],["مَآ","Tidak"],["أَخْلَفْنَا","kami pecah"],["مَوْعِدَكَ","janji dengan kamu"],["بِمَلْكِنَا","dengan kehendak kita"],["وَلَـٰكِنَّا","tetapi kita"],["حُمِّلْنَآ","[kami] telah dibuat untuk membawa"],["أَوْزَارًۭا","bebanan"],["مِّن","daripada"],["زِينَةِ","perhiasan"],["ٱلْقَوْمِ","(daripada) rakyat"],["فَقَذَفْنَـٰهَا","jadi kami melemparkannya"],["فَكَذَٰلِكَ","dan dengan demikian"],["أَلْقَى","melemparkan"],["ٱلسَّامِرِىُّ","Samiri"]]],"2436":["(Kemudian Samiri mengeluarkan untuk mereka anak lembu) yang berhasil ia cetak dari perhiasan itu (yang bertubuh) yakni ada daging dan darahnya (dan bersuara) suaranya dapat didengar. Anak lembu itu menjadi demikian disebabkan pengaruh tanah bekas teracak kuda malaikat Jibril, sehingga ia dapat hidup. Tanah itu diletakkan oleh Samiri ke dalam mulut lembu itu sesudah dicetak, lalu anak lembu itu menjadi hidup (maka mereka berkata) yakni Samiri dan para pengikutnya, (\"Inilah Tuhan kalian dan Tuhan Musa, tetapi ia telah lupa\") Musa telah lupa akan Tuhannya, bahwa Dia ada di sini, lalu pergi mencari-Nya. Maka Allah berfirman:",[["فَأَخْرَجَ","Kemudian dia melahirkan"],["لَهُمْ","bagi mereka"],["عِجْلًۭا","seekor anak lembu"],["جَسَدًۭا","badan"],["لَّهُۥ","ia telah"],["خُوَارٌۭ","bunyi merendah"],["فَقَالُوا۟","dan mereka berkata"],["هَـٰذَآ","Ini"],["إِلَـٰهُكُمْ","(ialah) tuhan kamu"],["وَإِلَـٰهُ","dan tuhan"],["مُوسَىٰ","(dari) Musa"],["فَنَسِىَ","tapi dia lupa"]]],"2437":["(Maka apakah mereka tidak memperhatikan bahwa patung anak lembu itu) lafal Allaa merupakan gabungan daripada Ann yang ditakhfif dari Anna dan Laa, sedangkan isim Ann tidak disebutkan, asalnya Annahu Laa, artinya, bahwasanya anak lembu itu (tidak dapat memberi) tidak dapat memberikan (jawaban kepada mereka) yakni tidak dapat menyahuti perkataan mereka (dan tidak dapat memberi kemudaratan kepada mereka) maksudnya tidak dapat menolak kemudaratan yang menimpa mereka (dan tidak pula kemanfaatan?) tidak dapat mendatangkan kemanfaatan buat mereka. Maksudnya, mengapa mereka menjadikannya sebagai Tuhan?",[["أَفَلَا","Kemudian, tidak"],["يَرَوْنَ","mereka lihat"],["أَلَّا","itu tidak"],["يَرْجِعُ","ia (boleh) kembali"],["إِلَيْهِمْ","kepada mereka"],["قَوْلًۭا","satu perkataan"],["وَلَا","dan bukan"],["يَمْلِكُ","memiliki"],["لَهُمْ","bagi mereka"],["ضَرًّۭا","sebarang kemudaratan"],["وَلَا","dan bukan"],["نَفْعًۭا","sebarang faedah"]]],"2438":["(Dan sesungguhnya Harun telah berkata kepada mereka sebelumnya) sebelum Nabi Musa kembali kepada mereka (\"Hai kaumku! Sesungguhnya kalian hanya diberi cobaan dengan anak lembu itu dan sesungguhnya Rabb kalian ialah Yang Maha Pemurah, maka ikutilah aku) yakni menyembah kepada-Nya (dan taatilah perintahku\") di dalam menyembah kepada-Nya.",[["وَلَقَدْ","Dan sesungguhnya"],["قَالَ","(telah) berkata"],["لَهُمْ","kepada mereka"],["هَـٰرُونُ","Harun"],["مِن","sebelum"],["قَبْلُ","sebelum"],["يَـٰقَوْمِ","Wahai kaumku"],["إِنَّمَا","Hanya"],["فُتِنتُم","kamu sedang diuji"],["بِهِۦ ۖ","olehnya"],["وَإِنَّ","dan sesungguhnya"],["رَبَّكُمُ","Tuhanmu"],["ٱلرَّحْمَـٰنُ","(adalah) Yang Maha Pemurah"],["فَٱتَّبِعُونِى","jadi ikut aku"],["وَأَطِيعُوٓا۟","dan taat"],["أَمْرِى","pesanan aku"]]],"2439":["(Mereka menjawab, \"Kami akan tetap) kami akan terus (menyembah patung anak lembu ini) (hingga Musa kembali kepada kami\").",[["قَالُوا۟","Mereka berkata"],["لَن","tidak pernah"],["نَّبْرَحَ","kami akan berhenti"],["عَلَيْهِ","berbakti kepadanya"],["عَـٰكِفِينَ","berbakti kepadanya"],["حَتَّىٰ","sehingga"],["يَرْجِعَ","pulangan"],["إِلَيْنَا","kepada kami"],["مُوسَىٰ","Musa"]]],"2440":["(Berkata Musa) setelah ia kembali kepada mereka, (\"Hai Harun! Apa yang menghalangi kamu ketika kamu melihat mereka sesat,) ketika mereka menyembah patung anak lembu itu.",[["قَالَ","Dia berkata"],["يَـٰهَـٰرُونُ","Wahai Harun"],["مَا","Apa"],["مَنَعَكَ","menghalang kamu"],["إِذْ","apabila"],["رَأَيْتَهُمْ","kamu melihat mereka"],["ضَلُّوٓا۟","sesat"]]],"2441":["(Sehingga kamu tidak mengikuti aku?) huruf Laa di sini Zaidah. (Maka apakah kamu telah sengaja mendurhakai perintahku?\") disebabkan kamu tinggal diam di antara orang-orang yang menyembah selain Allah swt.",[["أَلَّا","Itu tidak"],["تَتَّبِعَنِ ۖ","kamu ikut aku"],["أَفَعَصَيْتَ","Kemudian, adakah kamu ingkar"],["أَمْرِى","pesanan aku"]]],"2442":["(Berkatalah) Harun (\"Hai putra ibuku!) dapat dibaca Ummi dan Umma maksudnya ibuku, Nabi Harun sengaja menyebut nama ini untuk mengharapkan belas kasihan dari Nabi Musa (Janganlah kamu pegang janggutku) Nabi Musa memegang janggut Nabi Harun dengan tangan kirinya (dan jangan pula kepalaku) Nabi Musa memegang rambut kepala Nabi Harun dengan tangan kanannya sebagai pelampiasan kemarahannya (sesungguhnya aku khawatir) seandainya aku mengikutimu, maka pastilah akan mengikutiku pula segolongan orang-orang yang menyembah anak lembu itu (bahwa kamu akan berkata kepadaku, 'Kamu telah memecah belah antara Bani Israel) lalu kamu marah kepadaku (dan kamu tidak menunggu) (perintahku\") di dalam mengambil sikap.",[["قَالَ","Dia berkata"],["يَبْنَؤُمَّ","Wahai anak ibuku"],["لَا","Jangan"],["تَأْخُذْ","tangkap (aku)"],["بِلِحْيَتِى","oleh janggut aku"],["وَلَا","dan bukan"],["بِرَأْسِىٓ ۖ","oleh kepala aku"],["إِنِّى","Sesungguhnya aku"],["خَشِيتُ","[Aku] takut"],["أَن","bahawa"],["تَقُولَ","kamu akan berkata"],["فَرَّقْتَ","Kamu menyebabkan perpecahan"],["بَيْنَ","antara"],["بَنِىٓ","(the) Bani Israel"],["إِسْرَٰٓءِيلَ","(the) Bani Israel"],["وَلَمْ","dan bukan"],["تَرْقُبْ","kamu hormat"],["قَوْلِى","kata aku"]]],"2443":["Berkata Musa, \"Apakah yang mendorongmu) berbuat demikian (hai Samiri?\")",[["قَالَ","Dia berkata"],["فَمَا","Kemudian apa"],["خَطْبُكَ","(adalah) kes kamu"],["يَـٰسَـٰمِرِىُّ","Wahai Samiri"]]],"2444":["(Samiri menjawab, \"Aku mengetahui sesuatu yang mereka tidak mengetahuinya) dapat dibaca Yabshuruu dan Tabshuruu, artinya, aku mengetahui apa yang tidak mereka ketahui (maka aku ambil segenggam dari) tanah (bekas) jejak teracak kuda (rasul) yakni malaikat Jibril (lalu aku melemparkannya) yakni aku menaruhnya pada patung anak lembu yang telah dicetak (dan demikianlah telah menggoda) telah membujuk (aku hawa nafsuku\") untuk menaruhnya ke dalam tubuhnya, yaitu setelah terlebih dahulu aku mengambil segenggam tanah bekas jejak teracak kuda malaikat Jibril. Lalu tanah itu aku taruh ke dalam patung yang tidak bernyawa, hingga patung itu menjadi hidup bagaikan ada rohnya. Kemudian aku melihat bahwa kaummu meminta kepadamu untuk menjadikan tuhan buat mereka. Lalu hatiku menggodaku untuk menjadikan patung anak lembu itu sebagai tuhan mereka.",[["قَالَ","Dia berkata"],["بَصُرْتُ","aku rasa"],["بِمَا","apa"],["لَمْ","tidak"],["يَبْصُرُوا۟","mereka rasa"],["بِهِۦ","di dalamnya"],["فَقَبَضْتُ","jadi aku ambil"],["قَبْضَةًۭ","segenggam"],["مِّنْ","daripada"],["أَثَرِ","(the) trek"],["ٱلرَّسُولِ","(dari) Rasul"],["فَنَبَذْتُهَا","kemudian melemparkannya"],["وَكَذَٰلِكَ","dan dengan demikian"],["سَوَّلَتْ","dicadangkan"],["لِى","kepada aku"],["نَفْسِى","jiwa aku"]]],"2445":["(Berkata Musa) kepada Samiri, (\"Pergilah kamu) dari kalangan kami ini (maka sesungguhnya bagimu di dalam kehidupan di dunia ini) selama kamu hidup di dalamnya (hanya dapat mengatakan) kepada orang-orang yang kamu bertemu dengannya, ('Janganlah menyentuhku') janganlah kamu mendekat kepadaku. Dan disebutkan bahwa sejak saat itu Samiri mengembara tanpa tujuan dan jika ada seseorang menyentuhnya atau dia menyentuhnya, maka semuanya kena penyakit demam. (Dan sesungguhnya bagimu telah ada ketentuan waktu) bagi hukumanmu (yang kamu sekali-kali tidak dapat menghindarinya) jika dibaca Lan tukhlifahu artinya, kamu tidak dapat selamat dari azab itu. Dan jika dibaca Lan Tukhlafahu artinya, kamu dibangkitkan kelak di hari kiamat untuk diazab (dan lihatlah tuhanmu itu yang kamu tetap) lafal Zhalta asalnya dibaca Zhalilta, kemudian Lam yang pertama dibuang sehingga jadilah Zhalta artinya yang kamu selamanya (menyembah kepadanya) tetap menyembahnya. (Sesungguhnya kami akan membakarnya) dengan api (kemudian kami sungguh-sungguh akan menghambur-hamburkannya ke dalam laut) berupa abu yang berserakan terbawa oleh angin laut. Dan Nabi Musa mengerjakan apa yang telah dikatakannya itu setelah terlebih dahulu menyembelihnya.",[["قَالَ","Dia berkata"],["فَٱذْهَبْ","Kemudian pergi"],["فَإِنَّ","Dan sesungguhnya"],["لَكَ","bagi kamu"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["أَن","bahawa"],["تَقُولَ","kamu akan berkata"],["لَا","Jangan"],["مِسَاسَ ۖ","sentuh"],["وَإِنَّ","Dan sesungguhnya"],["لَكَ","bagi kamu"],["مَوْعِدًۭا","(adalah) temu janji"],["لَّن","tidak pernah"],["تُخْلَفَهُۥ ۖ","kamu akan gagal untuk (menyimpan)nya"],["وَٱنظُرْ","Dan lihat"],["إِلَىٰٓ","di"],["إِلَـٰهِكَ","tuhan kamu"],["ٱلَّذِى","itu yang"],["ظَلْتَ","kamu telah kekal"],["عَلَيْهِ","kepadanya"],["عَاكِفًۭا ۖ","berbakti"],["لَّنُحَرِّقَنَّهُۥ","Pasti kita akan membakarnya"],["ثُمَّ","kemudian"],["لَنَنسِفَنَّهُۥ","nescaya kami akan menghamburkannya"],["فِى","dalam"],["ٱلْيَمِّ","laut"],["نَسْفًا","(dalam) zarah"]]],"2446":["(Sesungguhnya Tuhan kalian hanyalah Allah yang tidak ada Tuhan selain Dia, pengetahuan-Nya meliputi segala sesuatu) lafal 'Ilman adalah Tamyiz yang dipindahkan dari bentuk Fa'ilnya, artinya, pengetahuan-Nya meliputi segala sesuatu.",[["إِنَّمَآ","Hanya"],["إِلَـٰهُكُمُ","Tuhanmu"],["ٱللَّهُ","(ialah) Allah"],["ٱلَّذِى","yang Satu"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","tetapi"],["هُوَ ۚ","Dia"],["وَسِعَ","Dia telah merangkumi"],["كُلَّ","semua"],["شَىْءٍ","benda"],["عِلْمًۭا","(dalam) pengetahuan"]]],"2447":["(Demikianlah) sebagaimana Kami telah mengisahkan cerita ini kepadamu, hai Muhammad (Kami kisahkan kepadamu sebagian kisah) berita (umat yang telah silam) yakni bangsa-bangsa di masa lampau (dan sesungguhnya telah Kami berikan kepadamu) yakni Kami telah memberimu (dari sisi Kami) yakni dari hadirat Kami (suatu peringatan) yakni Alquran.",[["كَذَٰلِكَ","Demikianlah"],["نَقُصُّ","Kami mengaitkan"],["عَلَيْكَ","kepada kamu"],["مِنْ","daripada"],["أَنۢبَآءِ","(the) berita"],["مَا","apa"],["قَدْ","telah mendahului"],["سَبَقَ ۚ","telah mendahului"],["وَقَدْ","Dan sungguh"],["ءَاتَيْنَـٰكَ","Kami telah memberi kamu"],["مِن","daripada"],["لَّدُنَّا","Kami"],["ذِكْرًۭا","satu Peringatan"]]],"2448":["(Barang siapa berpaling daripada Alquran) artinya ia tidak beriman kepada Alquran (maka sesungguhnya ia akan memikul dosa yang besar di hari kiamat) beban yang sangat berat berupa dosa-dosa.",[["مَّنْ","Siapa pun"],["أَعْرَضَ","berpaling"],["عَنْهُ","daripadanya"],["فَإِنَّهُۥ","maka sesungguhnya, dia"],["يَحْمِلُ","akan menanggung"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","(dari) Kebangkitan"],["وِزْرًا","suatu beban"]]],"2449":["(Mereka kekal di dalamnya) menanggung azab dosanya untuk selamanya. (Dan amat buruklah dosa itu sebagai beban bagi mereka di hari kiamat) lafal Himlan merupakan Tamyiz yang menafsirkan makna Dhamir dalam lafal Saa'a, sedangkan subjek yang dicelanya dibuang yaitu lafal Wizrahum, artinya dosa mereka. Huruf Lam yang ada pada lafal Lahum berfungsi untuk menerangkan. Kemudian lafal Yaumal Qiyaamah dijelaskan oleh ayat berikutnya, yaitu:",[["خَـٰلِدِينَ","Kekal selamanya"],["فِيهِ ۖ","di dalamnya"],["وَسَآءَ","dan jahat"],["لَهُمْ","bagi mereka"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["حِمْلًۭا","(sebagai) beban"]]],"2450":["(Yaitu di hari yang di waktu itu ditiup sangkakala) untuk tiupan yang kedua kalinya (dan Kami akan mengumpulkan orang-orang yang berdosa) yaitu orang-orang kafir (pada hari itu dengan mata yang biru muram) yakni mata mereka tampak membiru dan muka mereka tampak hitam karena muram.",[["يَوْمَ","(The) Hari"],["يُنفَخُ","akan ditiup"],["فِى","dalam"],["ٱلصُّورِ ۚ","Sangkakala"],["وَنَحْشُرُ","dan Kami akan mengumpulkan"],["ٱلْمُجْرِمِينَ","penjenayah"],["يَوْمَئِذٍۢ","hari itu"],["زُرْقًۭا","bermata biru"]]],"2451":["(Mereka berbisik-bisik di antara mereka sendiri) yaitu berbicara dengan suara yang pelan-pelan (\"Tidaklah) (kalian tinggal) di dunia (melainkan sepuluh) hari.\"",[["يَتَخَـٰفَتُونَ","Mereka merungut"],["بَيْنَهُمْ","sesama mereka"],["إِن","Tidak"],["لَّبِثْتُمْ","kamu kekal"],["إِلَّا","kecuali (untuk)"],["عَشْرًۭا","sepuluh"]]],"2452":["(Kami lebih mengetahui apa yang mereka katakan) dalam bisikan mereka itu. Maksudnya, keadaannya tidaklah seperti apa yang mereka katakan (ketika berkata orang yang paling tepat di antara mereka) yakni paling lurus (penilaiannya) sehubungan dengan hal ini, (\"Kalian tidak berdiam di dunia melainkan hanya sehari saja\") mereka menilai minim sekali masa tinggal mereka di dunia, hal ini disebabkan kengerian-kengerian yang mereka saksikan di alam akhirat.",[["نَّحْنُ","Kami"],["أَعْلَمُ","tahu yang terbaik"],["بِمَا","apa"],["يَقُولُونَ","mereka akan berkata"],["إِذْ","apabila"],["يَقُولُ","akan berkata"],["أَمْثَلُهُمْ","(yang) terbaik di antara mereka"],["طَرِيقَةً","(dalam) kelakuan"],["إِن","Tidak"],["لَّبِثْتُمْ","kamu kekal"],["إِلَّا","kecuali (untuk)"],["يَوْمًۭا","sehari"]]],"2453":["(Dan mereka bertanya kepadamu tentang gunung-gunung,) bagaimana jadinya di hari kiamat nanti? (maka katakanlah) kepada mereka (\"Rabbku akan menghancurkannya sehancur-hancurnya,) seumpamanya Dia meleburkannya menjadi debu yang lembut kemudian diterbangkan-Nya dengan angin.",[["وَيَسْـَٔلُونَكَ","Dan mereka bertanya kepada kamu"],["عَنِ","tentang"],["ٱلْجِبَالِ","pergunungan"],["فَقُلْ","jadi katakan"],["يَنسِفُهَا","Akan meletupkan mereka"],["رَبِّى","Tuhanku"],["نَسْفًۭا","(menjadi) zarah"]]],"2454":["(Maka Dia akan menjadikan bekas gunung-gunung itu datar) merata (dengan tanah) yakni rata sama sekali tiada bekasnya.",[["فَيَذَرُهَا","Kemudian Dia akan meninggalkannya"],["قَاعًۭا","satu tahap"],["صَفْصَفًۭا","kosong"]]],"2455":["(Tidak ada sedikit pun kamu lihat padanya tempat yang melengkung) tempat yang rendah (dan tidak pula tempat yang tinggi) tempat yang tinggi-tinggi.",[["لَّا","Tidak"],["تَرَىٰ","kamu akan melihat"],["فِيهَا","di dalamnya"],["عِوَجًۭا","sebarang kebengkokan"],["وَلَآ","dan bukan"],["أَمْتًۭا","sebarang lengkung"]]],"2456":["(Pada hari itu) pada hari ketika gunung-gunung itu dihancurkan (manusia mengikuti) manusia semuanya mengikuti sesudah mereka dibangunkan dari kuburannya (penyeru) yang menggiring mereka dengan suaranya ke padang Mahsyar, dia adalah malaikat Israfil. Dia mengatakan, \"Kemarilah kamu sekalian ke hadapan Tuhan Yang Maha Pemurah\" (dengan tidak berbelok-belok) sewaktu mereka menuruti panggilan suara itu. Atau dengan kata lain mereka tidak mempunyai kemampuan untuk tidak mengikuti anjuran suara itu (dan merendahlah) yakni menjadi tenanglah (semua suara kepada Tuhan Yang Maha Pemurah, maka kamu tidak mendengar melainkan hanya bisikan saja) suara telapak kaki mereka sewaktu berjalan menuju ke padang Mahsyar bagaikan suara teracak kaki unta bila berjalan.",[["يَوْمَئِذٍۢ","Pada Hari itu"],["يَتَّبِعُونَ","mereka akan mengikut"],["ٱلدَّاعِىَ","pemanggil"],["لَا","tidak"],["عِوَجَ","penyelewengan"],["لَهُۥ ۖ","daripadanya"],["وَخَشَعَتِ","Dan (akan) direndahkan"],["ٱلْأَصْوَاتُ","suara-suara"],["لِلرَّحْمَـٰنِ","untuk Yang Maha Pemurah"],["فَلَا","jadi tidak"],["تَسْمَعُ","kamu akan mendengar"],["إِلَّا","kecuali"],["هَمْسًۭا","bunyi samar"]]],"2457":["(Pada hari itu tidak berguna syafaat) seseorang (kecuali syafaat orang yang Allah Maha Pemurah telah memberi izin kepadanya) untuk memberi syafaat (dan Dia telah meridai perkataannya) seumpamanya orang yang diberi izin itu mengatakan, \"La Ilaaha Illallaah atau tidak ada Tuhan selain Allah.\"",[["يَوْمَئِذٍۢ","(Pada) hari itu"],["لَّا","tidak"],["تَنفَعُ","akan mendapat manfaat"],["ٱلشَّفَـٰعَةُ","syafaat itu"],["إِلَّا","kecuali"],["مَنْ","(kepada) siapa"],["أَذِنَ","telah memberi kebenaran"],["لَهُ","[kepadanya]"],["ٱلرَّحْمَـٰنُ","Yang Maha Pemurah"],["وَرَضِىَ","dan Dia telah menerima"],["لَهُۥ","baginya"],["قَوْلًۭا","satu perkataan"]]],"2458":["(Dia mengetahui apa yang ada di hadapan mereka) yaitu perkara-perkara akhirat (dan apa yang ada di belakang mereka) perkara-perkara dunia (sedangkan ilmu mereka tidak dapat meliputi ilmu-Nya\") yakni mereka tidak mengetahui hal tersebut.",[["يَعْلَمُ","Dia tahu"],["مَا","apa"],["بَيْنَ","(ada) di hadapan mereka"],["أَيْدِيهِمْ","(ada) di hadapan mereka"],["وَمَا","dan apa"],["خَلْفَهُمْ","(ada) di belakang mereka"],["وَلَا","manakala tidak"],["يُحِيطُونَ","mereka merangkumi"],["بِهِۦ","ia"],["عِلْمًۭا","(dalam) pengetahuan"]]],"2459":["(Dan tunduklah semua muka) tunduk merendahkan diri (kepada Tuhan Yang Hidup Kekal lagi Maha Memelihara) yakni Allah swt. (Dan sesungguhnya telah merugilah) (orang yang melakukan kelaliman) yakni kemusyrikan.",[["۞ وَعَنَتِ","Dan (akan) direndahkan"],["ٱلْوُجُوهُ","muka-muka"],["لِلْحَىِّ","sebelum Yang Hidup Kekal"],["ٱلْقَيُّومِ ۖ","yang Berdikari"],["وَقَدْ","Dan sesungguhnya"],["خَابَ","akan gagal"],["مَنْ","(dia) siapa"],["حَمَلَ","dibawa"],["ظُلْمًۭا","salah laku"]]],"2460":["(Dan barang siapa mengerjakan amal yang saleh) amal-amal ketaatan (dan ia dalam keadaan beriman, maka ia tidak khawatir akan diperlakukan tidak adil) dengan diberatkan dosanya (dan tidak pula akan pengurangan haknya) dikurangi pahala kebaikannya.",[["وَمَن","Tetapi (dia) yang"],["يَعْمَلْ","tidak"],["مِنَ","daripada"],["ٱلصَّـٰلِحَـٰتِ","perbuatan yang soleh"],["وَهُوَ","sedangkan dia"],["مُؤْمِنٌۭ","(adalah) seorang yang beriman"],["فَلَا","maka tidak"],["يَخَافُ","dia akan takut"],["ظُلْمًۭا","ketidakadilan"],["وَلَا","dan bukan"],["هَضْمًۭا","kekurangan"]]],"2461":["(Dan demikianlah) lafal Kadzaalika dia'athafkan kepada Kadzaalika Naqushshu pada ayat sembilan puluh sembilan. Artinya: Demikianlah sebagaimana diturunkannya apa yang telah Kami ceritakan tadi (Kami menurunkannya) Alquran (dalam bahasa Arab dan Kami telah menerangkan dengan berulang-ulang) (di dalamnya sebagian dari ancaman, agar mereka bertakwa) takut kepada kemusyrikan (atau agar ia menimbulkan) Alquran ini (pengajaran bagi mereka) melalui kebinasaan yang telah dialami oleh umat-umat sebelumnya sehingga mereka mengambil pelajaran daripadanya.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["أَنزَلْنَـٰهُ","Kami telah menurunkannya"],["قُرْءَانًا","(al-Quran)."],["عَرَبِيًّۭا","(dalam) bahasa Arab"],["وَصَرَّفْنَا","dan telah Kami jelaskan"],["فِيهِ","di dalamnya"],["مِنَ","daripada"],["ٱلْوَعِيدِ","amaran"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَتَّقُونَ","bertakwa"],["أَوْ","atau"],["يُحْدِثُ","ia boleh menyebabkan"],["لَهُمْ","[untuk] mereka"],["ذِكْرًۭا","zikir"]]],"2462":["(Maka Maha Tinggi Allah Raja Yang sesungguhnya) daripada apa yang dikatakan oleh orang-orang musyrik (dan janganlah kamu tergesa-gesa terhadap Alquran) sewaktu kamu membacanya (sebelum disempurnakan mewahyukannya kepadamu) sebelum malaikat Jibril selesai menyampaikannya (dan katakanlah, \"Ya Rabbku! Tambahkanlah kepadaku ilmu pengetahuan\") tentang Alquran, sehingga setiap kali diturunkan kepadanya Alquran, makin bertambah ilmu pengetahuannya.",[["فَتَعَـٰلَى","Begitu tinggi (di atas semua)"],["ٱللَّهُ","(ialah) Allah"],["ٱلْمَلِكُ","sang Raja"],["ٱلْحَقُّ ۗ","yang Benar"],["وَلَا","Dan jangan"],["تَعْجَلْ","cepatkan"],["بِٱلْقُرْءَانِ","dengan al-Quran"],["مِن","sebelum"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["يُقْضَىٰٓ","selesai"],["إِلَيْكَ","kepada kamu"],["وَحْيُهُۥ ۖ","wahyunya"],["وَقُل","dan katakan"],["رَّبِّ","Tuhanku"],["زِدْنِى","Tingkatkan aku"],["عِلْمًۭا","(dalam) pengetahuan"]]],"2463":["(Dan sesungguhnya telah Kami perintahkan kepada Adam) Kami telah berwasiat kepadanya, janganlah ia memakan buah pohon terlarang ini (dahulu) sebelum ia memakannya (maka ia lupa) melupakan perintah kami itu (dan tidak Kami dapati padanya kemauan yang kuat) keteguhan dan kesabaran daripada apa yang Kami larang ia mengerjakannya.",[["وَلَقَدْ","Dan sesungguhnya"],["عَهِدْنَآ","Kami membuat perjanjian"],["إِلَىٰٓ","dengan"],["ءَادَمَ","Adam"],["مِن","sebelum"],["قَبْلُ","sebelum"],["فَنَسِىَ","tapi dia lupa"],["وَلَمْ","dan bukan"],["نَجِدْ","Kami jumpa"],["لَهُۥ","dalam dirinya"],["عَزْمًۭا","keazaman"]]],"2464":["(Dan) ingatlah (ketika Kami berkata kepada Malaikat, \"Sujudlah kalian kepada Adam!\" Maka mereka sujud kecuali iblis) dia adalah bapaknya jin, dia dahulu berteman dengan para Malaikat dan ikut menyembah Allah bersama dengan para Malaikat (ia membangkang) tidak mau sujud kepada Nabi Adam; bahkan mengatakan sebagaimana yang telah disitir oleh firman-Nya; Iblis menjawab, \"Saya lebih baik daripadanya...\" (Q.S. Al-A'raf, 12).",[["وَإِذْ","Dan apabila"],["قُلْنَا","Kami berkata"],["لِلْمَلَـٰٓئِكَةِ","kepada para Malaikat"],["ٱسْجُدُوا۟","Sujud"],["لِـَٔادَمَ","kepada Adam"],["فَسَجَدُوٓا۟","kemudian mereka sujud"],["إِلَّآ","kecuali"],["إِبْلِيسَ","Iblis"],["أَبَىٰ","dia menolak"]]],"2465":["(Maka Kami berkata, \"Hai Adam! Sesungguhnya iblis ini adalah musuh bagimu dan bagi istrimu) yakni Siti Hawa (maka sekali-kali janganlah sampai ia mengeluarkan kamu berdua dari surga, yang menyebabkan kamu menjadi sengsara) hidup sengsara disebabkan terlebih dahulu kamu harus mencangkul, menanam, menuai, menumbuk, membuat roti dan lain sebagainya. Ungkapan sengsara di sini ditujukan hanya kepada Nabi Adam, disebabkan secara fitrah suami itu mencari nafkah buat istrinya.",[["فَقُلْنَا","Kemudian Kami berkata"],["يَـٰٓـَٔادَمُ","Wahai Adam"],["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["عَدُوٌّۭ","(adalah) musuh"],["لَّكَ","kepada kamu"],["وَلِزَوْجِكَ","dan kepada isteri kamu"],["فَلَا","Jadi tidak"],["يُخْرِجَنَّكُمَا","(biarkan) dia memandu kamu berdua"],["مِنَ","daripada"],["ٱلْجَنَّةِ","Syurga"],["فَتَشْقَىٰٓ","supaya (agar) kamu menderita"]]],"2466":["(Sesungguhnya kamu tidak akan kelaparan di dalamnya dan tidak akan telanjang). Lafal Allaa adalah gabungan daripada huruf An dan Laa.",[["إِنَّ","Sesungguhnya"],["لَكَ","bagi kamu"],["أَلَّا","itu tidak"],["تَجُوعَ","kamu akan lapar"],["فِيهَا","di dalamnya"],["وَلَا","dan bukan"],["تَعْرَىٰ","kamu akan telanjang"]]],"2467":["(Dan sesungguhnya kamu) baik dibaca Annaka atau Innaka, diathafkan kepada isimnya Inna pada ayat sebelumnya dan jumlah kalimat kelanjutannya ialah (tidak akan merasa dahaga di dalamnya) yakni tidak akan merasa haus (dan tidak pula akan ditimpa panas matahari di dalamnya\") yaitu sinar matahari di waktu dhuha tidak akan kamu alami lagi, karena di dalam surga tidak ada matahari.",[["وَأَنَّكَ","Dan bahawa kamu"],["لَا","tidak"],["تَظْمَؤُا۟","akan mengalami kehausan"],["فِيهَا","di dalamnya"],["وَلَا","dan bukan"],["تَضْحَىٰ","terdedah kepada panas matahari"]]],"2468":["(Kemudian setan membisikkan pikiran jahat kepadanya seraya berkata, \"Hai Adam! Maukah saya tunjukkan kepada kamu pohon keabadian) yaitu pohon yang barang siapa memakan buahnya akan hidup kekal (dan kerajaan yang tidak akan binasa?\") yakni kerajaan yang kekal.",[["فَوَسْوَسَ","Kemudian berbisik"],["إِلَيْهِ","kepadanya"],["ٱلشَّيْطَـٰنُ","Syaitan"],["قَالَ","dia berkata"],["يَـٰٓـَٔادَمُ","Wahai Adam"],["هَلْ","hendaklah"],["أَدُلُّكَ","Aku mengarahkan kamu"],["عَلَىٰ","kepada"],["شَجَرَةِ","(the) pokok"],["ٱلْخُلْدِ","(dari) Keabadian"],["وَمُلْكٍۢ","dan sebuah kerajaan"],["لَّا","tidak"],["يَبْلَىٰ","(yang akan) merosot"]]],"2469":["(Maka keduanya memakan) yakni Adam dan Hawa (dari buah pohon itu, lalu tampaklah bagi keduanya aurat-auratnya) yakni keduanya dapat melihat kemaluan masing-masing. Kedua aurat itu dinamakan kemaluan disebabkan jika kelihatan maka orang yang memilikinya menjadi malu (dan mulailah keduanya menutupi) keduanya menempelkan kepada (aurat masing-masing dengan daun-daun yang ada di surga) untuk menutupi auratnya (dan durhakalah Adam kepada Rabbnya dan sesatlah ia) disebabkan memakan buah pohon yang terlarang itu.",[["فَأَكَلَا","Kemudian mereka berdua makan"],["مِنْهَا","daripadanya"],["فَبَدَتْ","jadi menjadi jelas"],["لَهُمَا","kepada mereka"],["سَوْءَٰتُهُمَا","keaiban mereka"],["وَطَفِقَا","dan mereka mula"],["يَخْصِفَانِ","(untuk) mengikat"],["عَلَيْهِمَا","ke atas mereka"],["مِن","daripada"],["وَرَقِ","(the) daun"],["ٱلْجَنَّةِ ۚ","(dari) Syurga"],["وَعَصَىٰٓ","Dan Adam ingkar"],["ءَادَمُ","Dan Adam ingkar"],["رَبَّهُۥ","Tuhannya"],["فَغَوَىٰ","dan tersilap"]]],"2470":["(Kemudian Rabbnya memilihnya) yakni mendekatkannya ke sisi-Nya (maka Dia menerima tobatnya) sebelum Nabi Adam bertobat (dan memberinya petunjuk) supaya terus-menerus bertobat.",[["ثُمَّ","Kemudian"],["ٱجْتَبَـٰهُ","memilih dia"],["رَبُّهُۥ","Tuhannya"],["فَتَابَ","dan berpaling"],["عَلَيْهِ","kepadanya"],["وَهَدَىٰ","dan diberi petunjuk (dia)"]]],"2471":["(Allah berfirman, \"Turunlah kamu berdua) Adam dan Hawa berikut apa yang telah dikandung oleh kalian yaitu anak cucu kalian (daripadanya) dari surga (bersama-sama, sebagian kalian) sebagian keturunan kalian (menjadi musuh bagi sebagian yang lain) disebabkan sebagian dari mereka berbuat zalim terhadap sebagian yang lain. (Maka jika) lafal Imma ini asalnya terdiri dari In Syarthiyah yang diidgamkan kepada Ma Zaidah (jika datang kepada kalian petunjuk daripada-Ku maka barang siapa yang mengikuti petunjuk-Ku) yakni Alquran (maka ia tidak akan sesat) di dunia (dan tidak akan celaka) di akhirat nanti.",[["قَالَ","Dia berkata"],["ٱهْبِطَا","turunlah"],["مِنْهَا","daripadanya"],["جَمِيعًۢا ۖ","semua"],["بَعْضُكُمْ","sebahagian daripada kamu"],["لِبَعْضٍ","kepada orang lain"],["عَدُوٌّۭ ۖ","(sebagai) musuh"],["فَإِمَّا","Kemudian jika"],["يَأْتِيَنَّكُم","datang kepada kamu"],["مِّنِّى","daripada Aku"],["هُدًۭى","bimbingan"],["فَمَنِ","maka sesiapa"],["ٱتَّبَعَ","mengikuti"],["هُدَاىَ","bimbingan aku"],["فَلَا","maka tidak"],["يَضِلُّ","dia akan sesat"],["وَلَا","dan bukan"],["يَشْقَىٰ","menderita"]]],"2472":["(Dan barang siapa berpaling dari peringatan-Ku) yakni Alquran, yaitu dia tidak beriman kepadanya (maka sesungguhnya baginya penghidupan yang sempit) lafal Dhankan ini merupakan Mashdar artinya sempit. Ditafsirkan oleh sebuah hadis, bahwa hal ini menunjukkan tentang diazabnya orang kafir di dalam kuburnya (dan Kami akan mengumpulkannya) orang yang berpaling dari Alquran (pada hari kiamat dalam keadaan buta\") penglihatannya.",[["وَمَنْ","Dan sesiapa"],["أَعْرَضَ","berpaling"],["عَن","daripada"],["ذِكْرِى","zikir aku"],["فَإِنَّ","maka sesungguhnya"],["لَهُۥ","baginya"],["مَعِيشَةًۭ","(adalah) kehidupan"],["ضَنكًۭا","tertekan"],["وَنَحْشُرُهُۥ","dan Kami akan mengumpulkannya"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["أَعْمَىٰ","buta"]]],"2473":["(Berkatalah ia, \"Ya Rabbku! Mengapa Engkau menghimpun aku dalam keadaan buta, padahal dahulunya aku adalah orang yang melihat?\") yakni di kala ia hidup di dunia melihat tetapi di kala ia dibangkitkan hidup kembali buta.",[["قَالَ","Dia akan berkata"],["رَبِّ","Tuhanku"],["لِمَ","kenapa"],["حَشَرْتَنِىٓ","Kamu membesarkan aku"],["أَعْمَىٰ","buta"],["وَقَدْ","sementara [sesungguhnya]"],["كُنتُ","aku ada"],["بَصِيرًۭا","penglihatan"]]],"2474":["(Allah berfirman,) perkaranya (\"Demikianlah, telah datang kepadamu ayat-ayat Kami, maka kamu melupakannya) kamu meninggalkannya dan tidak mau beriman kepadanya (dan begitu pula) sebagaimana kamu lupa kepada ayat-ayat Kami (pada hari ini kamu pun dilupakan\") dibiarkan tinggal di dalam neraka.",[["قَالَ","Dia akan berkata"],["كَذَٰلِكَ","Demikianlah"],["أَتَتْكَ","datang kepada kamu"],["ءَايَـٰتُنَا","Tanda-Tanda Kami"],["فَنَسِيتَهَا ۖ","tetapi kamu melupakan mereka"],["وَكَذَٰلِكَ","dan dengan demikian"],["ٱلْيَوْمَ","hari ini"],["تُنسَىٰ","kamu akan dilupakan"]]],"2475":["(Dan demikianlah) sebagaimana Kami membalas kepada orang yang berpaling daripada Alquran (Kami membalas orang yang melampaui batas) orang yang musyrik (dan tidak percaya kepada ayat-ayat Rabbnya. Dan sesungguhnya azab di akhirat itu lebih berat) daripada azab di dunia dan azab kubur (dan lebih kekal) lebih abadi.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["نَجْزِى","Kami membalas"],["مَنْ","(dia) siapa"],["أَسْرَفَ","melanggar"],["وَلَمْ","dan bukan"],["يُؤْمِنۢ","beriman"],["بِـَٔايَـٰتِ","dalam (the) Tanda-tanda"],["رَبِّهِۦ ۚ","(dari) Tuhannya"],["وَلَعَذَابُ","Dan sesungguhnya azab"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["أَشَدُّ","(adalah) lebih parah"],["وَأَبْقَىٰٓ","dan lebih tahan lama"]]],"2476":["(Maka tidakkah menjadi petunjuk) yakni tidak jelas (bagi mereka) orang-orang kafir Mekah (berapa banyak) lafal Kam di sini adalah kalimat berita yang berkedudukan menjadi maf'ul (Kami membinasakan) sudah berapa banyak telah Kami binasakan (umat-umat sebelum mereka) umat-umat terdahulu disebabkan mereka mendustakan Rasul-rasul (padahal mereka berjalan) Lafal Yamsyuuna ini menjadi Hal daripada Dhamir Lahum (melewati peninggalan umat-umat itu?) sewaktu mereka berniaga ke negeri Syam dan negeri-negeri yang lain, seharusnya mereka mengambil pelajaran daripadanya. Disebutkan pengertian membinasakan, hal ini diambil dari Fi'il atau kata kerjanya tanpa memakai huruf Mashdar demi memelihara keselarasan makna, maka hal ini tidak dilarang. (Sesungguhnya pada yang demikian itu terdapat tanda-tanda) pelajaran-pelajaran (bagi orang-orang yang berakal) yakni bagi mereka yang berakal.",[["أَفَلَمْ","Kemudian belum"],["يَهْدِ","ia dibimbing"],["لَهُمْ","[untuk] mereka"],["كَمْ","berapa ramai"],["أَهْلَكْنَا","Kami (telah) memusnahkan"],["قَبْلَهُم","sebelum mereka"],["مِّنَ","daripada"],["ٱلْقُرُونِ","generasi"],["يَمْشُونَ","(sambil) mereka berjalan"],["فِى","dalam"],["مَسَـٰكِنِهِمْ ۗ","kediaman mereka"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّأُو۟لِى","untuk pemilik"],["ٱلنُّهَىٰ","(daripada) kecerdasan"]]],"2477":["(Dan sekiranya tidak ada suatu ketetapan dari Rabbmu yang telah terdahulu) untuk menangguhkan azab daripada mereka hingga hari kemudian (niscayalah) pembinasaan itu (pasti) menimpa mereka sejak di dunia (dan waktu yang telah ditentukan) waktu yang telah dipastikan bagi azab mereka. Kalimat ayat ini di'athafkan kepada Dhamir yang terkandung di dalam lafal Kaana dan menjadi pemisah di antara keduanya adalah Khabar Kaana yang berfungsi sebagai pengukuh makna. Maksudnya; dan di hari kemudian, azab akan menimpa mereka pula.",[["وَلَوْلَا","Dan jika tidak"],["كَلِمَةٌۭ","(untuk) Firman"],["سَبَقَتْ","(yang) mendahului"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["لَكَانَ","pasti (akan) telah"],["لِزَامًۭا","satu kewajipan"],["وَأَجَلٌۭ","dan istilah"],["مُّسَمًّۭى","ditentukan"]]],"2478":["(Maka sabarlah kamu atas apa yang mereka katakan) hanya saja ayat ini dimansukh oleh ayat berperang (dan bertasbihlah) salatlah (dengan memuji Rabbmu) lafal Bihamdi Rabbika merupakan Hal atau kata keterangan keadaan, maksudnya seraya memuji-Nya (sebelum terbit matahari) yaitu salat Subuh (dan sebelum terbenamnya) salat Asar (dan pada waktu-waktu di malam hari) saat-saat malam hari (bertasbih pulalah) yaitu salat Magrib dan salat Isyaklah kamu (dan pada waktu-waktu di siang hari) ia di'athafkan secara Mahal kepada lafal Ana yang dinashabkan. Maksudnya salat Zuhurlah kamu; karena waktu salat Zuhur itu mulai sejak bergeser matahari dari garis pertengahan langit; yaitu bergesernya matahari dari bagian pertengahan pertama menuju kepada bagian pertengahan kedua (supaya kamu merasa senang) dengan pahala yang akan diberikan kepadamu.",[["فَٱصْبِرْ","Jadi bersabarlah"],["عَلَىٰ","atas"],["مَا","apa"],["يَقُولُونَ","mereka berkata"],["وَسَبِّحْ","dan bertasbih"],["بِحَمْدِ","dengan pujian"],["رَبِّكَ","Tuhanmu"],["قَبْلَ","sebelum"],["طُلُوعِ","(yang) meningkat"],["ٱلشَّمْسِ","(dari) matahari"],["وَقَبْلَ","dan sebelum ini"],["غُرُوبِهَا ۖ","tetapannya"],["وَمِنْ","dan daripada"],["ءَانَآئِ","(the) jam"],["ٱلَّيْلِ","(dari) malam"],["فَسَبِّحْ","dan bertasbih"],["وَأَطْرَافَ","(di) hujung"],["ٱلنَّهَارِ","(dari) hari itu"],["لَعَلَّكَ","supaya kamu"],["تَرْضَىٰ","berpuas hati"]]],"2479":["(Dan janganlah kamu tujukan kedua matamu kepada apa yang telah Kami berikan kepada golongan-golongan) yakni berbagai macam golongan (dari mereka, sebagai bunga kehidupan dunia) sebagai perhiasan dan kesemarakan kehidupan dunia (Kami cobai mereka dengannya) seumpamanya mereka makin kelewat batas karenanya. (Dan karunia Rabbmu) di surga (adalah lebih baik) daripada keduniaan yang diberikan kepada mereka (dan lebih kekal) yakni lebih abadi.",[["وَلَا","Dan jangan"],["تَمُدَّنَّ","memanjangkan"],["عَيْنَيْكَ","mata kamu"],["إِلَىٰ","ke arah"],["مَا","apa"],["مَتَّعْنَا","Kami telah memberi untuk kesenangan"],["بِهِۦٓ","[dengannya]"],["أَزْوَٰجًۭا","berpasangan"],["مِّنْهُمْ","daripada mereka"],["زَهْرَةَ","(the) kemegahan"],["ٱلْحَيَوٰةِ","(dari) kehidupan"],["ٱلدُّنْيَا","dunia"],["لِنَفْتِنَهُمْ","supaya Kami menguji mereka"],["فِيهِ ۚ","di dalamnya"],["وَرِزْقُ","Dan (peruntukan)."],["رَبِّكَ","Tuhanmu"],["خَيْرٌۭ","(lebih) baik"],["وَأَبْقَىٰ","dan lebih tahan lama"]]],"2480":["(Dan perintahkanlah kepada keluargamu mendirikan salat dan bersabarlah kamu) teguh dan sabarlah kamu (dalam mengerjakannya. Kami tidak meminta kepadamu) tidak membebankan kepadamu (rezeki) untuk dirimu dan tidak pula untuk orang lain (Kamilah yang memberi rezeki kepadamu. Dan akibat yang baik itu) yakni pahala surga (hanyalah bagi ketakwaan) bagi orang yang bertakwa.",[["وَأْمُرْ","Dan menyuruh"],["أَهْلَكَ","(pada) keluarga kamu"],["بِٱلصَّلَوٰةِ","solat"],["وَٱصْطَبِرْ","dan teguh hati"],["عَلَيْهَا ۖ","di dalamnya"],["لَا","Tidak"],["نَسْـَٔلُكَ","Kami bertanya kepada kamu"],["رِزْقًۭا ۖ","(untuk) peruntukan"],["نَّحْنُ","Kami"],["نَرْزُقُكَ ۗ","menyediakan (untuk) kamu"],["وَٱلْعَـٰقِبَةُ","dan hasilnya"],["لِلتَّقْوَىٰ","(adalah) untuk orang-orang yang soleh"]]],"2481":["(Dan mereka berkata,) orang-orang musyrik (\"Mengapa tidak) tidakkah (ia datang kepada kami) yakni Nabi Muhammad (dengan membawa bukti dari Rabbnya?\") sesuai dengan apa yang diminta mereka. (Dan apakah belum datang kepada mereka) dapat dibaca Ta-tihim dan Ya-tihim (bukti yang nyata) yakni penjelasan (dari apa yang tersebut di dalam kitab-kitab yang terdahulu?) yang kesemuanya disebutkan oleh Alquran, yaitu mengenai berita umat-umat terdahulu yang telah dibinasakan disebabkan mereka mendustakan para Rasul.",[["وَقَالُوا۟","Dan mereka berkata"],["لَوْلَا","kenapa tidak"],["يَأْتِينَا","dia membawa kita"],["بِـَٔايَةٍۢ","satu tanda"],["مِّن","daripada"],["رَّبِّهِۦٓ ۚ","Tuhannya"],["أَوَلَمْ","belum"],["تَأْتِهِم","datang kepada mereka"],["بَيِّنَةُ","bukti"],["مَا","apa"],["فِى","(telah) masuk"],["ٱلصُّحُفِ","Kitab Suci"],["ٱلْأُولَىٰ","yang dahulu"]]],"2482":["(Dan sekiranya Kami binasakan mereka dengan suatu azab sebelum ia diutus) sebelum Rasulullah diutus (tentulah mereka berkata) di hari kiamat nanti, (\"Ya Rabb kami! Mengapa tidak) (Engkau utus seorang Rasul kepada kami, lalu kami mengikuti ayat-ayat Engkau) yang dibawa olehnya (sebelum kami menjadi hina) di hari kiamat (dan rendah?\") dijebloskan ke dalam neraka Jahanam.",[["وَلَوْ","Dan jika"],["أَنَّآ","Kami"],["أَهْلَكْنَـٰهُم","(telah) membinasakan mereka"],["بِعَذَابٍۢ","dengan hukuman"],["مِّن","sebelum dia"],["قَبْلِهِۦ","sebelum dia"],["لَقَالُوا۟","nescaya mereka (akan) berkata"],["رَبَّنَا","Wahai Tuhan kami"],["لَوْلَآ","kenapa tidak"],["أَرْسَلْتَ","Kamu hantar"],["إِلَيْنَا","kepada kami"],["رَسُولًۭا","seorang Rasul"],["فَنَتَّبِعَ","jadi kami (boleh) ikut"],["ءَايَـٰتِكَ","Tanda-tanda kamu"],["مِن","sebelum"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["نَّذِلَّ","kami dihina"],["وَنَخْزَىٰ","dan terhina"]]],"2483":["(Katakanlah:) kepada mereka, (\"Masing-masing) di antara kami dan kalian (menanti) menunggu apa yang bakal terjadi padanya di hari kiamat itu (maka nantikanlah oleh kamu sekalian! Kelak kalian akan mengetahui) di hari kiamat itu (siapa yang menempuh jalan) yakni tuntunan (yang lurus) yang tidak menyimpang (dan siapa yang telah mendapat petunjuk\") sehingga selamat dari kesesatan, kami ataukah kalian?",[["قُلْ","Katakanlah"],["كُلٌّۭ","setiap satu"],["مُّتَرَبِّصٌۭ","(sedang) menunggu"],["فَتَرَبَّصُوا۟ ۖ","jadi tunggu"],["فَسَتَعْلَمُونَ","Kemudian kamu akan tahu"],["مَنْ","yang"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلصِّرَٰطِ","(dari) jalan"],["ٱلسَّوِىِّ","[yang] genap"],["وَمَنِ","dan siapa"],["ٱهْتَدَىٰ","dibimbing"]]]});